(10101101, 101011, 'P1-C1-L1-O01', null, 1, 'ان يعرف الطالب الفيزياء', 'أن يعرّف الطالب الفيزياء.', '[]'::jsonb, 'أن يعرّف الطالب الفيزياء.', 'إضافة همزة «أن»، وتشكيل «يعرّف» لأن المقصود التعريف، وإضافة نقطة الختام.', 'إملائي', 'يعتمد بعد التعديل', 'تذكر', 'حقائق ومصطلحات', '["الفيزياء"]'::jsonb, null, '[10,25]'::jsonb, 'مغطى', 'ص10 «ما الفيزياء؟»: «الفيزياء فرع من فروع العلم يُعنى بدراسة العالم الطبيعي: الطاقة والمادة وكيفية ارتباطهما»؛ ص25 المفاهيم الرئيسة: «الفيزياء علم دراسة المادة والطاقة والعلاقة بينهما».', null, 'approved', '2026-11-16'::timestamptz),
(10101102, 101011, 'P1-C1-L1-O02', null, 2, 'ان يذكر الطالب مجالات الدراسة لعلماء الفيزياء', 'أن يذكر الطالب مجالات الدراسة لعلماء الفيزياء.', '[]'::jsonb, 'أن يذكر الطالب مجالات الدراسة لعلماء الفيزياء.', 'إضافة همزة «أن»، وإضافة نقطة الختام.', 'إملائي', 'يعتمد بعد التعديل', 'تذكر', 'حقائق ومصطلحات', '["علماء الفيزياء","مجالات الدراسة"]'::jsonb, null, '[10]'::jsonb, 'مغطى', 'ص10: «فعلماء الفيزياء يدرسون طبيعة حركة الإلكترونات والصواريخ، والطاقة في الموجات الضوئية والصوتية، وفي الدوائر الكهربائية، ومكونات الكون وأصل المادة».', null, 'approved', '2026-11-16'::timestamptz),
(10101103, 101011, 'P1-C1-L1-O03', null, 3, 'ان يعدد الطالب مجالات ومهن دارسو الفيزياء', 'أن يعدّد الطالب مجالات عمل دارسي الفيزياء ومهنهم.', '[]'::jsonb, 'أن يعدّد الطالب مجالات عمل دارسي الفيزياء ومهنهم.', 'إضافة همزة «أن»، وتصحيح «دارسو» إلى «دارسي» لأنها مضاف إليه مجرور، وضبط العبارة بـ«مجالات عمل ... ومهنهم» كما في نص الكتاب.', 'لغوي', 'يعتمد بعد التعديل', 'تذكر', 'حقائق ومصطلحات', '["دارسو الفيزياء","المهن المرتبطة بالفيزياء"]'::jsonb, null, '[10]'::jsonb, 'مغطى', 'ص10: «يعمل دارسو الفيزياء في مجالات ومهن عديدة؛ فبعضهم يعمل باحثًا في الجامعات والكليات أو في المصانع ومراكز الأبحاث، والبعض الآخر يعمل في المجالات الأخرى المرتبطة مع علم الفيزياء، ومنها الفلك والهندسة وعلم الحاسب ومجال التعليم والصيدلة... الأعمال التجارية والمالية».', null, 'approved', '2026-11-16'::timestamptz),
(10101104, 101011, 'P1-C1-L1-O04', null, 4, 'ان يوضح الطالب كيفية استخدام الفيزياء للرياضيات', 'أن يوضّح الطالب أهمية استخدام الرياضيات في الفيزياء.', '[]'::jsonb, 'أن يوضّح الطالب أهمية استخدام الرياضيات في الفيزياء.', 'إضافة همزة «أن»، وإعادة صياغة «كيفية استخدام الفيزياء للرياضيات» الركيكة إلى «أهمية استخدام الرياضيات في الفيزياء» كما يعرضها الكتاب (لغة للتعبير عن القوانين، وأداة لنمذجة المشاهدات ووضع التوقعات).', 'صياغة', 'يعتمد بعد التعديل', 'فهم', 'مفاهيم', '["الرياضيات في الفيزياء","المعادلات الرياضية","الرسوم البيانية"]'::jsonb, null, '[10,15,26]'::jsonb, 'مغطى', 'ص10 «الرياضيات في الفيزياء»: يستخدم العلماء الرياضيات «بوصفها لغة قادرة على التعبير عن القوانين والظواهر الفيزيائية»، و«المعادلات الرياضية أداة مهمة لنمذجة المشاهدات ووضع التوقعات»، والرسوم البيانية (الشكل 1-1)؛ ص15 مراجعة 1-1 السؤال 5؛ ص26 السؤال 22.', null, 'approved', '2026-11-16'::timestamptz),
(10101105, 101011, 'P1-C1-L1-O05', null, 5, 'ان يجري الطالب العمليات الحسابية وفقا للقوانين الفيزيائية ، واستخدام التعبير العلمي.', 'أن يجري الطالب العمليات الحسابية وفقًا للقوانين الفيزيائية، وباستخدام التعبير العلمي.', '[]'::jsonb, 'أن يجري الطالب العمليات الحسابية وفقًا للقوانين الفيزيائية، وباستخدام التعبير العلمي.', 'إضافة همزة «أن»، وتنوين «وفقًا»، وتصحيح العطف «واستخدام» إلى «وباستخدام» ليتسق التركيب كما في أهداف الدرس بالكتاب ص9، وحذف المسافة قبل الفاصلة.', 'لغوي', 'يعتمد بعد التعديل', 'تطبيق', 'حل مسائل', '["القوانين الفيزيائية","العمليات الحسابية","التعبير العلمي"]'::jsonb, null, '[9,11,27]'::jsonb, 'مغطى', 'ص9 أهداف الدرس: «تجري العمليات الحسابية وفقًا للقوانين الفيزيائية، وباستخدام التعبير العلمي»؛ ص11 مثال 1 (حساب مقاومة مصباح من V = IR) ومسائل تدريبية 1–4؛ ص27 السؤال 32 (F = mg).', null, 'approved', '2026-11-16'::timestamptz),
(10101106, 101011, 'P1-C1-L1-O06', null, 6, 'ان يكتب الطالب المعادلات الرياضية في الفيزياء بدلالات مختلفة.', 'أن يعيد الطالب كتابة المعادلة الفيزيائية لإيجاد كمية مجهولة بدلالة الكميات الأخرى.', '[]'::jsonb, 'أن يعيد الطالب كتابة المعادلة الفيزيائية لإيجاد كمية مجهولة بدلالة الكميات الأخرى.', 'إضافة همزة «أن»، وتحديد السلوك بـ«يعيد كتابة المعادلة ... بدلالة» كما يرد في الكتاب بدل «يكتب المعادلات ... بدلالات مختلفة» الغامضة.', 'صياغة', 'يعتمد بعد التعديل', 'تطبيق', 'إجراءات ومهارات', '["إعادة كتابة المعادلة","الكمية المجهولة"]'::jsonb, null, '[11,15,29]'::jsonb, 'مغطى', 'ص11 مثال 1: «نعيد كتابة المعادلة ليكون المجهول وحده على الطرف الأيسر» (R = V/I)، و«أعد كتابة المعادلات المستخدمة في حل المسائل الآتية» (مسائل تدريبية 1–4)؛ ص15 السؤال 7 (أعد كتابة F = Bqv للحصول على v)؛ ص29 السؤالان 4 و6a.', null, 'approved', '2026-11-16'::timestamptz),
(10101107, 101011, 'P1-C1-L1-O07', null, 7, 'ان يوضح الطالب المقصود بالطريقة العلمية.', 'أن يوضّح الطالب المقصود بالطريقة العلمية.', '[]'::jsonb, 'أن يوضّح الطالب المقصود بالطريقة العلمية.', 'إضافة همزة «أن».', 'إملائي', 'يعتمد بعد التعديل', 'فهم', 'مفاهيم', '["الطريقة العلمية"]'::jsonb, null, '[12,25,26]'::jsonb, 'مغطى', 'ص12: «تمثل الطريقة العلمية أسلوبًا للإجابة عن تساؤلات علمية بهدف تفسير الظواهر الطبيعية المختلفة. وتبدأ بطرح أسئلة بناءً على مشاهدات، ثم محاولة البحث عن إجابات منطقية لها عن طريق وضع الفرضيات»؛ ص25؛ ص26 السؤال 21.', null, 'approved', '2026-11-16'::timestamptz),
(10101108, 101011, 'P1-C1-L1-O08', null, 8, 'ان يعرف الطالب الفرضية.', 'أن يعرّف الطالب الفرضية.', '[]'::jsonb, 'أن يعرّف الطالب الفرضية.', 'إضافة همزة «أن»، وتشكيل «يعرّف».', 'إملائي', 'يعتمد بعد التعديل', 'تذكر', 'حقائق ومصطلحات', '["الفرضية"]'::jsonb, null, '[12,25]'::jsonb, 'مغطى', 'ص12: «الفرضية تخمين علمي عن كيفية ارتباط المتغيرات بعضها مع بعض»؛ ص25 المفاهيم الرئيسة.', null, 'approved', '2026-11-16'::timestamptz),
(10101109, 101011, 'P1-C1-L1-O09', null, 9, 'ان يحدد الطالب نوع العلاقة( طردية او عكسية ) بين الكميات الفيزيائية في علاقة ما', 'أن يحدد الطالب نوع العلاقة (طردية أو عكسية) بين كميتين فيزيائيتين من معادلة أو رسم بياني.', '[]'::jsonb, 'أن يحدد الطالب نوع العلاقة (طردية أو عكسية) بين كميتين فيزيائيتين من معادلة أو رسم بياني.', 'إضافة همزة «أن»، وهمزة «أو»، وضبط المسافات حول القوسين، وتحديد مصدر الاستنتاج (معادلة أو رسم بياني) بدل «في علاقة ما».', 'صياغة', 'يعتمد بعد التعديل', 'تحليل', 'مفاهيم', '["العلاقة الطردية","العلاقة العكسية","الرسم البياني"]'::jsonb, null, '[10,26]'::jsonb, 'مغطى جزئيًا', 'ص10 الشكل 1-1: «نحصل على علاقة خطية طردية بين المتغيرين x وy» مع إحالة إلى دليل الرياضيات لبقية العلاقات؛ ص26 السؤال 26 (الشكل 1-13) والسؤال 27 (F = mv²/r: العلاقة بين F وكل من r وm وv). متن الدرس لا يشرح العلاقة العكسية، وإنما تُقوَّم بالأسئلة مع الإحالة إلى دليل الرياضيات ص196–201.', null, 'approved', '2026-11-16'::timestamptz),
(10101110, 101011, 'P1-C1-L1-O10', null, 10, 'ان يحدد الطالب المتغير المستقل والمتغير التابع في تجربة عملية ما.', 'أن يحدد الطالب المتغير المستقل والمتغير التابع في تجربة عملية.', '[]'::jsonb, 'أن يحدد الطالب المتغير المستقل والمتغير التابع في تجربة عملية.', 'إضافة همزة «أن»، وحذف «ما» الزائدة.', 'إملائي', 'يعتمد بعد التعديل', 'تطبيق', 'إجراءات ومهارات', '["المتغير المستقل","المتغير التابع"]'::jsonb, null, '[23,26]'::jsonb, 'مغطى جزئيًا', 'ص26 السؤال 25 (قياس حجم الغاز داخل بالون وعلاقته بدرجة الحرارة: ما المتغير المستقل والتابع؟) مع إحالة إلى دليل الرياضيات ص194؛ ص23 مختبر الفيزياء: «صف المتغيرات المستقلة والمتغيرات التابعة في هذه التجربة». لا يعرّف متن الدرس المتغيرين.', null, 'approved', '2026-11-16'::timestamptz),
(10101111, 101011, 'P1-C1-L1-O11', null, 11, 'ان يوضح الطالب خطوات اختبار صحة الفرضية', 'أن يوضّح الطالب خطوات اختبار صحة الفرضية.', '[]'::jsonb, 'أن يوضّح الطالب خطوات اختبار صحة الفرضية.', 'إضافة همزة «أن»، وإضافة نقطة الختام.', 'إملائي', 'يعتمد بعد التعديل', 'فهم', 'إجراءات ومهارات', '["الفرضية","التجربة العلمية","قابلية التكرار"]'::jsonb, null, '[12,26]'::jsonb, 'مغطى', 'ص12: «ولاختبار صحة الفرضية يتم تصميم التجارب العلمية وتنفيذها، وتسجيل النتائج وتنظيمها، ثم تحليلها؛ في محاولة لتفسير النتائج أو توقع إجابات جديدة. ويجب أن تكون التجارب والنتائج قابلة للتكرار»؛ ص26 السؤال 20 (خريطة خطوات الطريقة العلمية مع «تعديل الفرضية» و«تكرار»).', null, 'approved', '2026-11-16'::timestamptz),
(10101112, 101011, 'P1-C1-L1-O12', null, 12, 'ان يوضح الطالب المقصود بالنماذج العلمية', 'أن يوضّح الطالب المقصود بالنماذج العلمية.', '[]'::jsonb, 'أن يوضّح الطالب المقصود بالنماذج العلمية.', 'إضافة همزة «أن».', 'إملائي', 'يعتمد بعد التعديل', 'فهم', 'مفاهيم', '["النماذج العلمية"]'::jsonb, null, '[13,25]'::jsonb, 'مغطى', 'ص13: «يطلق على نمذجة فكرة أو معادلة أو تركيب أو نظام لظاهرة نحاول تفسيرها، النماذج العلمية، ولها أنواع متعددة منها: النماذج المادية، والحاسوبية، والفكرية»؛ ص25: «تسهّل النماذج العلمية دراسة وتفسير الظواهر».', null, 'approved', '2026-11-16'::timestamptz),
(10101113, 101011, 'P1-C1-L1-O13', null, 13, 'ان يعرف الطالب القانون العلمي.', 'أن يعرّف الطالب القانون العلمي.', '[]'::jsonb, 'أن يعرّف الطالب القانون العلمي.', 'إضافة همزة «أن»، وتشكيل «يعرّف».', 'إملائي', 'يعتمد بعد التعديل', 'تذكر', 'حقائق ومصطلحات', '["القانون العلمي"]'::jsonb, null, '[14,25]'::jsonb, 'مغطى', 'ص14: «القانون العلمي قاعدة طبيعية تجمع مشاهدات مترابطة لوصف ظاهرة طبيعية متكررة»؛ ص25.', null, 'approved', '2026-11-16'::timestamptz),
(10101114, 101011, 'P1-C1-L1-O14', null, 14, 'ان يوضح الطالب المقصود بالنظرية العلمية.', 'أن يوضّح الطالب المقصود بالنظرية العلمية.', '[]'::jsonb, 'أن يوضّح الطالب المقصود بالنظرية العلمية.', 'إضافة همزة «أن».', 'إملائي', 'يعتمد بعد التعديل', 'فهم', 'مفاهيم', '["النظرية العلمية"]'::jsonb, null, '[14,25]'::jsonb, 'مغطى', 'ص14: «النظرية العلمية إطار يجمع بين عناصر البناء العلمي في موضوع من موضوعات العلم، وهو قادر على تفسير المشاهدات والملاحظات المدعومة بنتائج تجريبية»؛ ص25.', null, 'approved', '2026-11-16'::timestamptz),
(10101115, 101011, 'P1-C1-L1-O15', null, 15, 'ان يذكر الطالب امثلة على قوانين علمية', 'أن يذكر الطالب أمثلة على قوانين علمية.', '[]'::jsonb, 'أن يذكر الطالب أمثلة على قوانين علمية.', 'إضافة همزة «أن»، وتصحيح «امثلة» إلى «أمثلة»، وإضافة نقطة الختام.', 'إملائي', 'يعتمد بعد التعديل', 'تذكر', 'حقائق ومصطلحات', '["القانون العلمي","قانون حفظ الشحنة","قانون الانعكاس"]'::jsonb, null, '[14]'::jsonb, 'مغطى', 'ص14: «ينص قانون حفظ الشحنة على أنه خلال التحولات المختلفة للمادة تبقى الشحنة الكهربائية ثابتة قبل التحول وبعده. وينص قانون الانعكاس على أن زاوية سقوط الشعاع الضوئي ... تساوي زاوية انعكاسه».', null, 'approved', '2026-11-16'::timestamptz),
