insert into public.questions (objective_id, type, number, stem, stimulus, images, options, thinking_level, question_kind, difficulty, source_ref, status, origin)
select (select id from public.objectives where code = 'P1-C2-L1-O02'), v.type, v.number, v.stem, v.stimulus::jsonb, v.images::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'لوصف حركة أي جسم وصفًا كاملًا، ما الذي يجب معرفته؟', null, null, '["أين كان الجسم في بداية حركته ونهايتها فقط","أين كان الجسم، ومتى كان في ذلك المكان","الزمن الكلي الذي استغرقته الحركة فقط","كتلة الجسم وشكله وحجمه"]'::jsonb, 'فهم', 'تفسير مفهوم', 'سهل', 'الكتاب ص 32 — وصف الحركة يرتبط بالمكان والزمان'),
('mcq', 2, 'يبين الشكل الآتي موقعين لسيارة على طريق مستقيم بجوار مسطرة مدرجة بالمتر. ما المعلومة الناقصة اللازمة لوصف حركة السيارة بين الموقعين؟', null, '[{"src":"qimg/phys1/c2l1-o02-positions.svg","alt":"طريق مستقيم أفقي وتحته مسطرة مدرجة من 0 إلى 100 بخطوة 10 ووحدتها m. تظهر سيارة باهتة فوق التدريج 20 مكتوب فوقها «الموقع الأول»، وسيارة واضحة فوق التدريج 60 مكتوب فوقها «الموقع الثاني». لا يظهر في الشكل أي زمن."}]'::jsonb, '["المسافة بين الموقعين على الطريق","كتلة السيارة وعدد ركابها","طول السيارة وعرضها","لحظة وجود السيارة عند كل موقع"]'::jsonb, 'فهم', 'استنتاج من رسم', 'متوسط', 'الكتاب ص 32 — وصف الحركة يرتبط بالمكان والزمان'),
('mcq', 3, 'قال شاهد: «رأيت السيارة عند الإشارة المرورية». لماذا لا تكفي هذه العبارة لوصف حركة السيارة؟', null, null, '["لأنها تحدد مكان السيارة دون أن تحدد متى كانت فيه","لأنها تحدد الزمن دون أن تحدد المكان","لأن الإشارة المرورية لا تصلح مرجعًا للمكان","لأنها لا تذكر لون السيارة ونوعها"]'::jsonb, 'فهم', 'تفسير', 'سهل', 'الكتاب ص 32 — وصف الحركة يرتبط بالمكان والزمان'),
('mcq', 4, 'يبين الشكل الآتي لقطتين لمشهد واحد فيه شجرة وعدّاء، ولم يُسجَّل زمن التقاط أيّ منهما. ماذا يمكن أن نستنتج منهما؟', null, '[{"src":"qimg/phys1/c2l1-o02-snapshots.svg","alt":"لوحتان متجاورتان لمشهد واحد. في كل لوحة أرض خضراء وشجرة في منتصفها. في اللوحة المكتوب تحتها «اللقطة (1)» يقف عدّاء على يسار الشجرة، وفي اللوحة المكتوب تحتها «اللقطة (2)» يقف العدّاء على يمين الشجرة. لا يظهر أي زمن على اللقطتين."}]'::jsonb, '["أن العدّاء قطع المسافة بين الموقعين في 1 s","أن الشجرة هي التي تحركت والعدّاء ساكن","أن موقع العدّاء تغير، لكن وصف حركته يحتاج إلى زمن كل لقطة","أن العدّاء لم يتحرك لأن اللقطتين بلا زمن"]'::jsonb, 'تحليل', 'استنتاج من رسم', 'متوسط', 'الكتاب ص 32 — وصف الحركة يرتبط بالمكان والزمان'),
('mcq', 5, 'يبين الشكل الآتي موقعي سيارة على طريق مستقيم، واللحظة الزمنية عند كل موقع. أيّ العبارات الآتية تصف حركة السيارة وصفًا يربط المكان بالزمان؟', null, '[{"src":"qimg/phys1/c2l1-o02-times.svg","alt":"طريق مستقيم أفقي وتحته مسطرة مدرجة من 0 إلى 100 بخطوة 10 ووحدتها m. سيارة باهتة فوق التدريج 20 مكتوب فوقها t = 0.0 s، وسيارة واضحة فوق التدريج 60 مكتوب فوقها t = 4.0 s."}]'::jsonb, '["تحركت السيارة من الموقع 20 m إلى الموقع 60 m","كانت عند 20 m في اللحظة 0.0 s، ثم عند 60 m في اللحظة 4.0 s","تحركت السيارة مدة 4.0 s على الطريق","كانت عند 60 m في اللحظة 0.0 s، ثم عند 20 m في اللحظة 4.0 s"]'::jsonb, 'فهم', 'قراءة رسم', 'متوسط', 'الكتاب ص 32 — وصف الحركة يرتبط بالمكان والزمان'),
('mcq', 6, 'سجّل طالب أن السيارة اللعبة A قطعت 2.0 m، وأن السيارة اللعبة B قطعت 3.0 m، دون أن يسجّل الزمن الذي استغرقته كل منهما، وقد انطلقتا في لحظتين مختلفتين. هل يمكنه الحكم أيّ السيارتين أسرع؟', null, null, '["نعم؛ السيارة B أسرع لأنها قطعت مسافة أكبر","نعم؛ السيارتان متساويتان في السرعة لأنهما لعبتان","لا؛ لأن المقارنة تحتاج إلى معرفة كتلة كل سيارة","لا؛ لأن المقارنة تحتاج إلى معرفة المسافة والزمن معًا"]'::jsonb, 'تحليل', 'تقويم بيانات', 'صعب', 'الكتاب ص 32 — وصف الحركة يرتبط بالمكان والزمان'),
('mcq', 7, 'صُوّر راكب دراجة هوائية بآلة تصوير تتابعه في أثناء حركته، فظهر الراكب واضحًا بينما ظهرت الخلفية غير واضحة. علامَ يدل ذلك؟', null, null, '["على أن موقع الراكب تغير في أثناء التقاط الصورة","على أن الراكب كان ساكنًا والخلفية تتحرك","على أن الراكب يتحرك في مسار دائري","على أن الصورة التُقطت قبل أن يبدأ الراكب الحركة"]'::jsonb, 'فهم', 'تفسير ملاحظة', 'سهل', 'الكتاب ص 32 — أنواع الحركة (راكب الدراجة الهوائية)'),
('essay', 1, 'وضّح لماذا يرتبط وصف حركة جسم بالمكان والزمان معًا، مستعينًا بمثال سيارة تتحرك على طريق مستقيم.', null, null, null, 'فهم', 'توضيح مع مثال', 'متوسط', 'الكتاب ص 32 — وصف الحركة يرتبط بالمكان والزمان'),
('essay', 2, 'سجّل طالب يقف على جانب طريق مستقيم أن حافلة كانت عند الموقع 50 m في اللحظة 2.0 s، وعند الموقع 110 m في اللحظة 5.0 s. (أ) صف حركة الحافلة بعبارة تربط المكان بالزمان. (ب) كتب زميله: «تحركت الحافلة من الموقع 50 m إلى الموقع 110 m». ما الذي ينقص عبارة الزميل لتصف حركة الحافلة وصفًا كاملًا؟ ولماذا؟', null, null, null, 'تطبيق', 'وصف وحساب', 'صعب', 'الكتاب ص 32 — وصف الحركة يرتبط بالمكان والزمان'),
('essay', 3, 'أراد طالبان تحديد أيّ سيارتين لعبتين تعملان بانضغاط النابض أسرع. اقترح الأول قياس المسافة التي تقطعها كل سيارة فقط، واقترح الثاني قياس المسافة والزمن لكل منهما. أيّ الاقتراحين أفضل؟ فسّر في ضوء ارتباط وصف الحركة بالمكان والزمان، واذكر البيانات التي يجب جمعها.', null, null, null, 'تحليل', 'تقويم تصميم', 'صعب', 'الكتاب ص 31 — تجربة استهلالية: أي السيارتين أسرع؟')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
