from (values
('mcq', 1, 1, 'لوصف حركة جسم يجب معرفة متى شغل الجسم مكانًا ما؛ فوصف الحركة يرتبط بالمكان والزمان معًا.', '["المكان وحده لا يكفي؛ إذ يجب معرفة متى شغل الجسم ذلك المكان.","","الزمن وحده لا يكفي؛ إذ يجب معرفة مكان الجسم عند كل لحظة.","الكتلة والشكل لا يصفان الحركة؛ فوصف الحركة يرتبط بالمكان والزمان."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-11-18T12:34:59.187Z"}'::jsonb),
('mcq', 2, 3, 'يعطي الشكل مكان السيارة في الموقعين (20 m و60 m) لكنه لا يبين متى كانت عند كل منهما، ووصف الحركة يتطلب المكان والزمان معًا.', '["المسافة بين الموقعين يمكن قراءتها من المسطرة (40 m)، فهي ليست ناقصة.","الكتلة لا تلزم لوصف الحركة؛ الناقص هو الزمن.","طول السيارة لا يحدد متى كانت في كل موقع، والناقص هو الزمن.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-11-18T12:34:59.187Z"}'::jsonb),
('mcq', 3, 0, 'وصف الحركة يرتبط بالمكان والزمان؛ والعبارة تذكر المكان فقط دون اللحظة التي كانت فيها السيارة هناك.', '["","العبارة تحدد المكان (عند الإشارة)، والناقص هو الزمن.","الإشارة جسم ثابت يصلح لتحديد مكان السيارة.","لون السيارة ونوعها لا علاقة لهما بوصف الحركة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-11-18T12:34:59.187Z"}'::jsonb),
('mcq', 4, 2, 'ظهور العدّاء في موقعين مختلفين بالنسبة إلى الشجرة الثابتة يدل على تغير موقعه، لكن وصف حركته وصفًا كاملًا يتطلب معرفة متى كان في كل موقع.', '["لا يمكن معرفة الزمن المستغرق لأنه لم يُسجَّل.","الشجرة في المكان نفسه في اللقطتين، والعدّاء هو الذي ظهر في موقع مختلف.","","غياب الزمن لا يلغي تغير الموقع الظاهر في اللقطتين."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-11-18T12:34:59.188Z"}'::jsonb),
('mcq', 5, 1, 'يبين الشكل أن السيارة كانت عند الموقع 20 m في اللحظة 0.0 s، وعند الموقع 60 m في اللحظة 4.0 s، وهذا الوصف يربط كل مكان بزمانه.', '["العبارة تذكر المكان فقط دون اللحظة التي كانت فيها السيارة في كل موقع.","","العبارة تذكر الزمن فقط دون أماكن السيارة.","هذا عكس ما في الشكل؛ فالسيارة كانت عند 20 m في اللحظة 0.0 s."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-11-18T12:34:59.188Z"}'::jsonb),
('mcq', 6, 3, 'الحكم على السرعة يتطلب ربط المسافة المقطوعة بالزمن المستغرق؛ وبدون الزمن لا يمكن معرفة أيّ السيارتين أسرع.', '["قطع مسافة أكبر قد يكون بسبب زمن أطول؛ فلا يكفي المكان دون الزمان.","لا دليل على تساوي سرعتيهما، ولم يُقس الزمن.","الكتلة لا تلزم لمقارنة السرعتين، والناقص هو الزمن.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (6%)"}],"at":"2026-11-18T12:34:59.188Z"}'::jsonb),
('mcq', 7, 0, 'كانت آلة التصوير مركزة على الراكب وتتابعه، فظهرت الخلفية غير واضحة، وهذا يدل على أن موقع الراكب قد تغير خلال زمن التقاط الصورة.', '["","الخلفية ثابتة، وعدم وضوحها ناتج عن تتبع آلة التصوير للراكب المتحرك.","عدم وضوح الخلفية لا يحدد شكل المسار.","لو كان الراكب ساكنًا وآلة التصوير ثابتة لظهرت الخلفية واضحة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (0%)"}],"at":"2026-11-18T12:34:59.189Z"}'::jsonb),
('essay', 1, null::int, null, null, 'لأن الحركة تغير في موقع الجسم مع مرور الزمن؛ فلا يكفي أن نعرف أين كانت السيارة، بل يجب أن نعرف متى كانت في كل مكان. فإذا قلنا: «كانت السيارة عند الموقع 100 m في اللحظة 5 s، ثم عند الموقع 300 m في اللحظة 15 s» نكون قد وصفنا حركتها، أما ذكر المكانين وحدهما أو الزمنين وحدهما فلا يكفي.', '["الحركة تغير الموقع مع الزمن","المكان وحده لا يكفي","الزمان وحده لا يكفي","مثال يربط كل موقع بلحظته"]'::jsonb, '[]'::jsonb, '[{"element":"بيان أن الحركة تغير موقع مع الزمن","marks":1},{"element":"عدم كفاية المكان وحده أو الزمن وحده","marks":1},{"element":"مثال صحيح يربط المكان بالزمان","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"يوضح الارتباط ويعلل عدم كفاية أحدهما ويعطي مثالًا صحيحًا"},{"level":"2 درجتان","description":"يوضح الارتباط مع مثال ناقص أو دون تعليل"},{"level":"1 درجة","description":"يذكر أن الوصف يحتاج إلى المكان والزمان دون توضيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["الاكتفاء بذكر مكان السيارة","ذكر الكتلة أو الشكل عناصر لوصف الحركة","مثال بلا أزمنة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-18T12:34:59.189Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) كانت الحافلة عند الموقع 50 m في اللحظة 2.0 s، ثم أصبحت عند الموقع 110 m في اللحظة 5.0 s. (ب) تنقص عبارةَ الزميل اللحظاتُ الزمنية التي كانت فيها الحافلة عند كل موقع؛ فهي تذكر المكان وحده ولا تبين متى كانت الحافلة في كل موقع، ووصف الحركة يرتبط بالمكان والزمان معًا.', '["ربط الموقع 50 m باللحظة 2.0 s","ربط الموقع 110 m باللحظة 5.0 s","تحديد الناقص في عبارة الزميل: اللحظات الزمنية","التعليل: وصف الحركة يرتبط بالمكان والزمان معًا"]'::jsonb, '[]'::jsonb, '[{"element":"ربط الموقع الأول بلحظته","marks":1},{"element":"ربط الموقع الثاني بلحظته","marks":1},{"element":"تحديد الناقص","marks":1},{"element":"التعليل","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"وصف يربط كل موقع بلحظته، وتحديد الناقص في عبارة الزميل مع التعليل"},{"level":"2–3 درجات","description":"وصف صحيح مع تحديد الناقص دون تعليل، أو وصف ناقص مع تحديد الناقص وتعليله"},{"level":"1 درجة","description":"عنصر واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["وصف المكان دون الزمن","عدّ عبارة الزميل كافية لأنها تذكر الموقعين","ذكر الكتلة أو حجم الحافلة على أنهما الناقص"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-11-18T12:34:59.189Z"}'::jsonb),
('essay', 3, null::int, null, null, 'اقتراح الطالب الثاني أفضل؛ لأن وصف الحركة يرتبط بالمكان والزمان معًا، والمسافة وحدها لا تكفي، فقد تقطع سيارة مسافة أكبر لأنها تحركت زمنًا أطول لا لأنها أسرع. يجب جمع موقع كل سيارة عند لحظات زمنية محددة (مثلًا كل 0.1 s) أو المسافة التي تقطعها كل سيارة في الزمن نفسه، مع إطلاقهما معًا من خط البداية.', '["اختيار الاقتراح الثاني","تعليل بارتباط الحركة بالمكان والزمان","بيان قصور قياس المسافة وحدها","ذكر البيانات: مواقع السيارتين عند لحظات زمنية محددة"]'::jsonb, '[]'::jsonb, '[{"element":"الاختيار الصحيح","marks":1},{"element":"التعليل","marks":1},{"element":"بيان قصور الاقتراح الأول","marks":1},{"element":"البيانات المطلوبة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"يختار الاقتراح الثاني ويعلل ويبين قصور الأول ويحدد البيانات"},{"level":"2–3 درجات","description":"يختار ويعلل دون تحديد البيانات أو دون بيان القصور"},{"level":"1 درجة","description":"يختار الاقتراح الصحيح دون تعليل"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["اختيار الاقتراح الأول","ذكر الكتلة ضمن البيانات اللازمة","إغفال تسجيل الزمن مع كل موقع"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-11-18T12:34:59.189Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
