from (values
('mcq', 1, 'ما المقصود بالمخطط التوضيحي للحركة؟', null, null, '["رسم بياني يُمثَّل فيه الزمن على المحور الأفقي والموقع على المحور الرأسي","صورة واحدة لجسم متحرك تظهر فيها الخلفية غير واضحة","خريطة تبين الطريق الذي سلكه الجسم من بداية حركته إلى نهايتها","صور متتابعة لجسم متحرك تُجمع في صورة واحدة تُظهر مواقعه في فترات زمنية متساوية"]'::jsonb, 'تذكر', 'تعريف مفهوم', 'سهل', 'الكتاب ص 32 — المخططات التوضيحية للحركة'),
('mcq', 2, 'التُقطت صور متتابعة لسيارة في فترات زمنية متساوية، ثم جُمعت في الشكل الآتي. ماذا يمثل هذا الشكل؟', null, '[{"src":"qimg/phys1/c2l1-o03-cars.svg","alt":"طريق أفقي عليه أربع صور لسيارة متجهة نحو اليمين في أربعة مواقع متباعدة، الصورة اليسرى باهتة جدًا والصور تزداد وضوحًا نحو اليمين، وأوضحها الصورة اليمنى. في أقصى اليمين شجرة ثابتة على جانب الطريق."}]'::jsonb, '["منحنى (الموقع – الزمن) لحركة السيارة","أربع سيارات مختلفة تسير معًا على الطريق","مخططًا توضيحيًا لحركة سيارة واحدة","نموذج الجسيم النقطي لحركة السيارة"]'::jsonb, 'فهم', 'تعرّف من رسم', 'سهل', 'الكتاب ص 32 — المخططات التوضيحية للحركة'),
('mcq', 3, 'ما الشرط الأساسي في الصور التي تُجمع لتكوين مخطط توضيحي للحركة؟', null, null, '["أن تكون المسافات بين مواقع الجسم المتتالية متساوية","أن تكون الفترات الزمنية بين الصور المتتالية متساوية","أن يكون الجسم ساكنًا في أثناء التصوير","أن تتحرك آلة التصوير مع الجسم"]'::jsonb, 'فهم', 'تفسير مفهوم', 'متوسط', 'الكتاب ص 32 — المخططات التوضيحية للحركة'),
('mcq', 4, 'أيّ الصور المرقمة في الشكل الآتي تمثل مخططًا توضيحيًا للحركة؟', null, '[{"src":"qimg/phys1/c2l1-o03-reps.svg","alt":"أربع لوحات مرقمة. اللوحة (1): سيارة واحدة واضحة خلفها أشرطة رأسية باهتة تمثل خلفية غير واضحة. اللوحة (2): رسم بياني محوره الأفقي «الزمن (s)» ومحوره الرأسي «الموقع (m)» وفيه خط مستقيم صاعد. اللوحة (3): طريق عليه أربع صور لسيارة واحدة متجهة نحو اليمين في مواقع متتالية، تزداد وضوحًا نحو اليمين، وخلفها شجرة ثابتة. اللوحة (4): خريطة عليها خط برتقالي متعرج يصل بين نقطة بداية ونقطة نهاية."}]'::jsonb, '["الصورة (3)","الصورة (1)","الصورة (2)","الصورة (4)"]'::jsonb, 'فهم', 'تمييز تمثيلات', 'متوسط', 'الكتاب ص 32 — المخططات التوضيحية للحركة'),
('mcq', 5, 'ما الهدف من رسم المخطط التوضيحي للحركة؟', null, null, '["قياس كتلة الجسم المتحرك بدقة في أثناء حركته","تحديد القوة التي سببت حركة الجسم ومقدارها في كل موقع من مواقعه","إظهار تفاصيل شكل الجسم وأجزائه بوضوح أكبر","بيان موقع الجسم في أزمنة متعاقبة لمعرفة كيف تتغير سرعته"]'::jsonb, 'فهم', 'تفسير غرض', 'متوسط', 'الكتاب ص 54 — إتقان المفاهيم (السؤالان 35 و36)'),
('mcq', 6, 'في مخطط توضيحي لحركة عدّاء، ظهرت الشجرة والمبنى في الخلفية في المكان نفسه في جميع الصور، بينما ظهر العدّاء في موقع مختلف في كل صورة. ماذا تستنتج؟', null, null, '["أن الشجرة والمبنى يتحركان مع العدّاء","أن العدّاء هو الجسم المتحرك الوحيد بالنسبة إلى ما حوله","أن الصور لم تُلتقط في فترات زمنية متساوية","أن العدّاء ساكن، وآلة التصوير هي التي تحركت بين صورة وأخرى"]'::jsonb, 'تحليل', 'استنتاج', 'صعب', 'الكتاب ص 32 — المخططات التوضيحية للحركة'),
('mcq', 7, 'يضم مخطط توضيحي لحركة سيارة 6 صور التُقطت كل 0.5 s. ما الفترة الزمنية بين أول صورة وآخر صورة في المخطط؟', null, null, '["3.0 s","2.0 s","2.5 s","0.5 s"]'::jsonb, 'تطبيق', 'حساب', 'صعب', 'الكتاب ص 32 — المخططات التوضيحية للحركة'),
('essay', 1, 'وضّح المقصود بالمخطط التوضيحي للحركة، واذكر ما الذي يبينه.', null, null, null, 'فهم', 'توضيح مفهوم', 'سهل', 'الكتاب ص 32 — المخططات التوضيحية للحركة'),
('essay', 2, 'أُعطيت صورًا متتابعة لعدّاء، التُقط بعضها بعد 0.2 s من الصورة السابقة، وبعضها بعد 0.5 s. هل يصلح جمعها كما هي في صورة واحدة لتكوين مخطط توضيحي للحركة؟ فسّر، وبيّن أثر ذلك في الحكم على تغير سرعة العدّاء.', null, null, null, 'تحليل', 'تفسير', 'متوسط', 'الكتاب ص 50 — مختبر الفيزياء: عمل رسوم توضيحية للحركة'),
('essay', 3, 'قارن بين صورة واحدة لراكب دراجة هوائية التقطتها آلة تصوير تتابعه (فظهرت الخلفية غير واضحة)، ومخطط توضيحي لحركته، من حيث المعلومات التي يقدمها كل منهما عن الحركة. أيهما أنسب لمعرفة هل تتزايد سرعة الراكب أم تتناقص؟ علّل.', null, null, null, 'تقويم', 'مقارنة وتقويم', 'صعب', 'الكتاب ص 32 — أنواع الحركة والمخططات التوضيحية للحركة')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
