insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 3, 'المخطط التوضيحي للحركة هو ترتيب سلسلة من الصور المتتابعة لجسم متحرك وجمعها في صورة واحدة تُظهر مواقعه في فترات زمنية متساوية.', '["هذا وصف منحنى (الموقع – الزمن)، لا المخطط التوضيحي للحركة.","الصورة الواحدة تُظهر الجسم في موقع واحد، ولا تُظهر مواقعه المتتابعة.","الخريطة تبين المسار فقط، ولا تبين مواقع الجسم في فترات زمنية متساوية.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (50%)"}],"at":"2026-11-18T12:34:59.190Z"}'::jsonb),
('mcq', 2, 2, 'الشكل يجمع صورًا متتابعة لسيارة واحدة التُقطت في فترات زمنية متساوية في صورة واحدة، وهذا هو المخطط التوضيحي للحركة.', '["لا توجد في الشكل محاور للموقع والزمن؛ بل صور للسيارة.","الصور لسيارة واحدة في مواقع مختلفة عند لحظات متتابعة، لا لأربع سيارات.","","في نموذج الجسيم النقطي تُستبدل بالسيارة نقاط مفردة، والشكل يُظهر صور السيارة نفسها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-11-18T12:34:59.190Z"}'::jsonb),
('mcq', 3, 1, 'يُظهر المخطط التوضيحي مواقع الجسم في فترات زمنية متساوية؛ ولذلك يجب أن تُلتقط الصور بفواصل زمنية متساوية.', '["المسافات تتساوى فقط إذا كانت سرعة الجسم ثابتة، وليست شرطًا لتكوين المخطط.","","المخطط يمثل جسمًا متحركًا تتغير مواقعه.","إذا تحركت آلة التصوير تغيرت الخلفية، والمطلوب أن تبقى الخلفية ثابتة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-18T12:34:59.190Z"}'::jsonb),
('mcq', 4, 0, 'الصورة (3) تجمع صورًا متتابعة لسيارة في صورة واحدة مع خلفية ثابتة، فتُظهر مواقعها المتتالية، وهذا هو المخطط التوضيحي للحركة.', '["","الصورة (1) صورة واحدة لسيارة بخلفية غير واضحة، وتُظهر موقعًا واحدًا فقط.","الصورة (2) منحنى (الموقع – الزمن)، وهو رسم بياني لا يجمع صور الجسم.","الصورة (4) خريطة لمسار الحركة، ولا تُظهر مواقع الجسم في فترات زمنية متساوية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-18T12:34:59.190Z"}'::jsonb),
('mcq', 5, 3, 'يبين المخطط التوضيحي للحركة موقع جسم خلال أزمنة متعاقبة، ومن تفحصه يمكن تقرير ما إذا كانت سرعة الجسم تتزايد أو تتناقص أو تظل ثابتة.', '["المخطط لا يعطي أي معلومة عن الكتلة.","المخطط يصف الحركة نفسها ولا يحدد القوة المسببة لها.","الهدف وصف الحركة، لا إبراز تفاصيل الجسم.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-11-18T12:34:59.190Z"}'::jsonb),
('mcq', 6, 1, 'بقاء كل شيء في الخلفية في المكان نفسه وتغير موقع العدّاء وحده يدل (ضمن المنظور) على أن العدّاء هو المتحرك الوحيد بالنسبة إلى ما حوله.', '["لو تحركت الخلفية لتغير مكانها بين الصور، لكنها بقيت في المكان نفسه.","","ثبات الخلفية لا يدل على الفترات الزمنية بين الصور.","لو تحركت آلة التصوير لتغير مكان الخلفية في الصور."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-11-18T12:34:59.191Z"}'::jsonb),
('mcq', 7, 2, 'بين 6 صور متتالية 5 فترات زمنية متساوية، فالفترة بين الأولى والأخيرة $= 5 \times 0.5\ \text{s} = 2.5\ \text{s}$.', '["هذا ناتج ضرب عدد الصور (6) في 0.5 s، لكن عدد الفترات بين 6 صور هو 5 فقط.","هذا ناتج عدّ 4 فترات فقط، وعدد الفترات بين 6 صور هو 5.","","هذه الفترة بين صورتين متتاليتين فقط، لا بين الأولى والأخيرة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-11-18T12:34:59.191Z"}'::jsonb),
('essay', 1, null::int, null, null, 'المخطط التوضيحي للحركة هو ترتيب سلسلة من الصور المتتابعة لجسم متحرك، التُقطت في فترات زمنية متساوية، وجمعها في صورة واحدة. وهو يبين موقع الجسم خلال أزمنة متعاقبة، ومنه يمكن تقرير ما إذا كانت سرعة الجسم تتزايد أو تتناقص أو تظل ثابتة.', '["صور متتابعة للجسم","فترات زمنية متساوية","تُجمع في صورة واحدة","يبين موقع الجسم خلال أزمنة متعاقبة"]'::jsonb, '[]'::jsonb, '[{"element":"صور متتابعة تُجمع في صورة واحدة","marks":1},{"element":"فترات زمنية متساوية","marks":1},{"element":"ما يبينه المخطط","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"يذكر العناصر الثلاثة بدقة"},{"level":"2 درجتان","description":"يذكر عنصرين صحيحين"},{"level":"1 درجة","description":"يذكر عنصرًا واحدًا"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["إغفال شرط تساوي الفترات الزمنية","الخلط بينه وبين منحنى (الموقع – الزمن)"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (50%)"}],"at":"2026-11-18T12:34:59.191Z"}'::jsonb),
('essay', 2, null::int, null, null, 'لا يصلح؛ لأن المخطط التوضيحي للحركة يُظهر مواقع الجسم في فترات زمنية متساوية. إذا اختلفت الفترات الزمنية فإن تباعد صور العدّاء لن يعبر عن سرعته؛ فقد تبدو المسافة أكبر بين صورتين لأن الفترة بينهما أطول (0.5 s) لا لأن العدّاء أسرع، فنحكم خطأً بأن سرعته تزايدت أو تناقصت.', '["الحكم بعدم الصلاحية","شرط تساوي الفترات الزمنية","التباعد يتأثر بطول الفترة","قد يؤدي إلى حكم خاطئ على السرعة"]'::jsonb, '[]'::jsonb, '[{"element":"الحكم الصحيح","marks":1},{"element":"ذكر الشرط","marks":1},{"element":"تفسير أثر اختلاف الفترات في التباعد","marks":1},{"element":"بيان الحكم الخاطئ على السرعة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"يحكم ويذكر الشرط ويفسر أثر اختلاف الفترات على الحكم على السرعة"},{"level":"2–3 درجات","description":"يحكم ويذكر الشرط دون تفسير كامل للأثر"},{"level":"1 درجة","description":"يحكم حكمًا صحيحًا دون تعليل"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدّ الصور صالحة لأنها لعدّاء واحد","الحكم على السرعة من تباعد الصور مع اختلاف الفترات"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-11-18T12:34:59.191Z"}'::jsonb),
('essay', 3, null::int, null, null, 'الصورة الواحدة تدل فقط على أن الراكب كان يتحرك (تغير موقعه بالنسبة إلى الخلفية)، لكنها تُظهره في موقع واحد ولا تبين مواقعه المتتالية. أما المخطط التوضيحي فيُظهر مواقع الراكب المتتالية في فترات زمنية متساوية في صورة واحدة. والمخطط أنسب؛ لأن المقارنة بين المسافات بين مواقعه المتتالية في فترات متساوية تبين هل سرعته تتزايد أو تتناقص أو تظل ثابتة.', '["الصورة الواحدة: تدل على الحركة فقط وتُظهر موقعًا واحدًا","المخطط: مواقع متتالية في فترات متساوية","المخطط أنسب","التعليل بمقارنة المسافات بين المواقع"]'::jsonb, '[]'::jsonb, '[{"element":"وصف ما تقدمه الصورة الواحدة","marks":1},{"element":"وصف ما يقدمه المخطط","marks":1},{"element":"اختيار المخطط","marks":1},{"element":"التعليل","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"يقارن بدقة ويختار المخطط ويعلل بتباعد المواقع في فترات متساوية"},{"level":"2–3 درجات","description":"يقارن مقارنة ناقصة أو يختار دون تعليل كافٍ"},{"level":"1 درجة","description":"يختار المخطط فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن الصورة الواحدة تبين تغير السرعة","إغفال تساوي الفترات الزمنية في المخطط"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-11-18T12:34:59.191Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
