('mcq', 1, 'ما المقصود بنموذج الجسيم النقطي؟', null, null, '["تمثيل حركة الجسم بسلسلة متتابعة من النقاط المفردة بدلًا من صوره","رسم الجسم بتفاصيله كاملة في كل صورة من الصور المتتابعة","رسم بياني لموقع الجسم مقابل الزمن","تقسيم الجسم إلى جسيمات صغيرة جدًا تُدرس حركة كل منها"]'::jsonb, 'تذكر', 'تعريف مفهوم', 'سهل', 'الكتاب ص 33 — نموذج الجسيم النقطي'),
('mcq', 2, 'في الشكل الآتي، ماذا تمثل النقاط المرسومة أسفل صور السيارة؟', null, '[{"src":"qimg/phys1/c2l1-o04-cardots.svg","alt":"طريق أفقي عليه أربع صور لسيارة متجهة نحو اليمين في مواقع متتالية، تزداد وضوحًا نحو اليمين. وتحت الطريق أربع نقاط سوداء، كل نقطة تحت منتصف إحدى صور السيارة تمامًا."}]'::jsonb, '["عجلات السيارة فقط في كل موقع من مواقعها","مواقع إشارات المرور المنتشرة على الطريق","الزمن الذي استغرقته السيارة بين كل صورتين متتاليتين","السيارة كلها ممثلة بنقطة مفردة عند كل موقع من مواقعها"]'::jsonb, 'تذكر', 'تعرّف من رسم', 'سهل', 'الكتاب ص 33 — نموذج الجسيم النقطي'),
('mcq', 3, 'يُراد تمثيل حركة العدّاء في الشكل الآتي بنموذج الجسيم النقطي. أيّ النقاط المعلّمة تُختار لتمثيل جسمه؟', null, '[{"src":"qimg/phys1/c2l1-o04-points.svg","alt":"رسم مبسط لعدّاء يجري على أرض خضراء، وعليه أربع نقاط حمراء معلّمة: A على الرأس، وB في منتصف الجذع (مركز الجسم)، وC على اليد الممدودة إلى الأمام، وD على القدم الملامسة للأرض."}]'::jsonb, '["النقطة A","النقطة B","النقطة C","النقطة D"]'::jsonb, 'فهم', 'تطبيق مفهوم على رسم', 'متوسط', 'الكتاب ص 33 — نموذج الجسيم النقطي'),
('mcq', 4, 'عند تمثيل حركة عدّاء بنموذج الجسيم النقطي، ما الذي نتجاهله؟', null, null, '["موقع العدّاء في كل صورة","الفترات الزمنية بين المواقع المتتالية","حركة الأذرع والأرجل وتفاصيل الجسم كله","اتجاه حركة العدّاء"]'::jsonb, 'تذكر', 'تذكر حقائق', 'سهل', 'الكتاب ص 33 — نموذج الجسيم النقطي'),
('mcq', 5, 'ما الذي يميز نموذج الجسيم النقطي من المخطط التوضيحي للحركة؟', null, null, '["يُظهر تفاصيل شكل الجسم في كل موقع بوضوح أكبر","لا تكون الفترات الزمنية بين مواقعه متساوية","يُمثَّل فيه الزمن على محور أفقي والموقع على محور رأسي","تُستخدم فيه نقاط مفردة متتالية بدلًا من صور الجسم"]'::jsonb, 'فهم', 'مقارنة', 'متوسط', 'الكتاب ص 53 — دليل مراجعة الفصل 2-1'),
('mcq', 6, 'لماذا يُعدّ نموذج الجسيم النقطي مفيدًا عند دراسة حركة الأجسام؟', null, null, '["لأنه يسهّل تتبع مسار الحركة بالتركيز على نقطة واحدة تمثل الجسم","لأنه يبين تفاصيل حركة كل جزء من أجزاء الجسم","لأنه يغني عن تسجيل مواقع الجسم في أزمنة متعاقبة خلال حركته","لأنه يجعل الجسم أصغر حجمًا فيتحرك أسرع"]'::jsonb, 'فهم', 'تفسير', 'متوسط', 'الكتاب ص 33 — نموذج الجسيم النقطي'),
('mcq', 7, 'التُقطت 5 صور متتابعة لسيارة تتحرك، ثم مُثّلت حركتها بنموذج الجسيم النقطي. كم نقطة يضم النموذج، وماذا تمثل كل نقطة؟', null, null, '["4 نقاط؛ كل نقطة تمثل المسافة بين صورتين متتاليتين","10 نقاط؛ نقطتان لكل صورة تمثلان مقدمة السيارة ومؤخرتها في موقعها","5 نقاط؛ كل نقطة تمثل السيارة كلها عند لحظة التقاط إحدى الصور","نقطة واحدة؛ تمثل موقع السيارة في الصورة الأخيرة"]'::jsonb, 'تطبيق', 'تطبيق مفهوم', 'صعب', 'الكتاب ص 33 — نموذج الجسيم النقطي'),
('essay', 1, 'عرّف نموذج الجسيم النقطي، ثم وضّح خطوات الحصول عليه من صور متتابعة لعدّاء التُقطت في فترات زمنية متساوية.', null, null, null, 'فهم', 'تعريف وإجراء', 'متوسط', 'الكتاب ص 33 — نموذج الجسيم النقطي'),
('essay', 2, 'تُظهر صور متتابعة طائرًا يطير أفقيًا، وصور أخرى لسيارة تقترب من إشارة مرورية لتتوقف عندها. (أ) حدّد النقطة التي تختارها على جسم كل منهما لتمثيله في نموذج الجسيم النقطي، مع التعليل. (ب) ما الذي تتجاهله في كل حالة؟', null, null, null, 'تطبيق', 'تطبيق النموذج', 'صعب', 'الكتاب ص 33 — مراجعة 2-1'),
('essay', 3, 'قال طالب: «نموذج الجسيم النقطي يعني أن الجسم المتحرك صغير جدًا كالذرة». صحّح العبارة، مبينًا المقصود بالنموذج وكيف يُمثَّل فيه جسم كبير كعدّاء.', null, null, null, 'تحليل', 'تصحيح مفهوم خاطئ', 'صعب', 'الكتاب ص 33 — نموذج الجسيم النقطي')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
