('mcq', 3, 1, 'نتجاهل حركة الأذرع والأرجل ونكتفي بنقطة صغيرة مفردة في مركز جسم العدّاء، وهي النقطة B.', '["النقطة A على الرأس، والنموذج يعتمد نقطة في مركز الجسم.","","النقطة C على اليد، وحركة الأذرع تُتجاهل في النموذج.","النقطة D على القدم، وحركة الأرجل تُتجاهل في النموذج."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (28%)"}],"at":"2026-11-18T12:34:59.193Z"}'::jsonb),
('mcq', 4, 2, 'يسهل تتبع مسار حركة العدّاء عند تجاهل حركة الأذرع والأرجل، بل تجاهل جسمه كله والاكتفاء بنقطة مفردة في مركزه.', '["موقع العدّاء هو ما تمثله النقطة، فلا يمكن تجاهله.","الفترات الزمنية المتساوية أساس رسم النموذج ولا تُتجاهل.","","ترتيب النقاط يبين اتجاه الحركة، فهو لا يُتجاهل."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (30%)"}],"at":"2026-11-18T12:34:59.193Z"}'::jsonb),
('mcq', 5, 3, 'يُستخدم في نموذج الجسيم النقطي مجموعة من النقاط المفردة المتتالية بدلًا من الجسم في المخطط التوضيحي للحركة.', '["النموذج يتجاهل تفاصيل الجسم ويمثله بنقطة.","النقاط تمثل مواقع الجسم في الفترات الزمنية المتساوية نفسها.","هذا وصف منحنى (الموقع – الزمن)، لا نموذج الجسيم النقطي.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-11-18T12:34:59.193Z"}'::jsonb),
('mcq', 6, 0, 'يسهل تتبع مسار حركة الجسم عند تجاهل تفاصيله والتركيز على نقطة صغيرة مفردة تمثله.', '["","النموذج يتجاهل حركة الأجزاء، ولا يبين تفاصيلها.","كل نقطة في النموذج هي موقع الجسم عند لحظة معينة، فلا غنى عن المواقع.","النموذج طريقة تمثيل، ولا يغير حجم الجسم ولا سرعته."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-11-18T12:34:59.193Z"}'::jsonb),
('mcq', 7, 2, 'لكل صورة نقطة مفردة واحدة تمثل السيارة كلها في موقعها عند لحظة التقاط تلك الصورة، فيضم النموذج 5 نقاط.', '["النقاط تمثل مواقع السيارة لا المسافات بينها، ولكل صورة نقطة.","النموذج يمثل الجسم كله بنقطة مفردة واحدة في كل صورة.","","النموذج سلسلة متتابعة من النقاط، لا نقطة واحدة؛ فالسيارة متحركة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-11-18T12:34:59.193Z"}'::jsonb),
('essay', 1, null::int, null, null, 'نموذج الجسيم النقطي: تمثيل حركة الجسم بسلسلة متتابعة من النقاط المفردة، كل نقطة تمثل الجسم كله في أحد مواقعه. الخطوات: 1) نرتب الصور المتتابعة ونجمعها في صورة واحدة (مخطط توضيحي للحركة). 2) نتجاهل حركة الأذرع والأرجل وتفاصيل الجسم. 3) نختار نقطة صغيرة مفردة في مركز جسم العدّاء في كل صورة. 4) نرسم هذه النقاط متتابعة في مواقعها فنحصل على النموذج.', '["التعريف: سلسلة نقاط مفردة متتابعة تمثل الجسم","جمع الصور المتتابعة في صورة واحدة","تجاهل حركة الأطراف وتفاصيل الجسم","اختيار نقطة في مركز الجسم ورسم النقاط متتابعة"]'::jsonb, '[]'::jsonb, '[{"element":"التعريف","marks":1},{"element":"جمع الصور","marks":1},{"element":"تجاهل التفاصيل","marks":1},{"element":"اختيار نقطة المركز ورسم السلسلة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تعريف صحيح وخطوات كاملة مرتبة"},{"level":"2–3 درجات","description":"تعريف صحيح مع خطوات ناقصة"},{"level":"1 درجة","description":"تعريف صحيح فقط أو خطوة واحدة"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["اختيار نقطة على الرأس أو القدم","رسم نقاط لأجزاء الجسم المختلفة في الصورة الواحدة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-11-18T12:34:59.193Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) الطائر: نقطة في مركز جسمه، لا على طرف الجناح أو المنقار؛ لأن الجناحين يتحركان صعودًا وهبوطًا بالنسبة إلى الجسم، ومركز الجسم يمثل حركة الطائر كله. السيارة: نقطة في مركزها (منتصفها)، لأنها تمثل موقع السيارة كلها. (ب) نتجاهل في الطائر حركة الجناحين والذيل وشكل جسمه، ونتجاهل في السيارة دوران العجلات وتفاصيل شكلها.', '["نقطة مركز جسم الطائر","نقطة مركز السيارة","التعليل: النقطة تمثل الجسم كله لا جزءًا متحركًا منه","المتجاهَل: حركة الجناحين/العجلات وتفاصيل الشكل"]'::jsonb, '[]'::jsonb, '[{"element":"نقطة الطائر","marks":1},{"element":"نقطة السيارة","marks":1},{"element":"التعليل","marks":1},{"element":"ما يُتجاهل","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"يحدد النقطتين ويعلل ويذكر ما يُتجاهل في الحالتين"},{"level":"2–3 درجات","description":"يحدد النقطتين دون تعليل كافٍ أو دون ذكر ما يُتجاهل"},{"level":"1 درجة","description":"يحدد نقطة واحدة صحيحة"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["اختيار طرف الجناح لأنه أوضح نقطة","اختيار العجلة الأمامية للسيارة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-18T12:34:59.193Z"}'::jsonb),
('essay', 3, null::int, null, null, 'العبارة غير صحيحة؛ فالنموذج لا يعني أن الجسم صغير كالذرة، بل هو طريقة تمثيل نتجاهل فيها تفاصيل الجسم وحركة أجزائه، ونمثل الجسم كله بنقطة صغيرة مفردة في مركزه عند كل موقع، فتصبح حركته سلسلة متتابعة من النقاط. فالعدّاء مثلًا يُمثَّل بنقطة في مركز جسمه في كل صورة، مع أنه ليس صغيرًا في ذاته؛ والمهم أن يكون حجمه صغيرًا جدًا مقارنة بالمسافة التي يتحركها.', '["الحكم بخطأ العبارة","النموذج طريقة تمثيل تتجاهل تفاصيل الجسم","الجسم يُمثل بنقطة في مركزه في كل موقع","مثال العدّاء"]'::jsonb, '[]'::jsonb, '[{"element":"الحكم","marks":1},{"element":"بيان المقصود بالنموذج","marks":1},{"element":"تمثيل الجسم بنقطة في مركزه","marks":1},{"element":"تطبيق على العدّاء","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"يصحح العبارة ويبين المقصود ويطبقه على العدّاء"},{"level":"2–3 درجات","description":"يصحح العبارة مع بيان ناقص"},{"level":"1 درجة","description":"يحكم بخطأ العبارة دون بيان"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["الموافقة على أن الجسيم النقطي جسيم دقيق فعلًا","الخلط بين النموذج وتقسيم الجسم إلى ذرات"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-18T12:34:59.193Z"}'::jsonb)
