('mcq', 1, 'يتحرك دراج نحو اليمين بسرعة ثابتة. أيّ الصفوف في الشكل الآتي يمثل نموذج الجسيم النقطي الصحيح لحركته؟ (الفترات الزمنية بين النقاط المتتالية متساوية في كل الصفوف)', null, '[{"src":"qimg/phys1/c2l1-o05-rows-bike.svg","alt":"أربعة صفوف أفقية من النقاط مرقمة على اليمين (1) إلى (4). الصف (1): ست نقاط تتقارب تدريجيًا من اليسار إلى اليمين (المسافات بينها تتناقص). الصف (2): ست نقاط تتباعد تدريجيًا من اليسار إلى اليمين (المسافات بينها تتزايد). الصف (3): ست نقاط بمسافات متساوية بينها. الصف (4): نقطة واحدة فقط في منتصف الصف."}]'::jsonb, '["الصف (1)","الصف (2)","الصف (3)","الصف (4)"]'::jsonb, 'تطبيق', 'اختيار نموذج', 'متوسط', 'الكتاب ص 33 — مراجعة 2-1'),
('mcq', 2, 'تتحرك سيارة نحو اليمين وتقترب من إشارة مرورية حتى تتوقف عندها. أيّ الصفوف في الشكل الآتي يمثل نموذج الجسيم النقطي لحركتها؟ (الفترات الزمنية بين النقاط المتتالية متساوية في كل الصفوف)', null, '[{"src":"qimg/phys1/c2l1-o05-rows-stop.svg","alt":"أربعة صفوف أفقية من النقاط مرقمة على اليمين (1) إلى (4). الصف (1): ست نقاط تتباعد تدريجيًا من اليسار إلى اليمين. الصف (2): ست نقاط متساوية التباعد. الصف (3): نقطة واحدة فقط. الصف (4): ست نقاط تتقارب تدريجيًا من اليسار إلى اليمين، وأصغر مسافة بين آخر نقطتين."}]'::jsonb, '["الصف (4)","الصف (1)","الصف (2)","الصف (3)"]'::jsonb, 'تطبيق', 'اختيار نموذج', 'متوسط', 'الكتاب ص 33 — مراجعة 2-1'),
('mcq', 3, 'سيارة متوقفة في موقف طوال مدة التقاط 5 صور متتابعة لها. كيف يُرسم نموذج الجسيم النقطي لها؟', null, null, '["خمس نقاط متساوية التباعد على خط مستقيم","نقطة واحدة؛ لأن النقاط الخمس تقع كلها في الموقع نفسه","خمس نقاط يتزايد التباعد بينها","لا يُرسم؛ لأن الجسم الساكن لا يُمثَّل بالنموذج"]'::jsonb, 'تطبيق', 'رسم نموذج', 'سهل', 'الكتاب ص 31 — مقدمة الدرس 2-1'),
('mcq', 4, 'سيارة تسير نحو اليمين ببطء في البداية ثم تتسارع. أيّ الصفوف في الشكل الآتي يمثل نموذج الجسيم النقطي لحركتها؟ (الفترات الزمنية بين النقاط المتتالية متساوية في كل الصفوف)', null, '[{"src":"qimg/phys1/c2l1-o05-rows-speedup.svg","alt":"أربعة صفوف أفقية من النقاط مرقمة على اليمين (1) إلى (4). الصف (1): ست نقاط متساوية التباعد. الصف (2): ست نقاط تتقارب تدريجيًا من اليسار إلى اليمين. الصف (3): ست نقاط تتباعد في البداية ثم تتقارب في النهاية. الصف (4): ست نقاط تتباعد تدريجيًا من اليسار إلى اليمين."}]'::jsonb, '["الصف (1)","الصف (2)","الصف (3)","الصف (4)"]'::jsonb, 'تطبيق', 'اختيار نموذج', 'متوسط', 'الكتاب ص 51 — مختبر الفيزياء: التحليل والتوسع'),
('mcq', 5, 'يبين الجدول مواقع سيارة لعبة تتحرك في خط مستقيم، سُجّلت كل 0.1 s. أيّ الصفوف في الشكل الآتي يمثل نموذج الجسيم النقطي لحركتها على المحور المدرج؟', '{"headers":["الزمن (s)","الموقع (cm)"],"rows":[["0.0","0"],["0.1","2"],["0.2","6"],["0.3","12"],["0.4","20"],["0.5","30"]]}'::jsonb, '[{"src":"qimg/phys1/c2l1-o05-table.svg","alt":"أربعة صفوف أفقية من النقاط مرقمة على اليمين (1) إلى (4)، وتحتها محور مدرج من 0 إلى 30 بخطوة 5 عنوانه «الموقع (cm)». الصف (1): نقاط عند 0 و10 و18 و24 و28 و30. الصف (2): نقاط عند 0 و2 و6 و12 و20 و22. الصف (3): نقاط عند 0 و2 و6 و12 و20 و30. الصف (4): نقاط عند 0 و6 و12 و18 و24 و30."}]'::jsonb, '["الصف (1)","الصف (2)","الصف (3)","الصف (4)"]'::jsonb, 'تطبيق', 'تمثيل بيانات', 'صعب', 'الكتاب ص 51 — مختبر الفيزياء: التحليل والتوسع'),
('mcq', 6, 'رُسم نموذجا الجسيم النقطي لعدّاءين A وB في سباق، بعدد النقاط نفسه وفي الفترات الزمنية نفسها، وتحرك كل منهما بسرعة ثابتة. كان التباعد بين نقاط A ثابتًا ومقداره 4.0 cm، وعندما تجاوز A خط النهاية كان B قد قطع ثلاثة أرباع مسافة السباق فقط. كم يكون التباعد بين نقاط B؟', null, null, '["1.0 cm","3.0 cm","5.3 cm","4.0 cm"]'::jsonb, 'تطبيق', 'حساب', 'صعب', 'الكتاب ص 33 — مراجعة 2-1'),
('mcq', 7, 'عند رسم نموذج الجسيم النقطي لجسم يتحرك بسرعة ثابتة، كيف تُرسم المسافات بين النقاط المتتالية؟', null, null, '["متساوية في الطول","متزايدة تدريجيًا","متناقصة تدريجيًا","منعدمة؛ فتنطبق النقاط"]'::jsonb, 'فهم', 'قاعدة رسم', 'سهل', 'الكتاب ص 51 — مختبر الفيزياء: التحليل والتوسع'),
('essay', 1, 'ارسم بست نقاط نموذج الجسيم النقطي لكل من: (أ) جسم ساكن، (ب) جسم يتحرك بسرعة ثابتة، ثم صف رسمك في كل حالة.', null, null, null, 'تطبيق', 'رسم نموذج', 'سهل', 'الكتاب ص 51 — مختبر الفيزياء: التحليل والتوسع'),
('essay', 2, 'ارسم نموذج الجسيم النقطي لسيارة تتحرك نحو اليمين بسرعة كبيرة ثم تتباطأ تدريجيًا حتى تتوقف، ثم ارسم نموذجًا آخر لسيارة تسير ببطء ثم تتسارع. وضّح كيف تتغير المسافة بين النقاط في كل نموذج.', null, null, null, 'تطبيق', 'رسم نموذج', 'متوسط', 'الكتاب ص 51 — مختبر الفيزياء: التحليل والتوسع'),
('essay', 3, 'يبين الجدول مواقع سيارة لعبة تتحرك في خط مستقيم، سُجّلت كل 0.1 s. (أ) ارسم نموذج الجسيم النقطي لحركتها على محور مدرج، بحيث يمثل كل 1 cm على الورق 5 cm من الحركة، وحدد موقع كل نقطة على الورق. (ب) ماذا يدل رسمك على حالة حركة السيارة؟', '{"headers":["الزمن (s)","الموقع (cm)"],"rows":[["0.0","0"],["0.1","5"],["0.2","10"],["0.3","15"],["0.4","20"],["0.5","20"],["0.6","20"]]}'::jsonb, null, null, 'تطبيق', 'رسم من بيانات', 'صعب', 'الكتاب ص 55 — مراجعة عامة (السؤال 50)')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
