from (values
('mcq', 1, 2, 'الجسم الذي يتحرك بسرعة ثابتة يقطع مسافات متساوية في فترات زمنية متساوية، فتكون نقاطه متساوية التباعد كما في الصف (3).', '["المسافات بين نقاط الصف (1) تتناقص نحو اليمين، وهذا يمثل جسمًا تتناقص سرعته.","المسافات بين نقاط الصف (2) تتزايد نحو اليمين، وهذا يمثل جسمًا تتزايد سرعته.","","الصف (4) نقطة واحدة، وهذا يمثل جسمًا ساكنًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (55%)"}],"at":"2026-11-18T12:34:59.194Z"}'::jsonb),
('mcq', 2, 0, 'السيارة التي تتباطأ حتى تتوقف تقطع مسافات تتناقص في الفترات الزمنية المتساوية، فتتقارب نقاطها في اتجاه حركتها (نحو اليمين) كما في الصف (4).', '["","تتباعد نقاط الصف (1) نحو اليمين، فهو يمثل سيارة تتزايد سرعتها.","نقاط الصف (2) متساوية التباعد، فهو يمثل سيارة سرعتها ثابتة لا تتوقف.","الصف (3) نقطة واحدة، فهو يمثل سيارة ساكنة طوال الوقت."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (60%)"}],"at":"2026-11-18T12:34:59.194Z"}'::jsonb),
('mcq', 3, 1, 'موقع السيارة الساكنة لا يتغير، فتقع النقاط الخمس كلها في الموقع نفسه وتظهر نقطة واحدة.', '["النقاط المتساوية التباعد تمثل جسمًا يتحرك بسرعة ثابتة، لا جسمًا ساكنًا.","","تزايد التباعد يمثل جسمًا تتزايد سرعته.","الجسم الساكن يُمثَّل بنقاط تنطبق في موقع واحد."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-11-18T12:34:59.194Z"}'::jsonb),
('mcq', 4, 3, 'عندما تبدأ السيارة ببطء ثم تتسارع تكون نقاطها متقاربة في البداية ثم يزداد التباعد بينها تدريجيًا في اتجاه الحركة، كما في الصف (4).', '["نقاط الصف (1) متساوية التباعد، فهو يمثل سرعة ثابتة.","نقاط الصف (2) تتقارب نحو اليمين، فهو يمثل سيارة تتباطأ.","نقاط الصف (3) تتباعد ثم تعود فتتقارب، فهو يمثل سيارة تتسارع ثم تتباطأ.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (60%)"}],"at":"2026-11-18T12:34:59.195Z"}'::jsonb),
('mcq', 5, 2, 'مواقع الجدول 0، 2، 6، 12، 20، 30 cm، والصف (3) فقط تقع نقاطه عند هذه القيم على المحور المدرج.', '["نقاط الصف (1) عند 0، 10، 18، 24، 28، 30 cm، وهي تمثل سيارة تتباطأ، عكس بيانات الجدول.","نقاط الصف (2) تنتهي عند 22 cm لا عند 30 cm؛ فآخر نقطة لا تطابق الجدول.","","نقاط الصف (4) متساوية التباعد (كل 6 cm)، وهذا يطابق الموقع الابتدائي والنهائي فقط دون المواقع بينهما."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (42%)"}],"at":"2026-11-18T12:34:59.195Z"}'::jsonb),
('mcq', 6, 1, 'في الزمن نفسه قطع B ثلاثة أرباع ما قطعه A، فكل مسافة بين نقطتين لـ B تساوي ثلاثة أرباع مثيلتها لـ A: $0.75 \times 4.0\ \text{cm} = 3.0\ \text{cm}$.', '["هذا ربع تباعد نقاط A؛ أي مثّل الجزء الذي لم يقطعه B بدل الجزء الذي قطعه.","","هذا ناتج قسمة 4.0 cm على 3/4 بدل ضربه فيه، فجعل B أسرع من A.","تساوي التباعد يعني أن العدّاءين قطعا المسافة نفسها، وB قطع ثلاثة أرباعها فقط."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-11-18T12:34:59.195Z"}'::jsonb),
('mcq', 7, 0, 'الجسم ذو السرعة الثابتة يقطع مسافات متساوية في فترات زمنية متساوية، فتُرسم نقاطه على أبعاد متساوية.', '["","تزايد المسافات يمثل جسمًا تتزايد سرعته.","تناقص المسافات يمثل جسمًا تتناقص سرعته.","انطباق النقاط يمثل جسمًا ساكنًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (32%)"}],"at":"2026-11-18T12:34:59.195Z"}'::jsonb),
('essay', 1, null::int, null, null, '(أ) الجسم الساكن: تنطبق النقاط الست على بعضها في موقع واحد فتظهر نقطة واحدة؛ لأن موقعه لا يتغير. (ب) الجسم ذو السرعة الثابتة: ست نقاط على خط مستقيم بينها مسافات متساوية (مثلًا 1 cm بين كل نقطتين)؛ لأنه يقطع مسافات متساوية في فترات زمنية متساوية.', '["الساكن: نقطة واحدة (نقاط منطبقة)","تعليل الساكن","السرعة الثابتة: نقاط متساوية التباعد","تعليل السرعة الثابتة"]'::jsonb, '[]'::jsonb, '[{"element":"رسم الجسم الساكن","marks":1},{"element":"تعليله","marks":1},{"element":"رسم الجسم ذي السرعة الثابتة","marks":1},{"element":"تعليله","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"رسمان صحيحان مع وصف وتعليل لكل منهما"},{"level":"2–3 درجات","description":"رسمان صحيحان دون تعليل، أو رسم واحد مع تعليله"},{"level":"1 درجة","description":"رسم واحد صحيح دون تعليل"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["رسم ست نقاط متباعدة للجسم الساكن","رسم نقاط غير متساوية للسرعة الثابتة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-11-18T12:34:59.195Z"}'::jsonb),
('essay', 2, null::int, null, null, 'النموذج الأول: نقاط متباعدة في البداية تتقارب تدريجيًا نحو اليمين حتى تكاد آخر النقاط تنطبق عند موقع التوقف؛ لأن المسافة المقطوعة في كل فترة زمنية متساوية تقل. النموذج الثاني: نقاط متقاربة في البداية تتباعد تدريجيًا نحو اليمين؛ لأن المسافة المقطوعة في كل فترة تزداد.', '["نموذج التباطؤ: تباعد ثم تقارب حتى التوقف","تعليل التباطؤ","نموذج التسارع: تقارب ثم تباعد","تعليل التسارع"]'::jsonb, '[]'::jsonb, '[{"element":"رسم التباطؤ","marks":1},{"element":"وصف تغير المسافة في التباطؤ","marks":1},{"element":"رسم التسارع","marks":1},{"element":"وصف تغير المسافة في التسارع","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"نموذجان صحيحان مع وصف صحيح لتغير المسافات"},{"level":"2–3 درجات","description":"نموذج واحد صحيح كامل مع جزء من الآخر"},{"level":"1 درجة","description":"نموذج واحد صحيح دون وصف"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عكس النموذجين","رسم المسافات متساوية في النموذجين","إغفال تقارب النقاط عند التوقف"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (32%)"}],"at":"2026-11-18T12:34:59.195Z"}'::jsonb),
('essay', 3, null::int, null, null, '(أ) مواقع النقاط على الورق: 0، 1، 2، 3، 4، 4، 4 cm؛ أي خمس نقاط متساوية التباعد (1 cm بين كل نقطتين)، ثم تنطبق آخر ثلاث نقاط عند 4 cm. (ب) تحركت السيارة بسرعة ثابتة من 0.0 s إلى 0.4 s (قطعت 5 cm في كل 0.1 s)، ثم توقفت (سكنت) عند الموقع 20 cm من 0.4 s إلى 0.6 s.', '["تحويل المقياس: قسمة كل موقع على 5","خمس نقاط متساوية التباعد","ثلاث نقاط منطبقة عند 4 cm","الاستنتاج: سرعة ثابتة ثم سكون"]'::jsonb, '["المقياس: 1 cm على الورق = 5 cm من الحركة","مواقع الورق: $\\frac{0}{5}, \\frac{5}{5}, \\frac{10}{5}, \\frac{15}{5}, \\frac{20}{5}, \\frac{20}{5}, \\frac{20}{5}$؛ أي 0، 1، 2، 3، 4، 4، 4 cm","المسافات بين النقاط الخمس الأولى = 1 cm (متساوية)، والنقاط الثلاث الأخيرة منطبقة"]'::jsonb, '[{"element":"تحويل المقياس ومواقع النقاط","marks":2},{"element":"رسم النقاط المنطبقة","marks":1},{"element":"الاستنتاج الصحيح","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"مواقع صحيحة بالمقياس مع النقاط المنطبقة واستنتاج صحيح"},{"level":"2–3 درجات","description":"رسم صحيح دون استنتاج كامل، أو خطأ في المقياس مع استنتاج صحيح"},{"level":"1 درجة","description":"استنتاج جزئي صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["رسم النقاط بالقيم الأصلية دون تحويل المقياس","رسم سبع نقاط متباعدة بإغفال التوقف","عدّ آخر ثلاث نقاط سرعة متناقصة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (42%)"}],"at":"2026-11-18T12:34:59.196Z"}'::jsonb)
