from (values
('mcq', 1, 'يمثل الشكل الآتي نموذج الجسيم النقطي لطائرة على المدرج في أثناء إقلاعها، والفترات الزمنية بين النقاط متساوية. ماذا يحدث لسرعة الطائرة؟', null, '[{"src":"qimg/phys1/c2l1-o06-plane.svg","alt":"صف أفقي من سبع نقاط، وفوقه سهم يشير إلى اليمين مكتوب بجانبه «اتجاه الحركة». النقاط متقاربة جدًا في اليسار، ثم يزداد التباعد بينها تدريجيًا نحو اليمين، وأكبر مسافة بين آخر نقطتين."}]'::jsonb, '["تتناقص؛ لأن النقاط متقاربة في بداية الحركة","تتزايد؛ لأن المسافات بين النقاط تتزايد في اتجاه الحركة","ثابتة؛ لأن الفترات الزمنية بين النقاط متساوية","تتزايد ثم تتناقص؛ لأن النقاط تتباعد ثم تتقارب"]'::jsonb, 'تحليل', 'تفسير نموذج', 'سهل', 'الكتاب ص 57 — اختبار مقنن (السؤال 1)'),
('mcq', 2, 'يمثل الشكل الآتي نموذج الجسيم النقطي لجسم يتحرك نحو اليسار، والفترات الزمنية بين النقاط متساوية. صف حالة حركة الجسم.', null, '[{"src":"qimg/phys1/c2l1-o06-left.svg","alt":"صف أفقي من ست نقاط، وفوقه في اليسار سهم يشير إلى اليسار مكتوب بجانبه «اتجاه الحركة». أبعد مسافة بين النقطتين في أقصى اليمين، ثم تقل المسافات تدريجيًا نحو اليسار حتى تكون آخر نقطتين في اليسار متقاربتين جدًا."}]'::jsonb, '["سرعته تتناقص؛ لأن النقاط تتقارب في اتجاه حركته","سرعته تتزايد؛ لأن المسافات بين النقاط تكبر من اليسار إلى اليمين","سرعته ثابتة؛ لأنه يتحرك في خط مستقيم","الجسم ساكن؛ لأن آخر نقطتين متقاربتان"]'::jsonb, 'تحليل', 'تفسير نموذج', 'صعب', 'الكتاب ص 51 — مختبر الفيزياء: التحليل والتوسع'),
('mcq', 3, 'سيارة لها فرامل تضغط وتفصل آليًا كل جزء متساوٍ من الثانية، فتترك عجلاتها آثارًا على الطريق في كل مرة تضغط فيها الفرامل، كما في الشكل الآتي. ماذا تستنتج عن حركة السيارة؟', null, '[{"src":"qimg/phys1/c2l1-o06-tire.svg","alt":"منظر من أعلى لطريق رمادي، فوقه سهم يشير إلى اليمين مكتوب بجانبه «اتجاه حركة السيارة». على الطريق صفان متوازيان من آثار العجلات (مستطيلات صغيرة سوداء)، في كل صف ستة آثار، المسافة بينها كبيرة في اليسار وتقل تدريجيًا نحو اليمين حتى يتقارب الأثران الأخيران جدًا. تحت الطريق عبارة «آثار العجلات على الطريق (منظر من أعلى)»."}]'::jsonb, '["سرعتها تتزايد؛ لأن الآثار تتباعد في اتجاه حركتها","سرعتها ثابتة؛ لأن الفرامل تعمل في فترات متساوية","السيارة ساكنة؛ لأن الآثار متوقفة على الطريق","سرعتها تتناقص؛ لأن الآثار تتقارب في اتجاه حركتها"]'::jsonb, 'تحليل', 'تفسير ظاهرة', 'متوسط', 'الكتاب ص 51 — الفيزياء في الحياة'),
('mcq', 4, 'يمثل الشكل الآتي نموذجي الجسيم النقطي لجسمين A وB رُسما بالفترات الزمنية المتساوية نفسها، ويتحرك كل منهما نحو اليمين. أيّ العبارات الآتية صحيحة؟', null, '[{"src":"qimg/phys1/c2l1-o06-two.svg","alt":"صفان من النقاط. الصف العلوي عنوانه «الجسم A» وفيه ست نقاط متساوية التباعد بمسافات صغيرة. الصف السفلي عنوانه «الجسم B» وفيه ست نقاط متساوية التباعد، والمسافة بين كل نقطتين فيه ضعف المسافة في الصف العلوي. النقطة الأولى في الصفين عند الموقع نفسه في اليسار."}]'::jsonb, '["كلاهما سرعته تتزايد، وسرعة B أكبر من سرعة A","كلاهما سرعته ثابتة، وسرعة A أكبر لأن نقاطه متقاربة","كلاهما سرعته ثابتة، وسرعة B أكبر من سرعة A","سرعة A ثابتة، وسرعة B تتزايد لأن نقاطه أكثر تباعدًا"]'::jsonb, 'تحليل', 'مقارنة نموذجين', 'متوسط', 'الكتاب ص 50 — مختبر الفيزياء: عمل رسوم توضيحية للحركة'),
('mcq', 5, 'يمثل الشكل الآتي نموذج الجسيم النقطي لحركة سيارة، والفترات الزمنية بين النقاط متساوية. أيّ وصف لتغير سرعتها صحيح؟', null, '[{"src":"qimg/phys1/c2l1-o06-mixed.svg","alt":"صف أفقي من تسع نقاط، فوقه سهم يشير إلى اليمين مكتوب بجانبه «اتجاه الحركة». المسافات بين النقاط من اليسار إلى اليمين: صغيرة ثم تكبر تدريجيًا في البداية، ثم أربع مسافات متساوية في الوسط، ثم تصغر تدريجيًا في النهاية حتى تتقارب آخر نقطتين."}]'::jsonb, '["تتناقص، ثم تبقى ثابتة، ثم تتزايد","تتزايد طوال الحركة","ثابتة طوال الحركة","تتزايد، ثم تبقى ثابتة، ثم تتناقص"]'::jsonb, 'تحليل', 'تفسير نموذج', 'صعب', 'الكتاب ص 51 — مختبر الفيزياء: التحليل والتوسع'),
('mcq', 6, 'في نموذج جسيم نقطي مرسوم بفترات زمنية متساوية، تتقارب النقاط المتتالية تدريجيًا في اتجاه الحركة. علامَ يدل ذلك؟', null, null, '["على أن سرعة الجسم تتزايد","على أن سرعة الجسم ثابتة","على أن سرعة الجسم تتناقص","على أن الجسم ساكن"]'::jsonb, 'فهم', 'تفسير', 'سهل', 'الكتاب ص 51 — مختبر الفيزياء: التحليل والتوسع'),
('mcq', 7, 'سُجّلت المسافات بين النقاط المتتالية في نموذج الجسيم النقطي لعدّاء (بفترات زمنية متساوية) بالترتيب: 1.2 m، 1.8 m، 2.4 m، 2.4 m، 2.4 m. صف حركة العدّاء.', null, null, '["تزايدت سرعته، ثم أصبحت ثابتة","تناقصت سرعته، ثم أصبحت ثابتة","سرعته ثابتة طوال الحركة","تزايدت سرعته طوال الحركة"]'::jsonb, 'تحليل', 'تفسير بيانات', 'متوسط', 'الكتاب ص 51 — مختبر الفيزياء: التحليل والتوسع'),
('essay', 1, 'يمثل الشكل الآتي نموذج الجسيم النقطي لجسم يتحرك نحو اليمين، والفترات الزمنية بين النقاط المتتالية متساوية. (أ) صف كيف تتغير المسافات بين النقاط المتتالية في اتجاه الحركة. (ب) ماذا تستنتج عن سرعة الجسم؟ علّل. (ج) أيّ الحركات الآتية يمكن أن يمثلها هذا النموذج: سيارة تنطلق من إشارة مرورية عندما تصبح خضراء، أم سيارة تقترب من إشارة مرورية لتتوقف عندها، أم دراج يسير بسرعة ثابتة؟ علّل.', null, '[{"src":"qimg/phys1/c2l1-o06-right.svg","alt":"صف أفقي من ست نقاط، وفوقه في اليسار سهم يشير إلى اليمين مكتوب بجانبه «اتجاه الحركة». المسافة بين أول نقطتين في اليسار صغيرة، ثم تكبر المسافات بين النقاط المتتالية تدريجيًا نحو اليمين، وأكبرها بين آخر نقطتين."}]'::jsonb, null, 'تحليل', 'تفسير نموذج', 'سهل', 'الكتاب ص 51 — مختبر الفيزياء: التحليل والتوسع'),
('essay', 2, 'يمثل الشكل الآتي نموذج الجسيم النقطي لكرة تتدحرج نحو اليمين على محور مدرج بالسنتيمتر، والفترة الزمنية بين كل نقطتين 0.1 s. (أ) اقرأ مواقع النقاط، واحسب المسافات بين النقاط المتتالية. (ب) صف حالة حركة الكرة في كل جزء من حركتها.', null, '[{"src":"qimg/phys1/c2l1-o06-essay.svg","alt":"صف أفقي من سبع نقاط فوقه سهم نحو اليمين مكتوب بجانبه «اتجاه الحركة»، وتحته محور مدرج من 0 إلى 20 بخطوة 2 عنوانه «الموقع (cm)». النقاط عند المواقع 0 و4 و8 و12 و15 و17 و18."}]'::jsonb, null, 'تحليل', 'تحليل نموذج مدرج', 'متوسط', 'الكتاب ص 51 — مختبر الفيزياء: التحليل والتوسع'),
('essay', 3, 'رُسم نموذجا الجسيم النقطي لعدّاءين A وB بالفترات الزمنية المتساوية نفسها، وكانت المسافات بين النقاط المتتالية بالترتيب: للعدّاء A: 3 m، 3 m، 3 m، 3 m، وللعدّاء B: 5 m، 4 m، 3 m، 2 m. قال طالب: «العدّاء B أسرع من A طوال الحركة». قوّم قول الطالب، ثم صف حركة كل منهما.', null, null, null, 'تقويم', 'تقويم ادعاء', 'صعب', 'الكتاب ص 51 — مختبر الفيزياء: التحليل والتوسع')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
