from (values
('mcq', 1, 1, 'في فترات زمنية متساوية تقطع الطائرة مسافات تتزايد باستمرار في اتجاه حركتها، فسرعتها تتزايد.', '["تقارب النقاط في البداية ثم تباعدها يعني أن السرعة كانت صغيرة ثم زادت.","","تساوي الفترات الزمنية شرط في رسم كل النماذج، والذي يحدد السرعة هو تباعد النقاط.","النقاط في الشكل تتباعد باستمرار ولا تعود فتتقارب."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (44%)"}],"at":"2026-11-18T12:34:59.196Z"}'::jsonb),
('mcq', 2, 0, 'يبدأ الجسم من اليمين ويتحرك نحو اليسار، والمسافات التي يقطعها في الفترات الزمنية المتساوية تقل في اتجاه حركته، فسرعته تتناقص.', '["","قُرئ النموذج من اليسار إلى اليمين، والجسم يتحرك نحو اليسار؛ ففي اتجاه حركته تتقارب النقاط.","الحركة في خط مستقيم لا تعني ثبات السرعة؛ فالمسافات بين النقاط غير متساوية.","النقاط في مواقع مختلفة، فالجسم يتحرك وإن كانت سرعته تقل."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (44%)"}],"at":"2026-11-18T12:34:59.197Z"}'::jsonb),
('mcq', 3, 3, 'الآثار تمثل مواقع السيارة في فترات زمنية متساوية، وهي تتقارب في اتجاه الحركة، فالسيارة تقطع مسافات أقل فأقل، أي أن سرعتها تتناقص.', '["الآثار في الشكل تتقارب في اتجاه الحركة لا تتباعد.","تساوي الفترات يجعل تباعد الآثار دليلًا على السرعة، والتباعد هنا يقل.","الآثار ثابتة على الطريق لكنها في مواقع مختلفة، فالسيارة تحركت.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-11-18T12:34:59.197Z"}'::jsonb),
('mcq', 4, 2, 'نقاط كل جسم متساوية التباعد فسرعة كل منهما ثابتة، والمسافة بين نقاط B ضعف المسافة بين نقاط A في الفترة نفسها، فـ B أسرع.', '["نقاط كل جسم متساوية التباعد، فسرعة كل منهما ثابتة لا متزايدة.","تقارب النقاط يعني مسافة أقل في الفترة نفسها، أي سرعة أقل.","","التباعد الأكبر الثابت يعني سرعة أكبر ثابتة، لا سرعة متزايدة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-11-18T12:34:59.197Z"}'::jsonb),
('mcq', 5, 3, 'في البداية تتزايد المسافات بين النقاط (سرعة تتزايد)، ثم تتساوى في الوسط (سرعة ثابتة)، ثم تتناقص في النهاية (سرعة تتناقص)، في اتجاه الحركة نحو اليمين.', '["قُرئ النموذج عكس اتجاه الحركة؛ فالسيارة تتحرك نحو اليمين.","المسافات في الوسط متساوية ثم تقل في النهاية، فالسرعة لا تتزايد طوال الحركة.","المسافات بين النقاط غير متساوية في البداية والنهاية.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (44%)"}],"at":"2026-11-18T12:34:59.197Z"}'::jsonb),
('mcq', 6, 2, 'تقارب النقاط يعني أن الجسم يقطع مسافات أقل فأقل في فترات زمنية متساوية، فسرعته تتناقص.', '["تزايد السرعة يجعل النقاط تتباعد في اتجاه الحركة، لا تتقارب.","السرعة الثابتة تجعل المسافات بين النقاط متساوية.","","الجسم الساكن تنطبق نقاطه في موقع واحد، وهنا المواقع مختلفة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-11-18T12:34:59.198Z"}'::jsonb),
('mcq', 7, 0, 'المسافات تتزايد من 1.2 m إلى 1.8 m إلى 2.4 m (سرعة تتزايد)، ثم تتساوى عند 2.4 m (سرعة ثابتة).', '["","المسافات تكبر في البداية (من 1.2 m إلى 2.4 m) فالسرعة تتزايد لا تتناقص.","المسافات الأولى غير متساوية، فالسرعة لم تكن ثابتة في البداية.","المسافات الثلاث الأخيرة متساوية، فالسرعة ثابتة في هذا الجزء."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (30%)"}],"at":"2026-11-18T12:34:59.198Z"}'::jsonb),
('essay', 1, null::int, null, null, '(أ) المسافات بين النقاط المتتالية تتزايد تدريجيًا في اتجاه الحركة (نحو اليمين). (ب) سرعة الجسم تتزايد؛ لأنه يقطع مسافات أكبر فأكبر في فترات زمنية متساوية. (ج) السيارة التي تنطلق من الإشارة عندما تصبح خضراء؛ لأنها تبدأ ببطء ثم تتزايد سرعتها فتتباعد نقاطها، أما السيارة التي تقترب من الإشارة لتتوقف فتتقارب نقاطها، والدراج ذو السرعة الثابتة تكون نقاطه متساوية التباعد.', '["المسافات تتزايد في اتجاه الحركة","السرعة تتزايد مع التعليل بالمسافات في فترات متساوية","اختيار السيارة المنطلقة من الإشارة مع استبعاد الحالتين الأخريين"]'::jsonb, '[]'::jsonb, '[{"element":"وصف تغير المسافات","marks":1},{"element":"الاستنتاج عن السرعة مع التعليل","marks":1},{"element":"اختيار الحركة المناسبة مع التعليل","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"يصف تغير المسافات ويستنتج تزايد السرعة ويختار الحركة المناسبة معللًا"},{"level":"2 درجتان","description":"يصف ويستنتج دون اختيار صحيح معلل للحركة"},{"level":"1 درجة","description":"يصف تغير المسافات فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["الحكم بتناقص السرعة لأن النقاط متقاربة في البداية","اختيار السيارة التي تقترب من الإشارة لتتوقف","اختيار الدراج لأن النقاط على خط مستقيم"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (31%)"}],"at":"2026-11-18T12:34:59.198Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) المواقع: 0، 4، 8، 12، 15، 17، 18 cm. المسافات بين النقاط المتتالية: 4، 4، 4، 3، 2، 1 cm. (ب) في الجزء الأول (المسافات الثلاث الأولى متساوية 4 cm) تتحرك الكرة بسرعة ثابتة، ثم تتناقص المسافات (3، 2، 1 cm) فتتناقص سرعة الكرة حتى تكاد تتوقف.', '["قراءة المواقع","حساب المسافات 4، 4، 4، 3، 2، 1 cm","سرعة ثابتة في البداية","سرعة متناقصة في النهاية"]'::jsonb, '["المواقع من المحور: 0، 4، 8، 12، 15، 17، 18 cm","المسافات: $4-0,\\ 8-4,\\ 12-8,\\ 15-12,\\ 17-15,\\ 18-17$؛ أي 4، 4، 4، 3، 2، 1 cm"]'::jsonb, '[{"element":"قراءة المواقع","marks":1},{"element":"حساب المسافات","marks":1},{"element":"وصف الجزء الأول","marks":1},{"element":"وصف الجزء الثاني","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"قراءات وحسابات صحيحة ووصف صحيح للجزأين"},{"level":"2–3 درجات","description":"حسابات صحيحة مع وصف جزء واحد، أو خطأ قراءة واحد مع وصف صحيح"},{"level":"1 درجة","description":"قراءة المواقع فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["الحكم بأن السرعة تتناقص طوال الحركة","الخلط بين المواقع والمسافات بين النقاط"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (36%)"}],"at":"2026-11-18T12:34:59.199Z"}'::jsonb),
('essay', 3, null::int, null, null, 'قول الطالب غير صحيح. A يتحرك بسرعة ثابتة (مسافات متساوية 3 m). أما B فسرعته تتناقص (المسافات تقل من 5 m إلى 2 m). في الفترتين الأولى والثانية كان B أسرع (5 m و4 m أكبر من 3 m)، وفي الفترة الثالثة تساوت سرعتاهما (3 m لكل منهما)، وفي الفترة الرابعة أصبح A أسرع (3 m أكبر من 2 m). فـ B ليس أسرع طوال الحركة.', '["الحكم بخطأ القول","A سرعته ثابتة","B سرعته تتناقص","المقارنة في كل فترة: B أسرع ثم تساوٍ ثم A أسرع"]'::jsonb, '[]'::jsonb, '[{"element":"الحكم","marks":1},{"element":"وصف حركة A","marks":1},{"element":"وصف حركة B","marks":1},{"element":"المقارنة عبر الفترات","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"يحكم ويصف الحركتين ويقارن في كل فترة"},{"level":"2–3 درجات","description":"يصف الحركتين دون مقارنة كاملة"},{"level":"1 درجة","description":"يحكم بخطأ القول دون تعليل"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["الموافقة على القول لأن B بدأ بمسافة أكبر","عدّ سرعة B ثابتة","مقارنة مجموع المسافات فقط"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (26%)"}],"at":"2026-11-18T12:34:59.200Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
