select (select id from public.objectives where code = 'P1-C2-L1-O07'), v.type, v.number, v.stem, v.stimulus::jsonb, v.images::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'تبين اللقطات الآتية سيارة لعبة تتحرك بجوار مسطرة مدرجة بالسنتيمتر، وقد التُقطت كل 0.1 s. عند جمع اللقطات في صورة واحدة لتكوين مخطط توضيحي للحركة، كم تكون المسافة بين كل موقعين متتاليين للسيارة؟', null, '[{"src":"qimg/phys1/c2l1-o07-frames.svg","alt":"أربع لقطات مرتبة من أعلى إلى أسفل. في كل لقطة مسطرة أفقية مدرجة من 0 إلى 100 بخطوة 10 ووحدتها cm، وفوقها سيارة لعبة وتحت منتصف السيارة علامة حمراء على المسطرة. اللقطة 1 (t = 0.0 s): العلامة عند 10. اللقطة 2 (t = 0.1 s): العلامة عند 30. اللقطة 3 (t = 0.2 s): العلامة عند 50. اللقطة 4 (t = 0.3 s): العلامة عند 70."}]'::jsonb, '["10 cm","60 cm","20 cm","70 cm"]'::jsonb, 'تطبيق', 'قراءة لقطات', 'متوسط', 'الكتاب ص 50 — مختبر الفيزياء: عمل رسوم توضيحية للحركة'),
('mcq', 2, 'يبين الجدول مواقع سيارة لعبة قرئت من لقطات متتابعة التُقطت كل 0.1 s. أيّ المخططات المرقمة في الشكل الآتي يمثل المخطط التوضيحي الصحيح لحركتها؟', '{"headers":["الزمن (s)","الموقع (cm)"],"rows":[["0.0","10"],["0.1","20"],["0.2","40"],["0.3","70"]]}'::jsonb, '[{"src":"qimg/phys1/c2l1-o07-candidates.svg","alt":"أربعة مخططات مرقمة (1) إلى (4) من أعلى إلى أسفل، في كل منها مسطرة مدرجة من 0 إلى 80 بخطوة 10 ووحدتها cm، وفوقها أربع صور لسيارة لعبة تزداد وضوحًا نحو اليمين، وتحت منتصف كل صورة علامة حمراء. المخطط (1): العلامات عند 10 و20 و40 و70. المخطط (2): عند 10 و25 و40 و55. المخطط (3): عند 10 و30 و50 و70. المخطط (4): عند 10 و40 و60 و70."}]'::jsonb, '["المخطط (2)","المخطط (1)","المخطط (3)","المخطط (4)"]'::jsonb, 'تطبيق', 'تمثيل بيانات', 'متوسط', 'الكتاب ص 50 — مختبر الفيزياء: عمل رسوم توضيحية للحركة'),
('mcq', 3, 'صُوّرت حركة سيارة لعبة بكاميرا فيديو، ثم عُرضت لقطات الفيديو عند اللحظات 0.0 و0.1 و0.2 و0.3 و0.4 و0.5 و0.6 s. يُراد إنشاء مخطط توضيحي لحركة السيارة من أربع لقطات فقط. أيّ مجموعات اللقطات الآتية يصح اختيارها؟', null, null, '["اللقطات عند 0.0 و0.2 و0.4 و0.6 s","اللقطات عند 0.0 و0.1 و0.3 و0.6 s","اللقطات عند 0.0 و0.1 و0.4 و0.5 s","اللقطات التي تبدو فيها السيارة على مسافات متساوية"]'::jsonb, 'تطبيق', 'اختيار بيانات', 'صعب', 'الكتاب ص 50 — مختبر الفيزياء: عمل رسوم توضيحية للحركة'),
('mcq', 4, 'تبين الصور الأربع الآتية عدّاءً أمام شجرة ثابتة، وقد التُقطت في فترات زمنية متساوية. ما الطريقة الصحيحة لتمثيل حركته بمخطط توضيحي للحركة؟', null, '[{"src":"qimg/phys1/c2l1-o07-runner-frames.svg","alt":"أربع صور متجاورة مرقمة من اليسار إلى اليمين: الصورة 1 إلى الصورة 4. في كل صورة أرض خضراء وشجرة في المنتصف في الموقع نفسه، وعدّاء يجري نحو اليمين. موقع العدّاء: في الصورة 1 يسار الشجرة بوضوح، وفي الصورة 2 قرب جذع الشجرة من اليسار، وفي الصورة 3 أمام الشجرة تقريبًا، وفي الصورة 4 يمين الشجرة."}]'::jsonb, '["رسم الشجرة في أربعة مواقع مختلفة والعدّاء في موقع واحد","الاكتفاء بالصورة الأخيرة لأنها تبين موقع العدّاء النهائي","رسم منحنى (الموقع – الزمن) للشجرة والعدّاء معًا","جمع الصور في صورة واحدة تظهر فيها الشجرة مرة واحدة والعدّاء في مواقعه الأربعة"]'::jsonb, 'تطبيق', 'إجراء', 'سهل', 'الكتاب ص 32 — المخططات التوضيحية للحركة'),
('mcq', 5, 'في نشاط لتمثيل حركة سيارة لعبة بمخطط توضيحي، صُوّرت حركتها بكاميرا فيديو. لماذا تُثبّت مسطرة مترية بموازاة مسار السيارة؟', null, null, '["لقياس الفترة الزمنية بين اللقطات","لجعل السيارة تتحرك بسرعة ثابتة","لقراءة موقع السيارة في كل لقطة وتسجيله","لقياس كتلة السيارة"]'::jsonb, 'فهم', 'تفسير إجراء', 'سهل', 'الكتاب ص 50 — مختبر الفيزياء: عمل رسوم توضيحية للحركة'),
('mcq', 6, 'صُوّرت سيارة كل 0.5 s، فكانت مواقعها بالترتيب: 0 m، 3 m، 6 m، 9 m. أُضيفت إلى المخطط التوضيحي صورة خامسة التُقطت بعد 0.5 s أخرى، وقد استمرت السيارة بالسرعة نفسها. عند أيّ موقع تُرسم الصورة الخامسة؟', null, null, '["9 m","12 m","15 m","18 m"]'::jsonb, 'تطبيق', 'توقع موقع', 'صعب', 'الكتاب ص 50 — مختبر الفيزياء: عمل رسوم توضيحية للحركة'),
('mcq', 7, 'عند جمع صور متتابعة التُقطت بآلة تصوير ثابتة لتكوين مخطط توضيحي للحركة، كيف تظهر خلفية الصور كالأشجار والمباني؟', null, null, '["في المكان نفسه في كل الصور","في مواقع مختلفة تتحرك مع الجسم","مكررة في مواقع متتالية","مكبرة لتوضيح المسافات"]'::jsonb, 'فهم', 'إجراء', 'متوسط', 'الكتاب ص 32 — المخططات التوضيحية للحركة'),
('essay', 1, 'اكتب خطوات تمثيل حركة عدّاء بمخطط توضيحي للحركة باستعمال آلة تصوير.', null, null, null, 'تطبيق', 'كتابة إجراء', 'سهل', 'الكتاب ص 32 — المخططات التوضيحية للحركة'),
('essay', 2, 'سُجّلت مواقع سيارتين لعبتين بطيئة وسريعة كل 0.1 s كما في الجدول. (أ) صف المخطط التوضيحي لحركة كل سيارة إذا رُسما فوق محور واحد. (ب) كيف يختلف المخطط التوضيحي لحركة السيارة السريعة عن مخطط السيارة البطيئة؟', '{"headers":["الزمن (s)","موقع السيارة البطيئة (cm)","موقع السيارة السريعة (cm)"],"rows":[["0.0","0","0"],["0.1","4","9"],["0.2","8","18"],["0.3","12","27"],["0.4","16","36"],["0.5","20","45"]]}'::jsonb, null, null, 'تطبيق', 'تمثيل ومقارنة', 'متوسط', 'الكتاب ص 51 — مختبر الفيزياء: التحليل والتوسع'),
('essay', 3, 'أراد طالب تمثيل حركة سيارة لعبة تنزل مستوى مائلًا بمخطط توضيحي للحركة، فالتقط صورًا عند اللحظات 0.0، 0.1، 0.2، 0.4، 0.5 s فقط (فاتته اللقطة عند 0.3 s)، فكانت مواقع السيارة بالترتيب 0، 1، 4، 16، 25 cm. (أ) ما المشكلة في جمع هذه الصور كما هي في مخطط توضيحي؟ (ب) إذا علمت أن موقع السيارة عند 0.3 s كان 9 cm، فاكتب المسافات بين المواقع المتتالية في المخطط المكتمل، وبيّن ما يدل عليه.', null, null, null, 'تحليل', 'تقويم وتمثيل', 'صعب', 'الكتاب ص 50 — مختبر الفيزياء: عمل رسوم توضيحية للحركة')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
