('mcq', 1, 2, 'المواقع على المسطرة: 10، 30، 50، 70 cm، فالمسافة بين كل موقعين متتاليين $= 30 - 10 = 20\ \text{cm}$.', '["هذا موقع السيارة في اللقطة الأولى، لا المسافة بين موقعين متتاليين.","هذه المسافة الكلية من اللقطة الأولى إلى الأخيرة ($70 - 10$)، لا بين لقطتين متتاليتين.","","هذا موقع السيارة في اللقطة الأخيرة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-11-18T12:34:59.200Z"}'::jsonb),
('mcq', 2, 1, 'مواقع الجدول 10، 20، 40، 70 cm، وهي مواقع السيارة (العلامات الحمراء) في المخطط (1).', '["مواقع السيارة في المخطط (2) هي 10، 25، 40، 55 cm بمسافات متساوية، ولا تطابق الجدول.","","مواقع السيارة في المخطط (3) هي 10، 30، 50، 70 cm بمسافات متساوية، ولا تطابق الموقعين الثاني والثالث في الجدول.","مواقع السيارة في المخطط (4) هي 10، 40، 60، 70 cm، أي بترتيب المسافات المعكوس."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-11-18T12:34:59.200Z"}'::jsonb),
('mcq', 3, 0, 'يُنشأ المخطط التوضيحي للحركة من لقطات تفصل بينها فترات زمنية متساوية، واللقطات عند 0.0 و0.2 و0.4 و0.6 s تفصل بينها فترات متساوية مقدار كل منها 0.2 s.', '["","الفترات بين هذه اللقطات 0.1 s ثم 0.2 s ثم 0.3 s، وهي غير متساوية.","الفترات بين هذه اللقطات 0.1 s ثم 0.3 s ثم 0.1 s، وهي غير متساوية.","المسافات لا يُشترط تساويها؛ واختيار اللقطات بحسب المسافات يجعل الفترات الزمنية غير متساوية إذا تغيرت سرعة السيارة، والشرط تساوي الفترات الزمنية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-11-18T12:34:59.201Z"}'::jsonb),
('mcq', 4, 3, 'نرتب الصور المتتابعة ونجمعها في صورة واحدة بحيث تبقى الخلفية الثابتة (الشجرة) في مكانها، ويظهر العدّاء في مواقعه المتتالية.', '["الشجرة ثابتة فتبقى في مكانها، والعدّاء هو الذي تتغير مواقعه.","صورة واحدة تُظهر موقعًا واحدًا فقط، والمخطط يُظهر المواقع المتتالية.","هذا رسم بياني، والمطلوب مخطط توضيحي يجمع الصور.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-11-18T12:34:59.201Z"}'::jsonb),
('mcq', 5, 2, 'تُقرأ مواقع السيارة من المسطرة المترية في كل لقطة وتُدوَّن في جدول البيانات، ثم تُستخدم في رسم المخطط.', '["الفترة الزمنية تُحدد من الفيديو (زمن اللقطات)، لا من المسطرة.","المسطرة لا تؤثر في سرعة السيارة.","","المسطرة تقيس الأطوال، والكتلة لا تلزم لتمثيل الحركة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-11-18T12:34:59.201Z"}'::jsonb),
('mcq', 6, 1, 'تقطع السيارة 3 m في كل 0.5 s، فبعد فترة أخرى يكون موقعها $9\ \text{m} + 3\ \text{m} = 12\ \text{m}$.', '["هذا الموقع الرابع نفسه، وكأن السيارة توقفت، مع أنها استمرت بالسرعة نفسها.","","هذا ناتج إضافة مسافتين (6 m)، أي فترتين زمنيتين بدل فترة واحدة.","هذا ضعف الموقع الرابع، وليس الموقع بعد فترة واحدة أخرى."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-18T12:34:59.201Z"}'::jsonb),
('mcq', 7, 0, 'الخلفية ثابتة فتبقى في المكان نفسه في كل الصور، بينما يظهر الجسم المتحرك في موقع مختلف في كل صورة؛ فيبين المخطط مواقعه المتتالية.', '["","آلة التصوير ثابتة، فلا يتغير مكان الخلفية بين الصور.","الخلفية ثابتة فتنطبق صورها في المكان نفسه ولا تتكرر في مواقع مختلفة.","الصور تُجمع كما هي دون تكبير الخلفية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-11-18T12:34:59.201Z"}'::jsonb),
('essay', 1, null::int, null, null, '1) نثبت آلة التصوير في مكان واحد بحيث تبقى الخلفية ثابتة. 2) نلتقط سلسلة من الصور المتتابعة للعدّاء في فترات زمنية متساوية. 3) نرتب الصور بحسب زمن التقاطها. 4) نجمعها في صورة واحدة تظهر فيها الخلفية مرة واحدة والعدّاء في مواقعه المتتالية.', '["تثبيت آلة التصوير","التقاط صور متتابعة في فترات زمنية متساوية","ترتيب الصور","جمعها في صورة واحدة"]'::jsonb, '[]'::jsonb, '[{"element":"تثبيت آلة التصوير","marks":1},{"element":"فترات زمنية متساوية","marks":1},{"element":"ترتيب الصور","marks":1},{"element":"الجمع في صورة واحدة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"يذكر الخطوات الأربع مرتبة"},{"level":"2–3 درجات","description":"يذكر خطوتين أو ثلاثًا صحيحة"},{"level":"1 درجة","description":"يذكر خطوة واحدة"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["إغفال تساوي الفترات الزمنية","تحريك آلة التصوير مع العدّاء"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-11-18T12:34:59.201Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) السيارة البطيئة: ست صور عند 0، 4، 8، 12، 16، 20 cm؛ المسافة بين كل صورتين 4 cm. السيارة السريعة: ست صور عند 0، 9، 18، 27، 36، 45 cm؛ المسافة بين كل صورتين 9 cm. (ب) في المخططين المسافات متساوية (سرعة كل منهما ثابتة)، لكن صور السيارة السريعة متباعدة أكثر (9 cm مقابل 4 cm) وتمتد إلى مسافة أبعد (45 cm مقابل 20 cm) في الزمن نفسه.', '["مواقع البطيئة وتباعدها 4 cm","مواقع السريعة وتباعدها 9 cm","كلاهما بمسافات متساوية","صور السريعة أكثر تباعدًا"]'::jsonb, '["تباعد البطيئة $= 4 - 0 = 4\\ \\text{cm}$","تباعد السريعة $= 9 - 0 = 9\\ \\text{cm}$"]'::jsonb, '[{"element":"مخطط البطيئة","marks":1},{"element":"مخطط السريعة","marks":1},{"element":"المقارنة","marks":2}]'::jsonb, '[{"level":"4 درجات","description":"يصف المخططين بدقة ويقارن بينهما"},{"level":"2–3 درجات","description":"يصف المخططين دون مقارنة كاملة"},{"level":"1 درجة","description":"يصف مخططًا واحدًا"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدّ التباعد الأكبر دليلًا على تزايد السرعة","رسم المخططين بفترات زمنية مختلفة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-11-18T12:34:59.202Z"}'::jsonb),
('essay', 3, null::int, null, null, '(أ) الفترات الزمنية بين الصور غير متساوية (0.1 s ثم 0.2 s بين 0.2 s و0.4 s)، فلا يمثل تباعد الصور سرعة السيارة تمثيلًا صحيحًا. (ب) المواقع المكتملة: 0، 1، 4، 9، 16، 25 cm، والمسافات بينها: 1، 3، 5، 7، 9 cm؛ وهي تتزايد في اتجاه الحركة، فسرعة السيارة تتزايد في أثناء نزولها المستوى المائل.', '["الفترات الزمنية غير متساوية","المواقع المكتملة","المسافات 1، 3، 5، 7، 9 cm","السرعة تتزايد"]'::jsonb, '["المواقع المكتملة: 0، 1، 4، 9، 16، 25 cm","المسافات: $1-0,\\ 4-1,\\ 9-4,\\ 16-9,\\ 25-16$؛ أي 1، 3، 5، 7، 9 cm"]'::jsonb, '[{"element":"تحديد المشكلة","marks":1},{"element":"حساب المسافات","marks":2},{"element":"الاستنتاج","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"يحدد المشكلة ويحسب المسافات كلها ويستنتج تزايد السرعة"},{"level":"2–3 درجات","description":"يحسب المسافات ويستنتج دون تحديد المشكلة، أو العكس"},{"level":"1 درجة","description":"يحدد المشكلة فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدّ المشكلة في عدم تساوي المسافات","حساب المسافة $16 - 4 = 12\\ \\text{cm}$ بين صورتين متتاليتين","استنتاج سرعة ثابتة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-18T12:34:59.202Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
