('mcq', 1, 'متى يمكن معاملة الجسم المتحرك كجسيم نقطي؟', null, null, '["عندما تكون كتلته صغيرة جدًا مقارنة بكتل الأجسام حوله","عندما يتحرك بسرعة ثابتة في خط مستقيم فقط","عندما يكون حجمه صغيرًا جدًا مقارنة بالمسافة التي يتحركها","عندما يكون ساكنًا لا يتغير موقعه"]'::jsonb, 'تذكر', 'تذكر شرط', 'سهل', 'الكتاب ص 54 — إتقان المفاهيم (السؤالان 35 و36)'),
('mcq', 2, 'يبين الشكل الآتي حالتين لحركة سيارة: (1) دخولها مرآبًا طوله 6 m، و(2) سفرها بين مدينتين تفصل بينهما 400 km. في أيّ الحالتين يمكن تمثيل السيارة بجسيم نقطي؟', null, '[{"src":"qimg/phys1/c2l1-o08-scenes.svg","alt":"لوحتان مرقمتان. اللوحة (1): مرآب مستطيل وسيارة تدخل إليه وتملأ معظم طوله، وتحته سهم مزدوج الرأس مكتوب عليه 6 m يمثل طول المرآب، وبجانبه كلمة «مرآب». اللوحة (2): دائرتان صغيرتان مكتوب تحت كل منهما «مدينة»، يصل بينهما خط برتقالي مكتوب فوقه 400 km."}]'::jsonb, '["الحالة (2) فقط؛ لأن حجم السيارة صغير جدًا مقارنة بـ 400 km","الحالة (1) فقط؛ لأن المسافة قصيرة فيسهل تتبع السيارة","الحالتين معًا؛ لأن السيارة نفسها في الحالتين","لا يمكن في أيّ منهما؛ لأن السيارة جسم كبير"]'::jsonb, 'فهم', 'تطبيق شرط على رسم', 'متوسط', 'الكتاب ص 33 — نموذج الجسيم النقطي'),
('mcq', 3, 'أيّ الحالات الآتية يصح فيها استعمال نموذج الجسيم النقطي؟', null, null, '["لاعب جمباز يؤدي حركات دوران على البساط","طائرة تطير من الرياض إلى جدة","باب غرفة يُفتح حول مفصلاته","سيارة تدخل موقفًا ضيقًا بين سيارتين"]'::jsonb, 'فهم', 'تطبيق شرط', 'سهل', 'الكتاب ص 33 — نموذج الجسيم النقطي'),
('mcq', 4, 'أيّ الحالات الآتية لا يصلح فيها استعمال نموذج الجسيم النقطي؟', null, null, '["الأرض في دورانها حول الشمس","حافلة تقطع 300 km بين مدينتين","طائر يهاجر آلاف الكيلومترات","عجلة دراجة تدور حول محورها"]'::jsonb, 'فهم', 'تطبيق شرط', 'متوسط', 'الكتاب ص 33 — نموذج الجسيم النقطي'),
('mcq', 5, 'كرة قطرها 0.22 m. في أيّ الحالات الآتية تكون معاملتها كجسيم نقطي أنسب؟', null, null, '["عندما تتدحرج مسافة 60 m","عندما تتدحرج مسافة 0.3 m","عندما تتدحرج مسافة 0.5 m","عندما تتدحرج مسافة 0.7 m"]'::jsonb, 'تحليل', 'مقارنة نسب', 'متوسط', 'الكتاب ص 33 — نموذج الجسيم النقطي'),
('mcq', 6, 'يمكن تمثيل حافلة بجسيم نقطي عند دراسة رحلتها بين مدينتين، ولا يمكن ذلك عند دراسة دخولها إلى موقف الحافلات. ما سبب الاختلاف؟', null, null, '["سرعة الحافلة كبيرة في أثناء الرحلة، وصغيرة عند دخولها الموقف","كتلة الحافلة تتغير بتغير عدد الركاب في كل حالة","المسافة في الرحلة كبيرة جدًا مقارنة بحجم الحافلة، وفي الموقف تقاربه","زمن الرحلة أطول كثيرًا من زمن الدخول إلى الموقف"]'::jsonb, 'تحليل', 'تفسير', 'صعب', 'الكتاب ص 33 — نموذج الجسيم النقطي'),
('mcq', 7, 'لماذا يُشترط أن يكون حجم الجسم صغيرًا جدًا مقارنة بالمسافة التي يتحركها لاستعمال نموذج الجسيم النقطي؟', null, null, '["لأن الأجسام الصغيرة تتحرك دائمًا بسرعة ثابتة","لأن أبعاد الجسم وحركة أجزائه تصبح مهملة مقارنة بحركته الكلية","لأن النقطة لا يمكن أن تمثل إلا أجسامًا دقيقة جدًا كالذرات","لأن الجسم الكبير لا تتغير مواقعه في أثناء الحركة"]'::jsonb, 'فهم', 'تعليل', 'متوسط', 'الكتاب ص 33 — نموذج الجسيم النقطي'),
('essay', 1, 'متى يمكن معاملة الجسم كجسيم نقطي؟ أعطِ مثالًا يصح فيه ذلك، ومثالًا لا يصح، مع التعليل.', null, null, null, 'فهم', 'شرط مع أمثلة', 'سهل', 'الكتاب ص 54 — إتقان المفاهيم (السؤالان 35 و36)'),
('essay', 2, 'حدّد في كل حالة من الحالات الآتية هل يصلح تمثيل الجسم بجسيم نقطي، مع التعليل: (أ) الأرض في دورانها حول الشمس. (ب) لاعب يؤدي حركة دوران على عارضة. (ج) سفينة تعبر البحر الأحمر. (د) مروحة سقف تدور في مكانها.', null, null, null, 'تحليل', 'تطبيق شرط', 'متوسط', 'الكتاب ص 33 — نموذج الجسيم النقطي'),
('essay', 3, 'قال طالب: «لا يمكن تمثيل الطائرة بجسيم نقطي أبدًا؛ لأنها جسم ضخم طوله 70 m». قوّم عبارته، مستعينًا بحالتين لحركة الطائرة.', null, null, null, 'تقويم', 'تقويم ادعاء', 'صعب', 'الكتاب ص 54 — إتقان المفاهيم (السؤالان 35 و36)')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
where not exists (select 1 from public.questions x where x.objective_id = (select id from public.objectives where code = 'P1-C2-L1-O08') and x.type = v.type and x.number = v.number);
insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 2, 'لكي نستخدم نموذج الجسيم النقطي يجب أن يكون حجم الجسم صغيرًا جدًا مقارنة بالمسافة التي يتحركها.', '["الشرط يتعلق بالحجم مقارنة بالمسافة، لا بالكتلة.","يمكن تمثيل جسم سرعته متغيرة بالنموذج؛ فالسرعة ليست شرطًا.","","النموذج يُستعمل لتمثيل حركة الأجسام، والشرط هو صغر الحجم مقارنة بالمسافة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (38%)"}],"at":"2026-11-18T12:34:59.202Z"}'::jsonb),
('mcq', 2, 0, 'طول السيارة بضعة أمتار، وهو صغير جدًا مقارنة بـ 400 km فيصح النموذج في الحالة (2)، أما في المرآب فطولها قريب من 6 m فلا يصح.', '["","في الحالة (1) طول السيارة قريب من المسافة التي تتحركها، فلا تُهمل أبعادها.","الشرط مقارنة الحجم بالمسافة، وهي مختلفة كثيرًا بين الحالتين.","الحجم يُقارن بالمسافة؛ والسيارة صغيرة جدًا مقارنة بـ 400 km."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-11-18T12:34:59.203Z"}'::jsonb),
('mcq', 3, 1, 'طول الطائرة عشرات الأمتار، وهو صغير جدًا مقارنة بالمسافة بين الرياض وجدة (مئات الكيلومترات)، فيصح تمثيلها بجسيم نقطي.', '["اللاعب يتحرك مسافات قريبة من طول جسمه وتهم حركة أجزائه، فلا يصح النموذج.","","الباب يتحرك مسافة قريبة من أبعاده، فلا يُهمل حجمه.","المسافة التي تتحركها السيارة قريبة من طولها، فلا يصح النموذج."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (70%)"}],"at":"2026-11-18T12:34:59.203Z"}'::jsonb),
('mcq', 4, 3, 'العجلة تدور في مكانها، وأجزاؤها تتحرك مسافات مقاربة لأبعادها، فحجمها ليس صغيرًا مقارنة بالمسافة التي تتحركها؛ فلا يصلح النموذج.', '["قطر الأرض صغير جدًا مقارنة بطول مدارها حول الشمس، فيصلح النموذج.","طول الحافلة صغير جدًا مقارنة بـ 300 km، فيصلح النموذج.","حجم الطائر صغير جدًا مقارنة بآلاف الكيلومترات، فيصلح النموذج.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (70%)"}],"at":"2026-11-18T12:34:59.203Z"}'::jsonb),
('mcq', 5, 0, 'يُستخدم النموذج عندما يكون حجم الجسم صغيرًا جدًا مقارنة بالمسافة التي يتحركها؛ و60 m تساوي نحو 270 مثلًا من قطر الكرة ($60 \div 0.22 \approx 270$)، أما المسافات الأخرى فلا تزيد على نحو ثلاثة أمثال القطر.', '["","0.3 m قريبة من قطر الكرة (0.22 m)، فلا يُهمل حجمها.","0.5 m تساوي نحو ضعفي قطر الكرة فقط، فحجمها ليس صغيرًا جدًا مقارنة بها.","0.7 m تساوي نحو ثلاثة أمثال قطر الكرة فقط، فحجمها ليس صغيرًا جدًا مقارنة بها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-18T12:34:59.203Z"}'::jsonb),
('mcq', 6, 2, 'الحافلة نفسها، لكن نسبة حجمها إلى المسافة المقطوعة تختلف: صغيرة جدًا في الرحلة فيصح النموذج، ومقاربة في الموقف فلا يصح.', '["شرط النموذج لا يتعلق بالسرعة، بل بالحجم مقارنة بالمسافة.","الكتلة لا علاقة لها بشرط استخدام النموذج.","","طول الزمن ليس هو الشرط؛ بل صغر الحجم مقارنة بالمسافة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-11-18T12:34:59.203Z"}'::jsonb),
('mcq', 7, 1, 'عندما تكون المسافة كبيرة جدًا مقارنة بحجم الجسم تصبح تفاصيله وحركة أجزائه غير مؤثرة في وصف حركته الكلية، فتكفي نقطة لتمثيله.', '["صغر الحجم لا يعني ثبات السرعة.","","النموذج يمثل أجسامًا كبيرة كالعدّاء والطائرة إذا كانت المسافة كبيرة جدًا.","مواقع الجسم الكبير تتغير أيضًا عندما يتحرك."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-11-18T12:34:59.203Z"}'::jsonb),
('essay', 1, null::int, null, null, 'يمكن معاملة الجسم كجسيم نقطي عندما يكون حجمه صغيرًا جدًا مقارنة بالمسافة التي يتحركها. مثال يصح: سيارة تسافر 400 km بين مدينتين؛ لأن طولها صغير جدًا مقارنة بالمسافة. مثال لا يصح: سيارة تدخل مرآبًا طوله 6 m؛ لأن طولها مقارب للمسافة التي تتحركها.', '["الشرط: الحجم صغير جدًا مقارنة بالمسافة","مثال صحيح يصح فيه النموذج","مثال صحيح لا يصح فيه النموذج","تعليل المثالين بالمقارنة"]'::jsonb, '[]'::jsonb, '[{"element":"الشرط","marks":1},{"element":"المثال الأول مع تعليله","marks":1},{"element":"المثال الثاني مع تعليله","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"يذكر الشرط ومثالين صحيحين معللين"},{"level":"2 درجتان","description":"يذكر الشرط ومثالًا واحدًا صحيحًا"},{"level":"1 درجة","description":"يذكر الشرط فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["ربط الشرط بالكتلة أو السرعة","أمثلة دون مقارنة الحجم بالمسافة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (38%)"}],"at":"2026-11-18T12:34:59.204Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) يصلح؛ لأن قطر الأرض صغير جدًا مقارنة بطول مدارها حول الشمس. (ب) لا يصلح؛ لأن اللاعب يتحرك مسافات مقاربة لطول جسمه، وحركة أجزائه مهمة في وصف حركته. (ج) يصلح؛ لأن طول السفينة صغير جدًا مقارنة بعرض البحر الأحمر. (د) لا يصلح؛ لأن المروحة لا تنتقل من مكانها، وأجزاؤها تتحرك مسافات مقاربة لأبعادها.', '["(أ) يصلح مع التعليل","(ب) لا يصلح مع التعليل","(ج) يصلح مع التعليل","(د) لا يصلح مع التعليل"]'::jsonb, '[]'::jsonb, '[{"element":"الحالة (أ)","marks":1},{"element":"الحالة (ب)","marks":1},{"element":"الحالة (ج)","marks":1},{"element":"الحالة (د)","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"يحكم على الحالات الأربع حكمًا صحيحًا معللًا"},{"level":"2–3 درجات","description":"يحكم على حالتين أو ثلاث حكمًا صحيحًا معللًا"},{"level":"1 درجة","description":"حالة واحدة صحيحة"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["الحكم بأن الأرض لا تصلح لأنها جسم ضخم","الحكم دون مقارنة الحجم بالمسافة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-11-18T12:34:59.204Z"}'::jsonb),
('essay', 3, null::int, null, null, 'العبارة غير صحيحة؛ لأن الشرط ليس صغر حجم الجسم في ذاته، بل صغره مقارنة بالمسافة التي يتحركها. فعند دراسة رحلة الطائرة بين مدينتين تفصل بينهما 1000 km يكون طولها (70 m) صغيرًا جدًا مقارنة بالمسافة، فيصح تمثيلها بجسيم نقطي. أما عند دراسة حركتها وهي تقترب ببطء من بوابة المطار مسافة 100 m تقريبًا، فطولها مقارب للمسافة، فلا يصح النموذج.', '["الحكم بخطأ العبارة","الشرط نسبي: الحجم مقارنة بالمسافة","حالة يصح فيها النموذج","حالة لا يصح فيها النموذج"]'::jsonb, '[]'::jsonb, '[{"element":"الحكم","marks":1},{"element":"بيان الشرط","marks":1},{"element":"الحالة الأولى","marks":1},{"element":"الحالة الثانية","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"يحكم ويبين الشرط ويعطي حالتين صحيحتين معللتين"},{"level":"2–3 درجات","description":"يحكم ويبين الشرط مع حالة واحدة"},{"level":"1 درجة","description":"يحكم بخطأ العبارة دون تعليل"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["الموافقة على العبارة","عدّ الحجم وحده معيارًا دون المسافة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-11-18T12:34:59.204Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
join public.questions x on x.objective_id = (select id from public.objectives where code = 'P1-C2-L1-O08') and x.type = v.type and x.number = v.number
on conflict (question_id) do nothing;

insert into public.questions (objective_id, type, number, stem, stimulus, images, options, thinking_level, question_kind, difficulty, source_ref, status, origin)
select (select id from public.objectives where code = 'P1-C2-L2-O01'), v.type, v.number, v.stem, v.stimulus::jsonb, v.images::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'ما الذي يحدده النظام الإحداثي عند وصف حركة جسم؟', null, null, '["موقع نقطة الأصل للمتغير المدروس، والاتجاه الذي تتزايد فيه قيمه","سرعة الجسم واتجاه حركته عند كل لحظة من لحظات الحركة","المسافة الكلية التي يقطعها الجسم من بداية حركته إلى نهايتها","شكل المسار الذي يسلكه الجسم في أثناء حركته"]'::jsonb, 'تذكر', 'تذكر مفهوم', 'سهل', 'الكتاب ص 34 — أنظمة الإحداثيات'),
('mcq', 2, 'عندما تقرّر أين تضع بداية شريط القياس على امتداد مسار عدّاء، ومتى تبدأ تشغيل ساعة الإيقاف، فإنك بذلك تكون قد:', null, null, '["قست إزاحة العدّاء خلال حركته","حسبت الفترة الزمنية لحركة العدّاء","حدّدت النظام الإحداثي لوصف حركة العدّاء","حدّدت المسافة التي سيقطعها العدّاء"]'::jsonb, 'فهم', 'تطبيق مفهوم على موقف', 'سهل', 'الكتاب ص 34 — أنظمة الإحداثيات'),
('mcq', 3, 'يبين الشكل الآتي نظامين إحداثيين وُضعا لوصف الحركة على الطريق نفسه. بمَ يختلف النظام (2) عن النظام (1)؟', null, '[{"src":"qimg/phys1/c2l2-o01-two-systems.svg","alt":"شارع مستقيم عليه من اليسار إلى اليمين: منزل، ثم شجرة، ثم عمود إنارة في الطرف الأيمن. تحته محوران للموقع بوحدة المتر. النظام (1): محور d يتجه سهمه نحو اليمين، تدريجه 0 عند المنزل ثم 5، 10 (عند الشجرة)، 15، 20، 25، 30 عند عمود الإنارة. النظام (2): محور d يتجه سهمه نحو اليسار، تدريجه 0 عند عمود الإنارة ثم 5، 10، 15، 20 (عند الشجرة)، 25، 30 عند المنزل. عنوان المحور: الموقع (m)."}]'::jsonb, '["وحدة قياس الموقع المستخدمة على المحور","موقع نقطة الأصل، واتجاه تزايد قيم الموقع","طول الطريق الذي يمثله المحور","المسافة بين المنزل وعمود الإنارة"]'::jsonb, 'فهم', 'تفسير رسم', 'متوسط', 'الكتاب ص 34 — أنظمة الإحداثيات'),
('mcq', 4, 'في النظام الإحداثي الموضح في الشكل الآتي، أين تقع نقطة الأصل، وفي أيّ اتجاه تتزايد قيم الموقع؟', null, '[{"src":"qimg/phys1/c2l2-o01-axis.svg","alt":"محور موقع أفقي d يتجه سهمه نحو اليسار، تدريجه بالمتر من اليمين إلى اليسار: 0، 5، 10، 15، 20، 25، 30، 35، 40. شجرة مرسومة عند التدريج 0 في الطرف الأيمن، ومنزل مرسوم عند التدريج 25. عنوان المحور: الموقع (m)."}]'::jsonb, '["عند الشجرة، وتتزايد القيم نحو اليمين","عند المنزل، وتتزايد القيم نحو اليسار","عند الطرف الأيسر للمحور، وتتزايد القيم نحو اليمين","عند الشجرة، وتتزايد القيم نحو اليسار"]'::jsonb, 'تطبيق', 'قراءة رسم', 'متوسط', 'الكتاب ص 34 — أنظمة الإحداثيات'),
('mcq', 5, 'تتحرك سيارة على طريق مستقيم. لماذا يكفي في هذه الحالة محور واحد لوصف موقعها؟', null, null, '["لأن سرعة السيارة ثابتة طوال حركتها","لأن نقطة الأصل يجب أن تكون عند موقع السيارة الابتدائي","لأن الحركة على امتداد خط مستقيم يمثل أحد محوري النظام الإحداثي","لأن الزمن لا يحتاج إلى نقطة أصل عند القياس"]'::jsonb, 'فهم', 'تفسير', 'متوسط', 'الكتاب ص 34 — أنظمة الإحداثيات'),
('mcq', 6, 'قال طالب: «لوصف حركة العدّاء يجب أن يزداد تدريج شريط القياس نحو اليمين دائمًا، وأيّ اختيار آخر خاطئ». ما تقييمك لهذه العبارة؟', null, null, '["صحيحة؛ لأن القيم الموجبة للموقع تكون نحو اليمين في كل نظام إحداثي","خاطئة؛ فيمكن أن يزداد التدريج نحو اليمين أو نحو الاتجاه المعاكس، وكلاهما صحيح","صحيحة؛ لأن نقطة الأصل يجب أن تقع عند الطرف الأيسر للمسار","خاطئة؛ لأن التدريج يجب أن يزداد نحو اليسار دائمًا"]'::jsonb, 'تقويم', 'تقويم عبارة', 'صعب', 'الكتاب ص 34 — أنظمة الإحداثيات'),
('mcq', 7, 'يحدد النظام الإحداثي نقطة الأصل لكل متغير ندرسه. عند تسجيل أزمنة حركة عدّاء، ما الذي يمثل نقطة الأصل للزمن؟', null, null, '["لحظة بدء تشغيل ساعة الإيقاف، حين تكون قراءتها صفرًا","لحظة وصول العدّاء إلى خط النهاية","منتصف الزمن الذي استغرقته حركة العدّاء","لحظة توقف العدّاء عن الحركة تمامًا"]'::jsonb, 'فهم', 'تطبيق مفهوم', 'صعب', 'الكتاب ص 34 — أنظمة الإحداثيات'),
('essay', 1, 'وضّح المقصود بالنظام الإحداثي، واذكر الأمرين اللذين يحددهما.', null, null, null, 'فهم', 'شرح مفهوم', 'سهل', 'الكتاب ص 53 — دليل مراجعة الفصل (2-2 الموقع والزمن)'),
('essay', 2, 'تريد تصوير حركة عدّاء على مسار مستقيم لقياس مواقعه والأزمنة التي يصل فيها إلى كل موقع. صف كيف تحدد نظامًا إحداثيًّا مناسبًا لهذه التجربة.', null, null, null, 'تطبيق', 'تصميم إجراء', 'متوسط', 'الكتاب ص 34 — أنظمة الإحداثيات'),
('essay', 3, 'يبين الشكل الآتي نظامين إحداثيين وُضعا لوصف الحركة على الطريق نفسه. (أ) حدد نقطة الأصل واتجاه تزايد قيم الموقع في كل نظام. (ب) ما موقع الشجرة في كل من النظامين؟ (ج) هل كلا النظامين صالح لوصف حركة جسم على هذا الطريق؟ فسّر.', null, '[{"src":"qimg/phys1/c2l2-o01-two-systems.svg","alt":"شارع مستقيم عليه من اليسار إلى اليمين: منزل، ثم شجرة، ثم عمود إنارة في الطرف الأيمن. تحته محوران للموقع بوحدة المتر. النظام (1): محور d يتجه سهمه نحو اليمين، تدريجه 0 عند المنزل ثم 5، 10 (عند الشجرة)، 15، 20، 25، 30 عند عمود الإنارة. النظام (2): محور d يتجه سهمه نحو اليسار، تدريجه 0 عند عمود الإنارة ثم 5، 10، 15، 20 (عند الشجرة)، 25، 30 عند المنزل. عنوان المحور: الموقع (m)."}]'::jsonb, null, 'تحليل', 'تحليل رسم', 'صعب', 'الكتاب ص 34 — أنظمة الإحداثيات')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
where not exists (select 1 from public.questions x where x.objective_id = (select id from public.objectives where code = 'P1-C2-L2-O01') and x.type = v.type and x.number = v.number);
