select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 0, 'النظام الإحداثي يعيّن موقع نقطة الأصل (نقطة الإسناد) بالنسبة إلى المتغير المدروس، والاتجاه الذي تتزايد فيه قيم هذا المتغير.', '["","السرعة صفة لحركة الجسم نفسه، والنظام الإحداثي إطار نختاره نحن لقياس الموقع والزمن ولا يحدد السرعة.","المسافة تُقاس بعد الحركة، ولا يحددها اختيار النظام الإحداثي.","المسار تحدده حركة الجسم نفسه، أما النظام الإحداثي فيحدد نقطة الأصل واتجاه تزايد القيم فقط."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (26%)"}],"at":"2026-11-18T12:34:59.204Z"}'::jsonb),
('mcq', 2, 2, 'بذلك تكون قد حدّدت النظام الإحداثي لوصف حركة العدّاء؛ فاختيار مكان بداية شريط القياس (نقطة الأصل للموقع) ولحظة تشغيل ساعة الإيقاف (نقطة الأصل للزمن) واتجاه تزايد التدريج هو تحديد للنظام الإحداثي.', '["وضع الشريط وتشغيل الساعة يسبقان القياس؛ والإزاحة تُحسب لاحقًا من موقعين للعدّاء.","الفترة الزمنية فرق بين قراءتين للساعة، ولم تُؤخذ أي قراءة بعد.","","مكان بداية الشريط لا يحدد المسافة التي سيقطعها العدّاء."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (5%)"}],"at":"2026-11-18T12:34:59.205Z"}'::jsonb),
('mcq', 3, 1, 'نقطة الأصل في النظام (1) عند المنزل والقيم تتزايد نحو اليمين، وفي النظام (2) عند عمود الإنارة والقيم تتزايد نحو اليسار؛ وهذان هما ما يحدده النظام الإحداثي.', '["المحوران كلاهما مدرّج بالمتر (m)؛ فالوحدة لم تتغير.","","كلا المحورين يمتد من 0 إلى 30 m على الطريق نفسه؛ فالطول واحد.","المسافة بين المعلمين ثابتة (30 m) في النظامين؛ لأن الطريق لم يتغير."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (31%)"}],"at":"2026-11-18T12:34:59.205Z"}'::jsonb),
('mcq', 4, 3, 'تدريج الصفر عند الشجرة فهي نقطة الأصل، والأرقام تكبر وسهم المحور يشير نحو اليسار؛ فالاتجاه الموجب نحو اليسار.', '["سهم المحور والأرقام 5، 10، 15… تتزايد نحو اليسار لا اليمين.","المنزل عند التدريج 25، أما نقطة الأصل فهي حيث القيمة صفر عند الشجرة.","الطرف الأيسر يقابل 40 m لا الصفر؛ فلا نقطة الأصل هناك، ولا القيم تتزايد يمينًا.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-11-18T12:34:59.205Z"}'::jsonb),
('mcq', 5, 2, 'عندما تكون الحركة في خط مستقيم يوضع شريط القياس على امتداد هذا الخط، فيمثل أحد محوري النظام الإحداثي، ويكفي لتحديد الموقع.', '["عدد المحاور يحدده شكل المسار لا ثبات السرعة؛ فالحركة المستقيمة المتسارعة يكفيها محور واحد أيضًا.","نقطة الأصل يمكن اختيارها في أي مكان، ولا علاقة لذلك بعدد المحاور.","","الزمن أيضًا له نقطة أصل (لحظة تشغيل الساعة)، ولا يفسّر هذا كفاية محور واحد للموقع."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (4%)"}],"at":"2026-11-18T12:34:59.205Z"}'::jsonb),
('mcq', 6, 1, 'من المحتمل أن يُوضع شريط القياس بحيث يزداد تدريجه عن يمين الصفر، كما أن وضعه في الاتجاه المعاكس صحيح أيضًا؛ فاتجاه التزايد نختاره نحن.', '["اتجاه تزايد القيم جزء من اختيارنا للنظام الإحداثي، وليس قاعدة ثابتة.","","نقطة الأصل يمكن وضعها في أي مكان مناسب، لا في الطرف الأيسر بالضرورة.","هذا يستبدل قاعدة خاطئة بأخرى خاطئة؛ فلا يُفرض اتجاه واحد للتزايد."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (5%)"}],"at":"2026-11-18T12:34:59.205Z"}'::jsonb),
('mcq', 7, 0, 'نقطة الأصل هي حيث تكون قيمة المتغير صفرًا؛ وللزمن تكون عند اللحظة التي تُشغَّل فيها ساعة الإيقاف من الصفر.', '["","هذه لحظة تقع في آخر الحركة، وقراءة الساعة عندها ليست صفرًا.","منتصف الحركة لا تكون عنده قراءة الساعة صفرًا، فلا يمثل نقطة الأصل للزمن.","التوقف قد يحدث في أي لحظة، ولا علاقة له بصفر الزمن."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (26%)"}],"at":"2026-11-18T12:34:59.205Z"}'::jsonb),
('essay', 1, null::int, null, null, 'النظام الإحداثي نظام يُستخدم لوصف الحركة، يحدد: (1) موقع نقطة الأصل (نقطة الإسناد) بالنسبة إلى المتغير المدروس، وهي النقطة التي تكون عندها قيمة المتغير صفرًا. (2) الاتجاه الذي تتزايد فيه قيم هذا المتغير.', '["النظام الإحداثي نظام لوصف الحركة","يحدد موقع نقطة الأصل للمتغير المدروس","يحدد الاتجاه الذي تتزايد فيه قيم المتغير"]'::jsonb, '[]'::jsonb, '[{"element":"التعريف","marks":1},{"element":"نقطة الأصل","marks":1},{"element":"اتجاه التزايد","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"إجابة كاملة صحيحة تشمل جميع العناصر المطلوبة."},{"level":"درجة جزئية","description":"يذكر بعض العناصر صحيحة أو يخطئ في أحدها."},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة."}]'::jsonb, '["الاكتفاء بذكر نقطة الأصل وإهمال اتجاه تزايد القيم.","الخلط بين النظام الإحداثي ومسار حركة الجسم."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (7%)"}],"at":"2026-11-18T12:34:59.205Z"}'::jsonb),
('essay', 2, null::int, null, null, 'أضع شريط القياس على امتداد الخط المستقيم الذي يجري عليه العدّاء، فيمثل محور الموقع. أختار مكان النهاية الصفرية للشريط (مثل نقطة على بعد 6 m يسار شجرة)، فتكون هي نقطة الأصل للموقع. أحدد اتجاه تزايد التدريج (نحو اليمين مثلًا) فيكون هو الاتجاه الموجب. أختار لحظة تشغيل ساعة الإيقاف من الصفر لتكون نقطة الأصل للزمن.', '["وضع الشريط على امتداد خط الحركة المستقيم","اختيار نقطة الأصل للموقع (صفر الشريط)","تحديد اتجاه تزايد قيم الموقع","اختيار نقطة الأصل للزمن (لحظة تشغيل الساعة)"]'::jsonb, '[]'::jsonb, '[{"element":"محور على امتداد الحركة","marks":1},{"element":"نقطة الأصل للموقع","marks":1},{"element":"اتجاه التزايد","marks":1},{"element":"نقطة الأصل للزمن","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة تشمل جميع العناصر المطلوبة."},{"level":"درجة جزئية","description":"يذكر بعض العناصر صحيحة أو يخطئ في أحدها."},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة."}]'::jsonb, '["إهمال تحديد نقطة الأصل للزمن.","وضع الشريط بشكل لا يوازي مسار العدّاء.","الظن أن نقطة الأصل يجب أن تكون عند موقع بداية العدّاء."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (6%)"}],"at":"2026-11-18T12:34:59.206Z"}'::jsonb),
('essay', 3, null::int, null, null, '(أ) النظام (1): نقطة الأصل عند المنزل، والقيم تتزايد نحو اليمين. النظام (2): نقطة الأصل عند عمود الإنارة، والقيم تتزايد نحو اليسار. (ب) الشجرة عند 10 m في النظام (1)، وعند 20 m في النظام (2). (ج) نعم، كلاهما صالح؛ لأن اختيار مكان نقطة الأصل واتجاه التزايد أمر نختاره نحن، والمهم أن نلتزم بالنظام المختار طوال وصف الحركة.', '["نقطة الأصل واتجاه التزايد في النظام (1)","نقطة الأصل واتجاه التزايد في النظام (2)","موقع الشجرة 10 m و20 m","كلا النظامين صالح مع التعليل"]'::jsonb, '[]'::jsonb, '[{"element":"النظام (1)","marks":1},{"element":"النظام (2)","marks":1},{"element":"موقعا الشجرة","marks":1},{"element":"صلاحية النظامين مع التعليل","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة تشمل جميع العناصر المطلوبة."},{"level":"درجة جزئية","description":"يذكر بعض العناصر صحيحة أو يخطئ في أحدها."},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة."}]'::jsonb, '["قراءة موقع الشجرة في النظام (2) من اليسار كما في النظام (1).","الاعتقاد بأن نظامًا واحدًا فقط هو الصحيح."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (31%)"}],"at":"2026-11-18T12:34:59.206Z"}'::jsonb)
