('mcq', 4, 'بدأ عدّاء حركته من نقطة الأصل لحظة تشغيل ساعة الإيقاف. ماذا تكون قيمتا موقعه وزمنه في تلك اللحظة؟', null, null, '["الموقع صفر، والزمن يساوي زمن الرحلة كلها","الموقع يساوي طول المسار، والزمن صفر","الموقع صفر، والزمن صفر","لا يمكن معرفتهما دون معرفة سرعة العدّاء"]'::jsonb, 'فهم', 'تطبيق تعريف', 'متوسط', 'الكتاب ص 34 — أنظمة الإحداثيات'),
('mcq', 5, 'يقيس طالب مواقع سيارة لعبة بمسطرة مترية مثبتة بموازاة مسارها. أيّ نقطة على المسطرة تمثل نقطة الأصل؟', null, null, '["النقطة التي تتوقف عندها السيارة","النقطة المقابلة لمنتصف المسطرة","النقطة المقابلة لأكبر تدريج في المسطرة","النقطة المقابلة لتدريج الصفر في المسطرة"]'::jsonb, 'تطبيق', 'تطبيق تعريف', 'متوسط', 'الكتاب ص 50–51 — مختبر الفيزياء: عمل رسوم توضيحية للحركة'),
('mcq', 6, 'يُقال إن اختيار مكان نقطة الأصل أمر اختياري. أيّ العبارات الآتية تصف ذلك وصفًا صحيحًا؟', null, null, '["يمكن وضع نقطة الأصل في أي مكان مناسب، على أن تكون قيمة الموقع عندها صفرًا","يجب أن تكون نقطة الأصل دائمًا عند موقع بداية حركة الجسم","يجب أن تكون نقطة الأصل دائمًا عند الطرف الأيسر لمسار الحركة","نقطة الأصل هي دائمًا أول نقطة تظهر في المخطط التوضيحي للحركة"]'::jsonb, 'فهم', 'تمييز عبارة صحيحة', 'صعب', 'الكتاب ص 34 — أنظمة الإحداثيات'),
('mcq', 7, 'على محور موقع اتجاهه الموجب نحو الشرق، موقع البئر $+15\ \text{m}$ وموقع الخيمة $-5\ \text{m}$. أين تقع نقطة الأصل لهذا المحور؟', null, null, '["عند الخيمة نفسها","على بعد 5 m شرق الخيمة","في منتصف المسافة بين الخيمة والبئر","على بعد 5 m غرب الخيمة"]'::jsonb, 'فهم', 'استنتاج من قيم الموقع', 'صعب', 'الكتاب ص 34–35 — نقطة الأصل والموقع السالب'),
('essay', 1, 'عرّف نقطة الأصل في النظام الإحداثي، واذكر الاسم الآخر الذي تُعرف به.', null, null, null, 'تذكر', 'تذكر تعريف', 'سهل', 'الكتاب ص 53 — دليل مراجعة الفصل (2-2 الموقع والزمن)'),
