('mcq', 1, 1, 'نقطة الأصل هي النقطة التي تكون عندها قيمة كل من المتغيرين (الموقع – الزمن) صفرًا.', '["نقطة توقف الجسم قد تكون في أي موقع، ولا تكون قيمة الموقع والزمن عندها صفرًا بالضرورة.","","نقطة الأصل تتعلق بقيم الموقع والزمن، ولا علاقة لها بسرعة الجسم.","نقطة الأصل ليست منتصف المسار بالضرورة؛ بل هي حيث قيمة المتغيرين صفر."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-11-18T12:34:59.207Z"}'::jsonb),
('mcq', 2, 3, 'يحدد النظام الإحداثي موقع نقطة الأصل، وتُسمّى أيضًا نقطة الإسناد؛ إذ تُنسب إليها مواقع الأجسام.', '["نقطة الاتزان مصطلح لا يدل على نقطة الصفر في النظام الإحداثي.","نقطة النهاية آخر موقع للجسم، وليست نقطة الأصل.","نقطة المنتصف تقع في وسط المسار، وليست اسمًا لنقطة الأصل.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-11-18T12:34:59.207Z"}'::jsonb),
('mcq', 3, 0, 'نقطة الأصل هي حيث تكون قيمة الموقع صفرًا، والتدريج 0 يقع عند المسجد.', '["","المنزل في الطرف الأيسر عند $-20\\ \\text{m}$؛ ونقطة الأصل ليست بالضرورة أول نقطة على المحور.","البقالة عند 30 m، فهي تبعد 30 m عن نقطة الأصل.","المدرسة عند 60 m، وهي أبعد الأماكن عن نقطة الأصل في الاتجاه الموجب."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-11-18T12:34:59.207Z"}'::jsonb),
('mcq', 4, 2, 'عند نقطة الأصل تكون قيمة كل من الموقع والزمن صفرًا، والعدّاء بدأ منها لحظة تشغيل الساعة.', '["الساعة شُغّلت في تلك اللحظة نفسها، فقراءتها صفر لا زمن الرحلة.","العدّاء عند نقطة الأصل، فموقعه صفر لا طول المسار.","","القيمتان معروفتان من تعريف نقطة الأصل، ولا تحتاجان إلى السرعة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-11-18T12:34:59.207Z"}'::jsonb),
('mcq', 5, 3, 'نقطة الأصل للموقع هي النقطة التي تكون عندها قيمته صفرًا، أي النهاية الصفرية لأداة القياس.', '["مكان توقف السيارة يُقرأ موقعه على المسطرة، وليس هو نقطة الأصل.","منتصف المسطرة يقابل قيمة غير صفرية، فلا يمثل نقطة الأصل.","أكبر تدريج يمثل أبعد موقع عن الصفر، لا نقطة الأصل.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-11-18T12:34:59.207Z"}'::jsonb),
('mcq', 6, 0, 'نقطة الأصل نختارها بحسب ما يناسب المسألة (مثل وضعها على بعد 6 m أو 4 m يسار شجرة)، وتكون قيمة الموقع عندها صفرًا دائمًا.', '["","يمكن أن تكون نقطة الأصل بعيدة عن بداية الحركة، كأن توضع على بعد أمتار يسار شجرة.","لا يُشترط موضع معيّن؛ فقد تقع نقطة الأصل في وسط المسار أو طرفه الأيمن.","أول نقطة في المخطط هي موقع الجسم الأول، وقد لا تكون قيمة الموقع عندها صفرًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-11-18T12:34:59.207Z"}'::jsonb),
('mcq', 7, 1, 'نقطة الأصل هي النقطة التي تكون عندها قيمة الموقع صفرًا. الموقع $-5\ \text{m}$ يعني أن الخيمة تبعد 5 m عن نقطة الأصل في الاتجاه السالب؛ فنقطة الأصل تقع شرق الخيمة بمقدار 5 m، أي بين الخيمة والبئر، وتبعد 15 m عن البئر.', '["موقع الخيمة $-5\\ \\text{m}$ لا صفر؛ فهي ليست نقطة الأصل.","","المنتصف يبعد 10 m عن كل منهما، فيكون موقع الخيمة عندئذ $-10\\ \\text{m}$ لا $-5\\ \\text{m}$.","الإشارة السالبة تعني أن الخيمة غرب نقطة الأصل، فنقطة الأصل شرقها لا غربها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-18T12:34:59.207Z"}'::jsonb),
('essay', 1, null::int, null, null, 'نقطة الأصل هي النقطة التي تكون عندها قيمة كل من المتغيرين (الموقع والزمن) صفرًا، وتُسمّى أيضًا نقطة الإسناد.', '["النقطة التي تكون عندها قيمة الموقع صفرًا","وقيمة الزمن صفرًا","تُسمّى نقطة الإسناد"]'::jsonb, '[]'::jsonb, '[{"element":"قيمة الموقع صفر","marks":1},{"element":"قيمة الزمن صفر","marks":1},{"element":"الاسم الآخر","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"إجابة كاملة صحيحة تشمل جميع العناصر المطلوبة."},{"level":"درجة جزئية","description":"يذكر بعض العناصر صحيحة أو يخطئ في أحدها."},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة."}]'::jsonb, '["تعريفها بأنها نقطة بداية حركة الجسم دائمًا.","إغفال أن الزمن أيضًا يكون صفرًا عندها."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-11-18T12:34:59.207Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) نقطة الأصل عند المسجد؛ لأن تدريج الموقع عنده يساوي صفرًا. (ب) البقالة عند 30 m فتبعد 30 m عن نقطة الأصل، والمدرسة عند 60 m فتبعد 60 m عنها.', '["نقطة الأصل عند المسجد","التعليل: قيمة الموقع عندها صفر","بعد البقالة 30 m","بعد المدرسة 60 m"]'::jsonb, '[]'::jsonb, '[{"element":"تحديد نقطة الأصل","marks":1},{"element":"التعليل","marks":1},{"element":"بعد البقالة","marks":1},{"element":"بعد المدرسة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة تشمل جميع العناصر المطلوبة."},{"level":"درجة جزئية","description":"يذكر بعض العناصر صحيحة أو يخطئ في أحدها."},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة."}]'::jsonb, '["اعتبار الطرف الأيسر للمحور (المنزل) نقطة الأصل.","قياس البعد من المنزل بدل نقطة الأصل."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-11-18T12:34:59.207Z"}'::jsonb),
('essay', 3, null::int, null, null, '(أ) أجعل خط البداية مقابلًا لتدريج الصفر في المسطرة، فيكون هو نقطة الأصل للموقع. (ب) نقطة الأصل للزمن هي لحظة إطلاق السيارة، حيث يبدأ عدّ الزمن من الصفر. (ج) السطر الأول: الزمن 0.0 s والموقع 0 cm؛ لأن السيارة عند نقطة الأصل في لحظة بدء العدّ.', '["نقطة الأصل للموقع عند خط البداية (صفر المسطرة)","نقطة الأصل للزمن لحظة الإطلاق","السطر الأول: الزمن 0.0 s","والموقع صفر"]'::jsonb, '[]'::jsonb, '[{"element":"نقطة الأصل للموقع","marks":1},{"element":"نقطة الأصل للزمن","marks":1},{"element":"قيمة الزمن في السطر الأول","marks":0.5},{"element":"قيمة الموقع في السطر الأول","marks":0.5}]'::jsonb, '[{"level":"3 درجات","description":"إجابة كاملة صحيحة تشمل جميع العناصر المطلوبة."},{"level":"درجة جزئية","description":"يذكر بعض العناصر صحيحة أو يخطئ في أحدها."},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة."}]'::jsonb, '["تسجيل الزمن الأول 0.1 s بدل 0.0 s.","اختيار نقطة أصل للموقع لا تقابل صفر المسطرة."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-11-18T12:34:59.208Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
