('mcq', 3, 'ما موقع الكرة في النظام الإحداثي الموضح في الشكل الآتي؟', null, '[{"src":"qimg/phys1/c2l2-o03-negative.svg","alt":"محور موقع أفقي d سهمه نحو اليمين، تدريجه بالمتر من اليسار إلى اليمين: −15، −10، −5، 0، 5، 10، 15، 20، 25، 30. شجرة مرسومة عند التدريج 5، وكرة حمراء (نقطة) عند التدريج −10. عنوان المحور: الموقع (m)."}]'::jsonb, '["$10\\ \\text{m}$","$-15\\ \\text{m}$","$15\\ \\text{m}$","$-10\\ \\text{m}$"]'::jsonb, 'تطبيق', 'قراءة رسم', 'سهل', 'الكتاب ص 35 — الموقع السالب'),
('mcq', 4, 'ما الذي يدل عليه طول السهم الذي يمثل موقع جسم على المخطط التوضيحي للحركة؟', null, null, '["المسافة الكلية التي قطعها الجسم منذ بدء حركته","بُعد الجسم عن نقطة الأصل","الزمن الذي استغرقه الجسم للوصول إلى موقعه","سرعة الجسم عند تلك اللحظة"]'::jsonb, 'فهم', 'تفسير', 'متوسط', 'الكتاب ص 34 — أنظمة الإحداثيات'),
('mcq', 5, 'على محور موقع اتجاهه الموجب نحو اليمين، تقع شجرة عند الموقع $+6\ \text{m}$، ويقع مقعد على بعد 10 m يسار الشجرة. ما موقع المقعد؟', null, null, '["$-4\\ \\text{m}$","$-10\\ \\text{m}$","$+16\\ \\text{m}$","$+4\\ \\text{m}$"]'::jsonb, 'تطبيق', 'حساب موقع', 'صعب', 'الكتاب ص 35 — الموقع السالب'),
('mcq', 6, 'يقع الجسم A عند الموقع $-7\ \text{m}$، والجسم B عند الموقع $-2\ \text{m}$ على محور اتجاهه الموجب نحو اليمين. أيّ العبارات الآتية تصف متجهي موقعيهما وصفًا صحيحًا؟', null, null, '["المتجهان متعاكسان في الاتجاه، ومتجه A أطول","المتجهان كلاهما في الاتجاه السالب، ومتجه B أطول","المتجهان كلاهما في الاتجاه السالب، ولهما الطول نفسه","المتجهان كلاهما في الاتجاه السالب، ومتجه A أطول"]'::jsonb, 'تحليل', 'تحليل متجهي موقع', 'صعب', 'الكتاب ص 34–36 — متجه الموقع والموقع السالب'),
('mcq', 7, 'ماذا تعني الإشارة السالبة في الموقع $-20\ \text{m}$ لجسم على محور اتجاهه الموجب نحو الشرق؟', null, null, '["أن الجسم يتحرك نحو الغرب","أن بعد الجسم عن نقطة الأصل أقل من الصفر","أن الجسم يقع على بعد 20 m غرب نقطة الأصل","أن الجسم قطع مسافة 20 m في الاتجاه السالب"]'::jsonb, 'فهم', 'تفسير إشارة', 'متوسط', 'الكتاب ص 35 — الموقع السالب'),
