from (values
('mcq', 1, 2, 'الموقع في الفيزياء متجه ذيله عند نقطة الأصل لنظام الإحداثيات المستخدم، ورأسه عند المكان المراد تحديد موقعه.', '["هذا عكس الاتجاه الصحيح؛ فسهم الموقع يتجه دائمًا من نقطة الأصل إلى الجسم.","الموقع له اتجاه، وقد يكون موجبًا أو سالبًا بحسب جهة الجسم من نقطة الأصل.","","هذا تمثيل الإزاحة لا الموقع."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-11-18T12:34:59.208Z"}'::jsonb),
('mcq', 2, 0, 'متجه الموقع يبدأ من نقطة الأصل (0) وينتهي برأسه عند العدّاء (20 m)، وهذا هو السهم (3).', '["","السهم (1) يبدأ عند العدّاء وينتهي عند نقطة الأصل؛ أي أن اتجاهه معكوس.","السهم (2) يبدأ من 10 m لا من نقطة الأصل.","السهم (4) يبدأ من نقطة الأصل لكنه ينتهي عند 30 m لا عند العدّاء."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-11-18T12:34:59.208Z"}'::jsonb),
('mcq', 3, 3, 'الكرة عند التدريج $-10$، أي على بعد 10 m يسار نقطة الأصل في عكس الاتجاه الموجب؛ فموقعها سالب.', '["الكرة يسار نقطة الأصل والاتجاه الموجب نحو اليمين، فموقعها سالب.","هذا بعد الكرة عن الشجرة؛ والموقع يُقاس من نقطة الأصل لا من الشجرة.","هذا بعد الكرة عن الشجرة مع إهمال الإشارة؛ والموقع يُقاس من نقطة الأصل.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-11-18T12:34:59.208Z"}'::jsonb),
('mcq', 4, 1, 'يدل طول سهم الموقع على بُعد الجسم عن نقطة الأصل، ويتجه السهم دومًا من نقطة الأصل إلى موقع الجسم.', '["قد يقطع الجسم مسافة طويلة ثم يعود قرب نقطة الأصل؛ فطول سهم الموقع لا يمثل المسافة المقطوعة.","","السهم مرسوم على محور الموقع، ولا يمثل طوله زمنًا.","سهم الموقع يحدد مكان الجسم فقط، ولا يعبّر عن سرعته."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-11-18T12:34:59.208Z"}'::jsonb),
('mcq', 5, 0, 'المقعد يسار الشجرة بمقدار 10 m، أي في الاتجاه السالب: $6\ \text{m} - 10\ \text{m} = -4\ \text{m}$؛ فهو يقع 4 m يسار نقطة الأصل، وموقعه سالب.', '["","هذا بعد المقعد عن الشجرة؛ أما الموقع فيُقاس من نقطة الأصل لا من الشجرة.","أُضيف البعد 10 m كأن المقعد يمين الشجرة، مع أنه يسارها في الاتجاه السالب.","الحساب صحيح المقدار لكن المقعد يقع يسار نقطة الأصل، فإشارة موقعه سالبة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-11-18T12:34:59.208Z"}'::jsonb),
('mcq', 6, 3, 'متجه الموقع يبدأ من نقطة الأصل وينتهي عند الجسم. الجسمان كلاهما يسار نقطة الأصل، فيشير المتجهان نحو اليسار (الاتجاه السالب). وطول المتجه يدل على البعد عن نقطة الأصل: A يبعد 7 m وB يبعد 2 m؛ فمتجه A أطول.', '["الموقعان سالبان، فالجسمان في جهة واحدة من نقطة الأصل، والمتجهان في الاتجاه نفسه.","العدد $-2$ أكبر من $-7$، لكن طول المتجه يمثل البعد عن نقطة الأصل: 2 m لـ B و7 m لـ A.","اتحاد الإشارة لا يعني تساوي الطول؛ فالبعدان عن نقطة الأصل مختلفان (7 m و2 m).",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-11-18T12:34:59.208Z"}'::jsonb),
('mcq', 7, 2, 'مقدار الموقع (20 m) هو بعد الجسم عن نقطة الأصل، والإشارة السالبة تعني أنه في عكس الاتجاه الموجب، أي غرب نقطة الأصل.', '["الموقع يحدد مكان الجسم فقط، ولا يدل على اتجاه حركته.","البعد لا يكون أقل من الصفر؛ فالإشارة تدل على الجهة لا على البعد.","","الموقع لا يخبرنا بالمسافة المقطوعة؛ فقد يكون الجسم وُضع هناك دون أن يتحرك."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-11-18T12:34:59.209Z"}'::jsonb),
('essay', 1, null::int, null, null, 'الموقع متجه ذيله عند نقطة الأصل لنظام الإحداثيات المستخدم، ورأسه عند المكان المراد تحديد موقعه، ويُرمز له $\boldsymbol{d}$. يُمثَّل على المخطط بسهم يُرسم من نقطة الأصل إلى النقطة التي تمثل الجسم؛ يدل طوله على بعد الجسم عن نقطة الأصل، ويدل اتجاهه على جهة الجسم منها، فيكون الموقع موجبًا أو سالبًا.', '["الموقع متجه","ذيله عند نقطة الأصل ورأسه عند الجسم","طول السهم يدل على البعد عن نقطة الأصل","يمكن أن يكون موجبًا أو سالبًا"]'::jsonb, '[]'::jsonb, '[{"element":"الموقع متجه","marks":1},{"element":"ذيل السهم ورأسه","marks":1},{"element":"دلالة الطول","marks":1},{"element":"الإشارة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة تشمل جميع العناصر المطلوبة."},{"level":"درجة جزئية","description":"يذكر بعض العناصر صحيحة أو يخطئ في أحدها."},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة."}]'::jsonb, '["رسم سهم الموقع من الجسم إلى نقطة الأصل.","الخلط بين الموقع والإزاحة."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-11-18T12:34:59.209Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) موقع A يساوي 15 m، وموقع B يساوي $-10\ \text{m}$. (ب) متجه موقع A: ذيله عند عمود الإنارة (0)، ورأسه عند A، طوله يمثل 15 m، ويتجه نحو اليمين (الاتجاه الموجب). متجه موقع B: ذيله عند 0، ورأسه عند B، طوله يمثل 10 m، ويتجه نحو اليسار (الاتجاه السالب). (ج) A أبعد عن نقطة الأصل؛ لأن 15 m أكبر من 10 m، فالإشارة السالبة لـ B تدل على الجهة لا على البعد.', '["موقع A: 15 m، وموقع B: $-10\\ \\text{m}$","وصف متجه موقع A","وصف متجه موقع B","A أبعد مع التعليل"]'::jsonb, '[]'::jsonb, '[{"element":"الموقعان","marks":1},{"element":"متجه A","marks":1},{"element":"متجه B","marks":1},{"element":"المقارنة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة تشمل جميع العناصر المطلوبة."},{"level":"درجة جزئية","description":"يذكر بعض العناصر صحيحة أو يخطئ في أحدها."},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة."}]'::jsonb, '["كتابة موقع B موجبًا.","الاعتقاد بأن B أقرب لأن موقعه عدد سالب أصغر."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-18T12:34:59.209Z"}'::jsonb),
('essay', 3, null::int, null, null, 'نعم، يمكن أن يكون الموقع سالبًا؛ إذا وقع الجسم في الجهة المعاكسة للاتجاه الموجب بالنسبة إلى نقطة الأصل (مثل نقطة تقع 5 m يسار نقطة الأصل والاتجاه الموجب نحو اليمين). يتفق الموقعان في المقدار؛ فكلا الجسمين يبعد 5 m عن نقطة الأصل، ويختلفان في الاتجاه؛ فالأول في الاتجاه الموجب والثاني في الاتجاه السالب، أي أن متجهي موقعيهما متعاكسان.', '["نعم يمكن أن يكون سالبًا","التعليل: الجسم في عكس الاتجاه الموجب من نقطة الأصل","يتفقان في المقدار (5 m)","يختلفان في الاتجاه"]'::jsonb, '[]'::jsonb, '[{"element":"الحكم","marks":1},{"element":"التعليل","marks":1},{"element":"الاتفاق في المقدار","marks":1},{"element":"الاختلاف في الاتجاه","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة تشمل جميع العناصر المطلوبة."},{"level":"درجة جزئية","description":"يذكر بعض العناصر صحيحة أو يخطئ في أحدها."},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة."}]'::jsonb, '["الظن أن الإشارة السالبة تعني بعدًا أصغر.","ربط الإشارة السالبة باتجاه الحركة بدل جهة الجسم."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-11-18T12:34:59.209Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
