from (values
('mcq', 1, 'ما المقصود بالكمية الفيزيائية المتجهة؟', null, null, '["كمية يكفي لتعيينها تحديد مقدارها فقط دون اتجاهها","كمية تكون قيمتها موجبة دائمًا مهما كان موقع نقطة الإسناد","كمية تتغير قيمتها مع مرور الزمن في أثناء حركة الجسم","كمية يتطلب تعيينها تحديد مقدارها واتجاهها وفقًا لنقطة الإسناد"]'::jsonb, 'تذكر', 'تذكر تعريف', 'سهل', 'الكتاب ص 35 — الكميات الفيزيائية المتجهة والقياسية (العددية)'),
('mcq', 2, 'كمية فيزيائية يكفي لتعيينها ذكر مقدارها فقط. ماذا تُسمّى؟', null, null, '["كمية متجهة","كمية قياسية (عددية)","متجه الموقع","متجه المحصلة"]'::jsonb, 'تذكر', 'تذكر مصطلح', 'سهل', 'الكتاب ص 35 — الكميات الفيزيائية المتجهة والقياسية (العددية)'),
('mcq', 3, 'قيل لك: «تحرّك قارب 300 m من الرصيف». لماذا لا تكفي هذه المعلومة لتحديد مكان القارب الجديد؟', null, null, '["لأنها تحدد المقدار فقط دون الاتجاه، وتحديد المكان يتطلب المقدار والاتجاه معًا","لأن المسافة لا تُقاس بوحدة المتر، فالقيمة 300 m لا معنى لها","لأنها لم تحدد الزمن الذي استغرقته حركة القارب من الرصيف","لأن المقدار 300 m أكبر من أن يُمثَّل بسهم على الرسم بأي مقياس"]'::jsonb, 'فهم', 'تفسير', 'متوسط', 'الكتاب ص 35 — الكميات الفيزيائية المتجهة والقياسية (العددية)'),
('mcq', 4, 'تُجمع الكميات القياسية جمعًا حسابيًا، مثل: $0.2 + 0.6 = 0.8$. متى يساوي مقدار مجموع إزاحتين مجموع مقداريهما الحسابي؟', null, null, '["عندما تكون الإزاحتان في اتجاهين متعاكسين","دائمًا، مهما كان اتجاها الإزاحتين","عندما تكون الإزاحتان في الاتجاه نفسه","لا يحدث ذلك أبدًا لأن الإزاحة كمية متجهة"]'::jsonb, 'فهم', 'تفسير', 'متوسط', 'الكتاب ص 35 — الكميات الفيزيائية المتجهة والقياسية (العددية)'),
('mcq', 5, 'دُفعت عربة بقوة مقدارها 20 N نحو الشمال. ما الذي يجعل القوة كمية متجهة؟', null, null, '["أن مقدارها 20 N عدد كبير نسبيًا","أن وصفها الكامل يتطلب تحديد مقدارها واتجاهها معًا","أن وحدة قياس مقدارها هي النيوتن (N)","أنها هي التي تسبب حركة العربة"]'::jsonb, 'فهم', 'تعليل تصنيف', 'سهل', 'الكتاب ص 35 — الكميات الفيزيائية المتجهة والقياسية (العددية)'),
('mcq', 6, 'قطع طالبان المسافة نفسها 200 m بعد انطلاقهما من النقطة نفسها، لكنهما وصلا إلى مكانين مختلفين. ما التفسير الصحيح؟', null, null, '["قطع أحدهما في الحقيقة مسافة أكبر من التي قطعها الآخر","استغرق أحدهما زمنًا أطول من الآخر في قطع المسافة","المسافة كمية متجهة تختلف قيمتها باختلاف الطالب الذي يقطعها","تحركا في اتجاهين مختلفين؛ فتحديد المكان يحتاج إلى كمية لها مقدار واتجاه"]'::jsonb, 'تحليل', 'تحليل موقف', 'صعب', 'الكتاب ص 35 — الكميات الفيزيائية المتجهة والقياسية (العددية)'),
('mcq', 7, 'تشير ساعة إلى أن الزمن المنقضي 15 min، ويشير ميزان حرارة إلى $30\ ^\circ\text{C}$. لماذا لا نحتاج إلى ذكر اتجاه لأيّ منهما؟', null, null, '["لأنهما كميتان قياسيتان يكفي لتعيينهما المقدار فقط","لأن قيمتيهما موجبتان، والكمية الموجبة لا تحتاج إلى اتجاه","لأنهما لا تُقاسان بأدوات قياس، فلا يمكن تحديد اتجاههما","لأنهما كميتان متجهتان اتجاههما معروف مسبقًا"]'::jsonb, 'فهم', 'تعليل', 'صعب', 'الكتاب ص 35 — الكميات الفيزيائية المتجهة والقياسية (العددية)'),
('essay', 1, 'وضّح المقصود بكل من الكمية الفيزيائية المتجهة والكمية الفيزيائية القياسية (العددية)، وبيّن الفرق الأساسي بينهما.', null, null, null, 'فهم', 'شرح مفهوم', 'سهل', 'الكتاب ص 35 — الكميات الفيزيائية المتجهة والقياسية (العددية)'),
('essay', 2, 'مشيت من بيتك 0.5 km شرقًا ثم 0.2 km شرقًا. (أ) ما بعدك عن البيت؟ (ب) ما بعدك عن البيت لو مشيت الـ 0.2 km الثانية نحو الغرب بدلًا من الشرق؟ (ج) فسّر اختلاف الناتجين في ضوء مفهوم الكمية المتجهة.', null, null, null, 'فهم', 'تفسير بمثال', 'متوسط', 'الكتاب ص 35 — الكميات الفيزيائية المتجهة والقياسية (العددية)'),
('essay', 3, 'قال أحد الطلاب: «يكفي أن أقول لصديقي إن المدرسة تبعد 2 km عن بيتي لكي يجدها». حلّل هذه العبارة في ضوء الفرق بين الكمية المتجهة والكمية القياسية، واقترح صياغة تكفي لتحديد مكان المدرسة.', null, null, null, 'تحليل', 'تحليل عبارة', 'صعب', 'الكتاب ص 35 — الكميات الفيزيائية المتجهة والقياسية (العددية)')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
