from (values
('mcq', 1, 3, 'الكميات الفيزيائية التي يتطلب تعيينها تحديد مقدارها واتجاهها وفقًا لنقطة الإسناد تُسمّى كميات متجهة.', '["هذا تعريف الكمية القياسية (العددية).","الكمية المتجهة قد تكون سالبة بحسب اتجاهها، والإشارة ليست أساس التعريف.","التغير مع الزمن لا يميّز الكمية المتجهة؛ فدرجة الحرارة مثلًا تتغير وهي قياسية.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-11-18T12:34:59.209Z"}'::jsonb),
('mcq', 2, 1, 'الكميات الفيزيائية التي يكفي لتعيينها تحديد مقدارها فقط تُسمّى كميات قياسية (عددية).', '["الكمية المتجهة تحتاج إلى مقدار واتجاه معًا.","","الموقع متجه يحتاج إلى مقدار واتجاه من نقطة الأصل.","المحصلة متجه ناتج عن جمع متجهات، فلها مقدار واتجاه."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-11-18T12:34:59.209Z"}'::jsonb),
('mcq', 3, 0, 'تغيّر المكان كمية متجهة؛ فالقارب قد يكون 300 m شمال الرصيف أو جنوبه أو في أي اتجاه آخر، ولا يتحدد مكانه إلا بذكر الاتجاه مع المقدار.', '["","المتر هو وحدة قياس المسافة والطول في النظام الدولي.","الزمن لا يلزم لتحديد مكان القارب؛ الناقص هو الاتجاه.","أي مقدار يمكن تمثيله باختيار مقياس رسم مناسب."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-11-18T12:34:59.210Z"}'::jsonb),
('mcq', 4, 2, 'عندما تكون الإزاحتان في الاتجاه نفسه يُجمع المقداران مباشرة، مثل 0.5 km شرقًا + 0.2 km شرقًا = 0.7 km شرقًا؛ أما إذا اختلف الاتجاه فلا يكون الناتج مجموع المقدارين.', '["في الاتجاهين المتعاكسين يكون مقدار المجموع هو الفرق بين المقدارين.","الإزاحة كمية متجهة؛ فاتجاهها يؤثر في ناتج جمعها.","","يحدث ذلك عند اتحاد الاتجاه، مثل 0.5 km شرقًا و0.2 km شرقًا مجموعهما 0.7 km شرقًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (4%)"}],"at":"2026-11-18T12:34:59.210Z"}'::jsonb),
('mcq', 5, 1, 'القوة كمية متجهة لأن تعيينها يتطلب مقدارها (20 N) واتجاهها (الشمال) وفقًا لنقطة الإسناد.', '["كِبر المقدار لا يحدد نوع الكمية؛ فالكمية القياسية قد تكون كبيرة أيضًا.","","الوحدة لا تحدد كون الكمية متجهة أو قياسية.","التسبب في الحركة ليس أساس التصنيف؛ الأساس هو الحاجة إلى الاتجاه."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-11-18T12:34:59.210Z"}'::jsonb),
('mcq', 6, 3, 'تحركا في اتجاهين مختلفين؛ فالمسافة كمية قياسية لا تحدد الاتجاه، وتساويها لا يعني الوصول إلى المكان نفسه؛ أما تغيّر المكان فكمية متجهة تختلف باختلاف الاتجاه.', '["المسافتان متساويتان (200 m) كما في نص السؤال.","الزمن لا يغير المكان النهائي إذا تساوت المسافة واتحد الاتجاه.","المسافة كمية قياسية (عددية) لها مقدار فقط.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (0%)"}],"at":"2026-11-18T12:34:59.210Z"}'::jsonb),
('mcq', 7, 0, 'الزمن ودرجة الحرارة كميتان قياسيتان (عدديتان)؛ يكفي لتعيين كل منهما ذكر مقداره مع وحدته.', '["","كون القيمة موجبة لا يلغي الحاجة إلى الاتجاه في الكميات المتجهة.","الزمن يُقاس بالساعة ودرجة الحرارة بميزان الحرارة.","الزمن ودرجة الحرارة كميتان قياسيتان لا اتجاه لهما أصلًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (6%)"}],"at":"2026-11-18T12:34:59.210Z"}'::jsonb),
('essay', 1, null::int, null, null, 'الكمية المتجهة: كمية فيزيائية يتطلب تعيينها تحديد مقدارها واتجاهها وفقًا لنقطة الإسناد. الكمية القياسية (العددية): كمية فيزيائية يكفي لتعيينها تحديد مقدارها فقط. الفرق الأساسي: الحاجة إلى الاتجاه؛ فالمتجهة لها مقدار واتجاه، والقياسية لها مقدار فقط.', '["تعريف الكمية المتجهة","تعريف الكمية القياسية","الفرق: الاتجاه"]'::jsonb, '[]'::jsonb, '[{"element":"الكمية المتجهة","marks":1},{"element":"الكمية القياسية","marks":1},{"element":"الفرق","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"إجابة كاملة صحيحة تشمل جميع العناصر المطلوبة."},{"level":"درجة جزئية","description":"يذكر بعض العناصر صحيحة أو يخطئ في أحدها."},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة."}]'::jsonb, '["تعريف الكمية المتجهة بأنها كمية لها اتجاه فقط.","الظن أن الكمية القياسية لا وحدة لها."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-11-18T12:34:59.210Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) $0.5 + 0.2 = 0.7\ \text{km}$ شرق البيت. (ب) $0.5 - 0.2 = 0.3\ \text{km}$ شرق البيت. (ج) الإزاحة كمية متجهة؛ فناتج جمع إزاحتين يعتمد على مقداريهما واتجاهيهما معًا، فإذا اتحد الاتجاه جُمع المقداران، وإذا تعاكس طُرح الأصغر من الأكبر.', '["0.7 km شرقًا","0.3 km شرقًا","التفسير: الإزاحة كمية متجهة يؤثر اتجاهها في ناتج الجمع"]'::jsonb, '["(أ) الإزاحتان في الاتجاه نفسه: $0.5\\ \\text{km} + 0.2\\ \\text{km} = 0.7\\ \\text{km}$ شرقًا.","(ب) الإزاحتان متعاكستان: $0.5\\ \\text{km} - 0.2\\ \\text{km} = 0.3\\ \\text{km}$ شرقًا (في اتجاه الإزاحة الأكبر)."]'::jsonb, '[{"element":"الناتج الأول","marks":1},{"element":"الناتج الثاني","marks":1},{"element":"التفسير","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"إجابة كاملة صحيحة تشمل جميع العناصر المطلوبة."},{"level":"درجة جزئية","description":"يذكر بعض العناصر صحيحة أو يخطئ في أحدها."},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة."}]'::jsonb, '["جمع 0.5 و0.2 في الحالتين.","إهمال ذكر اتجاه الناتج."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-11-18T12:34:59.210Z"}'::jsonb),
('essay', 3, null::int, null, null, 'العبارة غير كافية؛ لأن «2 km» مقدار فقط (كمية قياسية)، وكل الأماكن التي تبعد 2 km عن البيت في أي اتجاه تحقق هذا الوصف، فلا يتحدد مكان المدرسة. تحديد المكان يتطلب كمية متجهة لها مقدار واتجاه بالنسبة إلى نقطة إسناد (البيت). الصياغة المقترحة: «المدرسة على بعد 2 km شرق بيتي» (أو أي اتجاه صحيح).', '["العبارة غير كافية","2 km مقدار فقط فتتحقق في اتجاهات كثيرة","تحديد المكان يتطلب مقدارًا واتجاهًا من نقطة إسناد","صياغة صحيحة تتضمن الاتجاه"]'::jsonb, '[]'::jsonb, '[{"element":"الحكم","marks":1},{"element":"التعليل","marks":1},{"element":"ربطه بالكمية المتجهة","marks":1},{"element":"الصياغة المقترحة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة تشمل جميع العناصر المطلوبة."},{"level":"درجة جزئية","description":"يذكر بعض العناصر صحيحة أو يخطئ في أحدها."},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة."}]'::jsonb, '["الاكتفاء بالحكم دون تعليل.","إضافة الزمن بدل الاتجاه في الصياغة."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-18T12:34:59.210Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
