('essay', 1, null::int, null, null, 'كميات متجهة: الإزاحة، والقوة (ويُقبل الموقع). كميات قياسية (عددية): المسافة، والزمن، ودرجة الحرارة.', '["مثالان صحيحان على الكميات المتجهة","ثلاثة أمثلة صحيحة على الكميات القياسية"]'::jsonb, '[]'::jsonb, '[{"element":"المثالان المتجهان","marks":2},{"element":"الأمثلة القياسية الثلاثة","marks":3}]'::jsonb, '[{"level":"5 درجات","description":"إجابة كاملة صحيحة تشمل جميع العناصر المطلوبة."},{"level":"درجة جزئية","description":"يذكر بعض العناصر صحيحة أو يخطئ في أحدها."},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة."}]'::jsonb, '["ذكر المسافة مثالًا على كمية متجهة.","ذكر الإزاحة والمسافة في القائمة نفسها."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-11-18T12:34:59.212Z"}'::jsonb),
('essay', 2, null::int, null, null, 'متجهة: الموقع، والقوة، والإزاحة؛ لأن تعيين كل منها يتطلب مقدارًا واتجاهًا وفقًا لنقطة الإسناد. قياسية (عددية): الزمن، ودرجة الحرارة، والمسافة؛ لأنه يكفي لتعيين كل منها مقدارها فقط.', '["الموقع والقوة والإزاحة متجهة","الزمن ودرجة الحرارة والمسافة قياسية","سبب التصنيف"]'::jsonb, '[]'::jsonb, '[{"element":"تصنيف المتجهة","marks":1.5},{"element":"تصنيف القياسية","marks":1.5},{"element":"السبب","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة تشمل جميع العناصر المطلوبة."},{"level":"درجة جزئية","description":"يذكر بعض العناصر صحيحة أو يخطئ في أحدها."},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة."}]'::jsonb, '["تصنيف المسافة متجهة.","تصنيف الموقع قياسيًا لأنه «عدد»."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (38%)"}],"at":"2026-11-18T12:34:59.212Z"}'::jsonb),
('essay', 3, null::int, null, null, 'أمثلة: (أ) «انتقلتُ من باب الصف إلى السبورة 6 m نحو الشمال». (ب) «قطعتُ في نزهتي 3 km». (ج) «دفعتُ الباب بقوة 15 N نحو الخارج». (د) «استغرقت الحصة 45 min». اشترطتُ ذكر الاتجاه مع المقدار والوحدة في جملتي الإزاحة والقوة لأنهما كميتان متجهتان، واكتفيت بالمقدار والوحدة في جملتي المسافة والزمن لأنهما كميتان قياسيتان.', '["جملة إزاحة فيها مقدار واتجاه","جملة مسافة فيها مقدار فقط","جملة قوة فيها مقدار واتجاه","جملة زمن فيها مقدار فقط","بيان اشتراط الاتجاه للكميات المتجهة"]'::jsonb, '[]'::jsonb, '[{"element":"الإزاحة","marks":1},{"element":"المسافة","marks":1},{"element":"القوة","marks":1},{"element":"الزمن","marks":1},{"element":"البيان","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"إجابة كاملة صحيحة تشمل جميع العناصر المطلوبة."},{"level":"درجة جزئية","description":"يذكر بعض العناصر صحيحة أو يخطئ في أحدها."},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة."}]'::jsonb, '["ذكر اتجاه مع المسافة أو الزمن.","إغفال الاتجاه في جملة القوة أو الإزاحة."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-11-18T12:34:59.212Z"}'::jsonb)
