('essay', 1, 'وضّح كيف تُمثَّل الكميات الفيزيائية المتجهة بالرسم، وما الذي يدل عليه كل من طول السهم واتجاهه، ولماذا يلزم اختيار مقياس رسم.', null, null, null, 'فهم', 'شرح إجراء', 'سهل', 'الكتاب ص 35 — تمثيل الكميات المتجهة بالأسهم ومقياس الرسم'),
('essay', 2, 'مشى طالب 0.5 km شرقًا من بيته إلى البقالة. (أ) اختر مقياس رسم مناسبًا لتمثيل هذه الإزاحة على ورقة دفترك. (ب) احسب طول السهم بالمقياس الذي اخترته. (ج) صف كيف ترسم السهم.', null, null, null, 'تطبيق', 'رسم بمقياس', 'متوسط', 'الكتاب ص 35 — تمثيل الكميات المتجهة بالأسهم ومقياس الرسم'),
('essay', 3, 'رسم طالبان الإزاحة نفسها (300 m شمالًا)؛ فرسمها الأول بسهم طوله 3 cm، والثاني بسهم طوله 6 cm. (أ) ما المقياس الذي استخدمه كل منهما؟ (ب) هل يمكن أن يكون الرسمان صحيحين معًا؟ فسّر. (ج) ما الذي يجب أن يُكتب مع كل رسم ليُفهم بشكل صحيح؟', null, null, null, 'تحليل', 'تحليل ومقارنة', 'صعب', 'الكتاب ص 35 — تمثيل الكميات المتجهة بالأسهم ومقياس الرسم')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
