select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 2, 'تُمثَّل الكميات المتجهة بالأسهم، على أن يكون طول السهم متناسبًا مع مقدار الكمية وفق مقياس رسم مناسب، ويشير السهم إلى اتجاهها.', '["النقطة لا تبيّن مقدارًا ولا اتجاهًا؛ فهي تُستخدم في نموذج الجسيم النقطي لا لتمثيل المتجه.","الخط بلا رأس لا يبيّن الاتجاه، وثبات طوله لا يبيّن المقدار.","","طول السهم يجب أن يتناسب مع مقدار الكمية وفق مقياس رسم مناسب."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-11-18T12:34:59.212Z"}'::jsonb),
('mcq', 2, 0, 'غالبًا ما يُعبَّر عن الكمية المتجهة بوضع سهم فوق رمزها، أو بكتابة رمزها بحروف البنط العريض مثل $\boldsymbol{F}$ و$\boldsymbol{d}$.', '["","الإشارة السالبة تدل على الاتجاه المعاكس، ولا تميّز المتجه من غيره.","حجم الحرف لا يميّز الكمية المتجهة؛ فالرمز t للزمن صغير وهو قياسي.","الأقواس لا تُستخدم للدلالة على أن الكمية متجهة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-11-18T12:34:59.212Z"}'::jsonb),
('mcq', 3, 1, 'طول السهم 6 مربعات = 6 cm، وكل 1 cm يمثل 0.1 km؛ فالإزاحة $6 \times 0.1 = 0.6\ \text{km}$ نحو الشرق (اتجاه السهم).', '["عُدّ كل مربع 1 km بدلًا من 0.1 km.","","السهم يشير نحو اليمين، وهو اتجاه الشرق.","قُسم طول السهم على 100 بدل ضربه في 0.1 km؛ فطوله 6 cm يقابل 0.6 km."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (37%)"}],"at":"2026-11-18T12:34:59.213Z"}'::jsonb),
('mcq', 4, 3, 'عدد المربعات اللازم = $150 \div 50 = 3$ مربعات، والاتجاه نحو الغرب (اليسار)؛ وهذا هو السهم (3).', '["طوله 3 مربعات (150 m) صحيح، لكنه يتجه نحو الشرق.","طوله 6 مربعات يمثل 300 m؛ وكأن كل مربع عُدّ 25 m.","طوله 5 مربعات يمثل 250 m لا 150 m.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (37%)"}],"at":"2026-11-18T12:34:59.213Z"}'::jsonb),
('mcq', 5, 0, 'بمقياس الرسم نفسه يتناسب طول السهم مع المقدار: طول A ستة مربعات وطول B ثلاثة، فمقدار A ضعف مقدار B، والسهمان يشيران إلى اتجاهين متعاكسين.', '["","سهم A طوله 6 مربعات وسهم B طوله 3؛ فالأكبر هو A.","طولا السهمين مختلفان، وبمقياس الرسم نفسه يعني ذلك اختلاف المقدارين.","سهم A يشير نحو اليمين وسهم B نحو اليسار؛ فهما متعاكسان."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-11-18T12:34:59.213Z"}'::jsonb),
('mcq', 6, 2, 'طول السهم = المقدار ÷ ما يمثله 1 cm. بالمقياس 1 cm لكل 0.2 km: $2.4 \div 0.2 = 12\ \text{cm}$، وهو الوحيد الأقل من 15 cm.', '["يصبح طول السهم $2.4 \\div 0.1 = 24\\ \\text{cm}$، وهو أطول من 15 cm.","يصبح طول السهم $2.4 \\div 0.12 = 20\\ \\text{cm}$، وهو أطول من 15 cm.","","يصبح طول السهم $2.4 \\div 0.15 = 16\\ \\text{cm}$، وهو أطول من 15 cm بقليل."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-11-18T12:34:59.213Z"}'::jsonb),
('mcq', 7, 3, 'بالمقياس نفسه يتناسب طول السهم طرديًا مع المقدار: الإزاحة الأولى 0.4 km وطولها 4 cm، والثانية 0.8 km فطولها 8 cm.', '["طول السهم يتناسب مع المقدار؛ فلا يبقى ثابتًا عند مضاعفة المقدار.","قُسم الطول على 2 بدل ضربه؛ فمضاعفة المقدار تضاعف الطول.","خُلط بين مقدار الإزاحة (0.8 km) وطول السهم الذي يمثلها.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-11-18T12:34:59.213Z"}'::jsonb),
('essay', 1, null::int, null, null, 'تُمثَّل الكمية المتجهة بسهم: يدل طوله على مقدار الكمية، ويدل اتجاهه على اتجاهها. ولأن المقادير الحقيقية (مثل 0.5 km) لا يمكن رسمها بأطوالها، يُختار مقياس رسم مناسب (مثل 1 cm لكل 0.1 km) يجعل طول السهم متناسبًا مع مقدار الكمية ويتسع له الورق.', '["التمثيل بسهم","الطول يدل على المقدار","الاتجاه يدل على اتجاه الكمية","مقياس الرسم يجعل الطول متناسبًا مع المقدار"]'::jsonb, '[]'::jsonb, '[{"element":"التمثيل بسهم","marks":1},{"element":"دلالة الطول","marks":1},{"element":"دلالة الاتجاه","marks":1},{"element":"مقياس الرسم","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة تشمل جميع العناصر المطلوبة."},{"level":"درجة جزئية","description":"يذكر بعض العناصر صحيحة أو يخطئ في أحدها."},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة."}]'::jsonb, '["رسم أسهم بأطوال عشوائية لا تتناسب مع المقادير.","إهمال رسم رأس السهم."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-11-18T12:34:59.213Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) مقياس مناسب: 1 cm لكل 0.1 km. (ب) طول السهم = $0.5 \div 0.1 = 5$ cm. (ج) أرسم بالمسطرة خطًا طوله 5 cm يبدأ من نقطة تمثل البيت، متجهًا نحو الشرق (يمين الورقة عند اعتبار الشرق يمينًا)، وأضع رأس السهم عند نهايته، وأكتب عليه مقياس الرسم.', '["اختيار مقياس مناسب","حساب طول السهم وفق المقياس","رسم السهم من البيت نحو الشرق مع رأسه"]'::jsonb, '["طول السهم = مقدار الإزاحة ÷ ما يمثله 1 cm","طول السهم = $0.5\\ \\text{km} \\div 0.1\\ \\text{km}$ لكل cm = 5 cm"]'::jsonb, '[{"element":"المقياس","marks":1},{"element":"طول السهم","marks":1},{"element":"وصف الرسم","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"إجابة كاملة صحيحة تشمل جميع العناصر المطلوبة."},{"level":"درجة جزئية","description":"يذكر بعض العناصر صحيحة أو يخطئ في أحدها."},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة."}]'::jsonb, '["اختيار مقياس يجعل السهم أطول من الورقة أو قصيرًا جدًا.","رسم السهم دون رأس أو في الاتجاه الخطأ."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-11-18T12:34:59.213Z"}'::jsonb),
('essay', 3, null::int, null, null, '(أ) الأول: $300 \div 3 = 100\ \text{m}$ لكل 1 cm. الثاني: $300 \div 6 = 50\ \text{m}$ لكل 1 cm. (ب) نعم، الرسمان صحيحان؛ لأن كلًّا منهما يتناسب فيه طول السهم مع المقدار وفق مقياسه، وكلا السهمين يتجه شمالًا. (ج) يجب أن يُكتب مقياس الرسم المستخدم (واتجاه الشمال)، وإلا لا يمكن معرفة المقدار من طول السهم.', '["مقياس الأول 1 cm لكل 100 m","مقياس الثاني 1 cm لكل 50 m","الرسمان صحيحان مع التعليل","كتابة مقياس الرسم على الرسم"]'::jsonb, '["ما يمثله 1 cm = المقدار ÷ طول السهم","الأول: $300\\ \\text{m} \\div 3\\ \\text{cm} = 100\\ \\text{m}$ لكل cm","الثاني: $300\\ \\text{m} \\div 6\\ \\text{cm} = 50\\ \\text{m}$ لكل cm"]'::jsonb, '[{"element":"المقياس الأول","marks":1},{"element":"المقياس الثاني","marks":1},{"element":"الحكم والتعليل","marks":1},{"element":"ما يُكتب على الرسم","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة تشمل جميع العناصر المطلوبة."},{"level":"درجة جزئية","description":"يذكر بعض العناصر صحيحة أو يخطئ في أحدها."},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة."}]'::jsonb, '["الحكم بأن السهم الأطول يمثل إزاحة أكبر رغم اختلاف المقياسين.","قسمة الطول على المقدار بدل العكس."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-11-18T12:34:59.214Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
