from (values
('mcq', 1, 'ما المقصود بالإزاحة؟', null, null, '["كمية قياسية تمثل كل ما يقطعه الجسم دون تحديد الاتجاه","كمية فيزيائية متجهة تمثل مقدار التغير في موقع الجسم في اتجاه معين","الفرق بين زمنين تُقاس عندهما حركة الجسم","متجه ذيله عند نقطة الأصل ورأسه عند مكان الجسم"]'::jsonb, 'تذكر', 'تذكر تعريف', 'سهل', 'الكتاب ص 36 — الفترة الزمنية والإزاحة'),
('mcq', 2, 'ما الرمز الذي يُستخدم للدلالة على الإزاحة؟', null, null, '["$\\Delta t$","$\\boldsymbol{d}_i$","$\\boldsymbol{d}_f$","$\\Delta\\boldsymbol{d}$"]'::jsonb, 'تذكر', 'تذكر رمز', 'سهل', 'الكتاب ص 36 — الفترة الزمنية والإزاحة'),
