('mcq', 1, 1, 'الإزاحة كمية فيزيائية متجهة، وتمثل مقدار التغير الذي يحدث لموقع الجسم في اتجاه معين.', '["هذا تعريف المسافة لا الإزاحة.","","هذا تعريف الفترة الزمنية.","هذا وصف متجه الموقع."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (0%)"}],"at":"2026-11-18T12:34:59.214Z"}'::jsonb),
('mcq', 2, 3, 'يُرمز للإزاحة بالرمز $\Delta\boldsymbol{d}$، أي التغير في الموقع $\boldsymbol{d}$.', '["هذا رمز الفترة الزمنية.","هذا رمز الموقع الابتدائي.","هذا رمز الموقع النهائي.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-11-18T12:34:59.214Z"}'::jsonb),
('mcq', 3, 0, 'الإزاحة $\Delta\boldsymbol{d}$ تساوي متجه الموقع النهائي $\boldsymbol{d}_f$ مطروحًا منه متجه الموقع الابتدائي $\boldsymbol{d}_i$.', '["","الترتيب معكوس؛ فالإزاحة هي الموقع النهائي مطروحًا منه الموقع الابتدائي.","الإزاحة تغيّر في الموقع؛ فهي فرق بين الموقعين لا مجموعهما.","هذا لا يصح إلا إذا بدأ الجسم من نقطة الأصل؛ فالإزاحة عمومًا فرق بين الموقعين النهائي والابتدائي."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-11-18T12:34:59.214Z"}'::jsonb),
('mcq', 4, 2, 'سهم الإزاحة يشير ذيله إلى موقع بداية الحركة (الموقع 1 عند 5 m)، ورأسه إلى موقع نهايتها (الموقع 2 عند 25 m)، وهذا هو السهم (3).', '["يبدأ عند الموقع 2 وينتهي عند الموقع 1؛ أي أن اتجاهه معكوس.","يبدأ من نقطة الأصل؛ فهو متجه الموقع النهائي لا الإزاحة.","","يبدأ من نقطة الأصل وينتهي عند الموقع 1؛ فهو متجه الموقع الابتدائي."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-11-18T12:34:59.214Z"}'::jsonb),
('mcq', 5, 1, 'طول سهم الإزاحة يمثل مقدار تغير موقع الجسم (ما قطعه في اتجاه معين)، واتجاهه هو اتجاه هذا التغير.', '["هذا يمثله طول متجه الموقع النهائي، لا متجه الإزاحة.","","السهم مرسوم بوحدات الموقع، فطوله لا يمثل زمنًا.","سهم الإزاحة يبيّن تغير الموقع فقط ولا يبيّن السرعة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-11-18T12:34:59.214Z"}'::jsonb),
('mcq', 6, 0, '$\Delta\boldsymbol{d} = \boldsymbol{d}_f - \boldsymbol{d}_i = 12.0\ \text{m} - (-4.0\ \text{m}) = +16.0\ \text{m}$، والإشارة الموجبة تعني أن الإزاحة نحو اليمين.', '["","أُهملت إشارة الموقع الابتدائي ($12.0 - 4.0$)، مع أن طرح عدد سالب يعني إضافته.","طُرح الموقع النهائي من الابتدائي ($-4.0 - 12.0$)، فانعكس الاتجاه.","هذا الموقع النهائي للجسم، وليس التغير في موقعه."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-11-18T12:34:59.214Z"}'::jsonb),
('mcq', 7, 3, 'بتطبيق $\Delta\boldsymbol{d} = \boldsymbol{d}_f - \boldsymbol{d}_i$: (1) $+6\ \text{m}$، (2) $+6\ \text{m}$، (3) $-6\ \text{m}$، (4) $-8\ \text{m}$. للجسمين (1) و(2) الإزاحة نفسها ($6\ \text{m}$ نحو اليمين) مع أن موقعيهما مختلفان؛ لأن الإزاحة هي التغير في الموقع لا الموقع نفسه.', '["لهما المقدار نفسه (6 m)، لكن اتجاهيهما متعاكسان ($+6$ و$-6$)، فالإزاحتان مختلفتان.","إزاحة (2) تساوي $+6\\ \\text{m}$ وإزاحة (4) تساوي $-8\\ \\text{m}$؛ ومرور الجسمين بنقطة الأصل لا يجعل إزاحتيهما متساويتين.","كلتاهما نحو اليسار، لكن مقداريهما مختلفان (6 m و8 m).",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-11-18T12:34:59.215Z"}'::jsonb),
('essay', 1, null::int, null, null, 'الإزاحة كمية فيزيائية متجهة تمثل مقدار التغير الذي يحدث لموقع الجسم في اتجاه معين. العلاقة: $\Delta\boldsymbol{d} = \boldsymbol{d}_f - \boldsymbol{d}_i$، حيث $\Delta\boldsymbol{d}$ الإزاحة، و$\boldsymbol{d}_f$ متجه الموقع النهائي، و$\boldsymbol{d}_i$ متجه الموقع الابتدائي.', '["الإزاحة كمية متجهة","تمثل التغير في الموقع في اتجاه معين","العلاقة الرياضية","دلالة الرموز"]'::jsonb, '[]'::jsonb, '[{"element":"كمية متجهة","marks":1},{"element":"التغير في الموقع","marks":1},{"element":"العلاقة","marks":1},{"element":"الرموز","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة تشمل جميع العناصر المطلوبة."},{"level":"درجة جزئية","description":"يذكر بعض العناصر صحيحة أو يخطئ في أحدها."},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة."}]'::jsonb, '["كتابة العلاقة بطرح الموقع النهائي من الابتدائي.","تعريف الإزاحة بأنها كل ما يقطعه الجسم."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (7%)"}],"at":"2026-11-18T12:34:59.215Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) ذيل السهم عند موقع البداية 8.0 m، ورأسه عند موقع النهاية 2.0 m، ويتجه نحو اليسار، وطوله يمثل 6.0 m. (ب) $\Delta\boldsymbol{d} = \boldsymbol{d}_f - \boldsymbol{d}_i = 2.0\ \text{m} - 8.0\ \text{m} = -6.0\ \text{m}$؛ والإشارة السالبة تعني أن الإزاحة في عكس الاتجاه الموجب، أي نحو اليسار، ومقدارها 6.0 m.', '["الذيل عند 8.0 m والرأس عند 2.0 m","الاتجاه نحو اليسار","$\\Delta\\boldsymbol{d} = -6.0\\ \\text{m}$","تفسير الإشارة السالبة"]'::jsonb, '["$\\Delta\\boldsymbol{d} = \\boldsymbol{d}_f - \\boldsymbol{d}_i$","$\\Delta\\boldsymbol{d} = 2.0\\ \\text{m} - 8.0\\ \\text{m} = -6.0\\ \\text{m}$","الإشارة السالبة: الإزاحة نحو اليسار"]'::jsonb, '[{"element":"الذيل والرأس","marks":1},{"element":"الاتجاه","marks":1},{"element":"الحساب","marks":1},{"element":"تفسير الإشارة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة تشمل جميع العناصر المطلوبة."},{"level":"درجة جزئية","description":"يذكر بعض العناصر صحيحة أو يخطئ في أحدها."},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة."}]'::jsonb, '["طرح الموقع النهائي من الابتدائي والحصول على $+6.0\\ \\text{m}$.","رسم ذيل السهم عند نقطة الأصل."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-11-18T12:34:59.215Z"}'::jsonb),
('essay', 3, null::int, null, null, 'لأنها تمثل تغير موقع الجسم في اتجاه معين، فلا يكتمل وصفها إلا بذكر مقدارها واتجاهها معًا. مثال: سيارة أزيحت 10 m شرقًا، وأخرى 10 m غربًا؛ مقدار الإزاحة واحد (10 m)، لكن الإزاحتين مختلفتان لاختلاف الاتجاه، فتنتهي السيارتان في مكانين مختلفين.', '["الإزاحة تتطلب مقدارًا واتجاهًا","مثال بمقدار واحد واتجاهين مختلفين","بيان أن الإزاحتين مختلفتان"]'::jsonb, '[]'::jsonb, '[{"element":"التعليل","marks":1},{"element":"المثال","marks":1},{"element":"بيان الاختلاف","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"إجابة كاملة صحيحة تشمل جميع العناصر المطلوبة."},{"level":"درجة جزئية","description":"يذكر بعض العناصر صحيحة أو يخطئ في أحدها."},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة."}]'::jsonb, '["تقديم مثال تختلف فيه المقادير لا الاتجاهات.","الاكتفاء بالقول إن الإزاحة «لها اتجاه» دون مثال."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (7%)"}],"at":"2026-11-18T12:34:59.215Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
