('mcq', 4, 0, 'المسافة هي كل ما يقطعه الجسم دون تحديد الاتجاه؛ فتزداد قراءة العدّاد بمقدار طول الطريق كاملًا ذهابًا وإيابًا.', '["","هذا يصح على الإزاحة (تصبح صفرًا)، أما المسافة فتتراكم ولا تنقص.","المسافة لا اتجاه لها، فلا تنقص عند عكس اتجاه الحركة.","كل ما تقطعه السيارة يُضاف إلى المسافة، بما في ذلك طريق العودة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-18T12:34:59.216Z"}'::jsonb),
('mcq', 5, 3, 'المسافة تعبّر عمّا يقطعه الجسم دون تحديد الاتجاه، فلا إشارة اتجاه لها؛ فهي كمية قياسية، فهي مجموع أطوال، ولا تحمل إشارة سالبة.', '["الجسم قد يتحرك في الاتجاه السالب، ومع ذلك تبقى المسافة موجبة.","نقطة الأصل قد تقع في أي مكان، ولا علاقة لها بإشارة المسافة.","المسافة قد تكون أكبر من مقدار الإزاحة، كما في الذهاب والعودة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-11-18T12:34:59.216Z"}'::jsonb),
('mcq', 6, 2, 'المسافة هي كل ما يقطعه الجسم دون تحديد الاتجاه؛ فتُجمع أطوال أجزاء المسار: $30\ \text{m} + 40\ \text{m} = 70\ \text{m}$. أما 50 m فهو البعد المستقيم بين البداية والنهاية (مقدار الإزاحة) لا المسافة.', '["هذا البعد المستقيم بين نقطتي البداية والنهاية (مقدار الإزاحة)، والطالب لم يسلك هذا الخط.","جُمع البعد المستقيم 50 m مع جزأي المسار، مع أنه ليس جزءًا مما قطعه.","","طُرح الجزآن كأنهما متعاكسان؛ والمسافة لا تُطرح أجزاؤها، كما أن الجزأين متعامدان لا متعاكسان."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-11-18T12:34:59.216Z"}'::jsonb),
('mcq', 7, 1, 'المسافة تُذكر بمقدارها فقط دون اتجاه، كما في «قطع الدرّاج 12 km».', '["ذُكر الاتجاه، فهذه إزاحة لا مسافة.","","هذا تحديد لموقع البقالة بالنسبة إلى المدرسة، وهو متجه.","تغيّر الموقع في اتجاه معين هو الإزاحة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (0%)"}],"at":"2026-11-18T12:34:59.216Z"}'::jsonb),
('essay', 1, null::int, null, null, 'المسافة تعبّر عن كل ما يقطعه الجسم دون تحديد الاتجاه. وهي كمية قياسية (عددية)؛ لأنه يكفي لتعيينها مقدارها مع وحدته (مثل 400 m)، ولا يلزم ذكر اتجاه.', '["تعريف المسافة","المسافة كمية قياسية","التعليل: يكفي مقدارها"]'::jsonb, '[]'::jsonb, '[{"element":"التعريف","marks":1},{"element":"النوع","marks":1},{"element":"التعليل","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"إجابة كاملة صحيحة تشمل جميع العناصر المطلوبة."},{"level":"درجة جزئية","description":"يذكر بعض العناصر صحيحة أو يخطئ في أحدها."},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة."}]'::jsonb, '["تعريف المسافة بأنها تغيّر الموقع.","تصنيف المسافة متجهة."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-11-18T12:34:59.216Z"}'::jsonb),
('essay', 2, null::int, null, null, 'المسافة هي كل ما يقطعه الجسم دون تحديد الاتجاه، فنجمع أطوال أجزاء المسار: في الذهاب $40 - 0 = 40\ \text{m}$، وفي العودة $40 - 10 = 30\ \text{m}$، فالمسافة = $40 + 30 = 70$ m. رجوعه في الاتجاه المعاكس لا يُطرح؛ لأن المسافة لا اتجاه لها، فكل متر يقطعه يُضاف إليها.', '["جمع أطوال أجزاء المسار","الذهاب 40 m والعودة 30 m","المسافة 70 m","التفسير: المسافة لا اتجاه لها فلا يُطرح جزء العودة"]'::jsonb, '["طول الذهاب = $40\\ \\text{m} - 0\\ \\text{m} = 40\\ \\text{m}$","طول العودة = $40\\ \\text{m} - 10\\ \\text{m} = 30\\ \\text{m}$","المسافة = $40\\ \\text{m} + 30\\ \\text{m} = 70\\ \\text{m}$"]'::jsonb, '[{"element":"الطريقة","marks":1},{"element":"الجزءان","marks":1},{"element":"الناتج","marks":1},{"element":"التفسير","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة تشمل جميع العناصر المطلوبة."},{"level":"درجة جزئية","description":"يذكر بعض العناصر صحيحة أو يخطئ في أحدها."},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة."}]'::jsonb, '["طرح جزء العودة والحصول على 10 m.","الاكتفاء بالموقع النهائي 10 m."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-11-18T12:34:59.216Z"}'::jsonb),
('essay', 3, null::int, null, null, '(أ) المسافة = $12530 - 12450 = 80$ km. (ب) لأن العدّاد يقيس المسافة، وهي كل ما تقطعه السيارة دون تحديد الاتجاه؛ فطريق العودة يُضاف إلى ما قطعته ولا يُطرح منه، بخلاف الإزاحة التي تصبح صفرًا عند العودة إلى المنزل.', '["المسافة 80 km","العدّاد يقيس المسافة","المسافة لا اتجاه لها فتُضاف أجزاء الطريق"]'::jsonb, '["المسافة = القراءة النهائية مطروحًا منها القراءة الابتدائية","المسافة = $12530\\ \\text{km} - 12450\\ \\text{km} = 80\\ \\text{km}$"]'::jsonb, '[{"element":"الحساب","marks":1},{"element":"التفسير","marks":2}]'::jsonb, '[{"level":"3 درجات","description":"إجابة كاملة صحيحة تشمل جميع العناصر المطلوبة."},{"level":"درجة جزئية","description":"يذكر بعض العناصر صحيحة أو يخطئ في أحدها."},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة."}]'::jsonb, '["الظن أن المسافة صفر لعودة السيارة إلى المنزل.","قسمة الفرق على 2."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-18T12:34:59.216Z"}'::jsonb)
