('mcq', 4, 'رُسمت في الشكل الآتي ثلاث إزاحات متتالية $\boldsymbol{A}$ ثم $\boldsymbol{B}$ ثم $\boldsymbol{C}$ منفصلةً، بمقياس رسم يمثل فيه طول ضلع كل مربع 20 m. ما محصلة جمعها بيانيًا؟', null, '[{"src":"qimg/phys1/c2l2-o09-three.svg","alt":"شبكة مربعات فيها ثلاثة متجهات خضراء أفقية مرسومة منفصلة في صفوف مختلفة: المتجه A طوله 5 مربعات ويتجه نحو اليمين (الشرق)، والمتجه B طوله 8 مربعات ويتجه نحو اليسار (الغرب)، والمتجه C طوله مربعان ويتجه نحو اليمين (الشرق). بجانب الشبكة سهما اتجاه: الشرق نحو اليمين والشمال نحو الأعلى."}]'::jsonb, '["300 m شرقًا","20 m غربًا","20 m شرقًا","1 m غربًا"]'::jsonb, 'تطبيق', 'جمع بياني لثلاث إزاحات', 'صعب', 'الكتاب ص 35 — جمع المتجهات بيانيًا (الشكل 2-8)'),
('mcq', 5, 'تحركت دراجة 400 m شمالًا ثم 600 m جنوبًا. لجمع الإزاحتين بيانيًا بمقياس 1 cm لكل 200 m، رُسم السهم الأول بطول 2 cm نحو الشمال. كيف يُرسم السهم الثاني؟', null, null, '["بطول 3 cm نحو الجنوب، ويبدأ ذيله من رأس السهم الأول","بطول 3 cm نحو الجنوب، ويبدأ ذيله من ذيل السهم الأول","بطول 3 cm نحو الشمال، ويبدأ ذيله من رأس السهم الأول","بطول 1 cm نحو الجنوب، ويبدأ ذيله من رأس السهم الأول"]'::jsonb, 'تطبيق', 'تطبيق إجراء', 'متوسط', 'الكتاب ص 35 — جمع المتجهات بيانيًا (الشكل 2-8)'),
('mcq', 6, 'جمع طالب بيانيًا إزاحتين: 40 m شرقًا و20 m شرقًا بمقياس 1 cm لكل 10 m. رسم السهم الأول 4 cm، ثم رسم الثاني 4 cm أيضًا ليكون الرسم «متناسقًا»، فحصل على محصلة 80 m. ما خطؤه؟', null, null, '["كان يجب أن يضع ذيلي السهمين عند النقطة نفسها بدل وصل الرأس بالذيل","كان يجب أن يرسم السهم الثاني نحو الغرب حتى تكون المحصلة 20 m","كان يجب أن يستخدم مقياس رسم مختلفًا لكل متجه بحسب مقداره","لم يجعل طول السهم الثاني متناسبًا مع مقداره؛ فطوله يجب أن يكون 2 cm فتكون المحصلة 60 m"]'::jsonb, 'تحليل', 'اكتشاف خطأ', 'صعب', 'الكتاب ص 35 — جمع المتجهات بيانيًا (الشكل 2-8)'),
('mcq', 7, 'يبيّن الشكل الآتي إزاحة أولى $\boldsymbol{A}$ مرسومة من النقطة O بمقياس رسم يمثل فيه طول ضلع كل مربع 50 m. يُراد أن تُجمع معها بيانيًا إزاحة ثانية $\boldsymbol{B}$ مقدارها 150 m نحو الغرب. عند رسم $\boldsymbol{B}$ بطريقة صحيحة، فوق أيّ النقاط المحددة أسفل الشبكة يقع رأسه؟', null, '[{"src":"qimg/phys1/c2l2-o09-complete.svg","alt":"شبكة مربعات فيها نقطة O، ومنها متجه أخضر أفقي A طوله 5 مربعات نحو اليمين (الشرق). أسفل الشبكة أربع نقاط مرقمة بحروف: P على بعد 3 مربعات يسار O، وQ على بعد مربعين يسار O، وR على بعد مربعين يمين O، وS على بعد 8 مربعات يمين O. بجانب الشبكة سهما اتجاه: الشرق نحو اليمين والشمال نحو الأعلى."}]'::jsonb, '["النقطة P","النقطة Q","النقطة R","النقطة S"]'::jsonb, 'تطبيق', 'إكمال جمع بياني على الرسم', 'متوسط', 'الكتاب ص 35 — جمع المتجهات بيانيًا (الشكل 2-8)'),
('essay', 1, 'مشى خالد من بيته 300 m شرقًا إلى المسجد، ثم 500 m غربًا إلى المكتبة. باستخدام مقياس رسم 1 cm لكل 100 m: (أ) صف خطوات جمع الإزاحتين بيانيًا. (ب) ما طول متجه المحصلة على الرسم؟ وما مقدارها واتجاهها؟', null, null, null, 'تطبيق', 'جمع بياني', 'متوسط', 'الكتاب ص 35 — جمع المتجهات بيانيًا (الشكل 2-8)'),
('essay', 2, 'يبين الشكل الآتي المتجهين $\boldsymbol{A}$ و$\boldsymbol{B}$ مرسومين بمقياس رسم يمثل فيه طول ضلع كل مربع 20 m. اشرح كيف تجمعهما بيانيًا، ثم أوجد مقدار المحصلة واتجاهها.', null, '[{"src":"qimg/phys1/c2l2-o09-essay.svg","alt":"شبكة مربعات فيها متجهان أخضران أفقيان مرسومان منفصلين على السطر نفسه: المتجه A طوله 3 مربعات نحو اليمين (الشرق)، والمتجه B طوله 5 مربعات نحو اليمين (الشرق). بجانب الشبكة سهما اتجاه: الشرق نحو اليمين والشمال نحو الأعلى."}]'::jsonb, null, 'تطبيق', 'جمع بياني من رسم', 'سهل', 'الكتاب ص 35 — جمع المتجهات بيانيًا (الشكل 2-8)'),
('essay', 3, 'تحركت سيارة توصيل على طريق مستقيم يمتد بين الشمال والجنوب: 4.0 km شمالًا، ثم 6.0 km جنوبًا، ثم 1.0 km شمالًا. تريد جمع الإزاحات الثلاث بيانيًا على ورقة لا يتجاوز الطول المتاح عليها في اتجاه الشمال–الجنوب 10 cm. (أ) أيّ المقياسين أنسب: 1 cm لكل 0.5 km، أم 1 cm لكل 1 km؟ علّل بتحديد الامتداد الكلي للرسم. (ب) احسب طول كل سهم بالمقياس الذي اخترته. (ج) صف كيف ترسم الأسهم وترسم المحصلة، ثم أوجد مقدار المحصلة واتجاهها.', null, null, null, 'تحليل', 'جمع بياني بمقياس رسم مناسب', 'صعب', 'الكتاب ص 35 — جمع المتجهات بيانيًا (الشكل 2-8)')
