from (values
('mcq', 1, 0, 'يُجمع متجهان بوضع رأس الأول ملامسًا لذيل الثاني، مع المحافظة على طول كل منهما واتجاهه.', '["","الجمع بطريقة الرسم يكون بوصل الرأس بالذيل، لا بالذيلين معًا.","تلامس الرأسين لا يمثل جمع المتجهين.","عكس اتجاه المتجه الثاني يُستخدم في الطرح لا في الجمع."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-11-18T12:34:59.217Z"}'::jsonb),
('mcq', 2, 2, 'في الترتيب (3) يقع ذيل B عند رأس A، وبقي لكل منهما طوله واتجاهه كما في الأصل.', '["الذيلان عند النقطة نفسها؛ وهذا ليس ترتيب الرأس إلى الذيل.","الرأسان متلامسان، واتجاه B معكوس؛ فلم يُحافَظ على اتجاهه.","","ذيل B عند رأس A، لكن طول B صار 4 مربعات بدل مربعين؛ فلم يُحافَظ على مقداره."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-11-18T12:34:59.217Z"}'::jsonb),
('mcq', 3, 3, 'طول السهم الأول $0.4 \div 0.1 = 4\ \text{cm}$، والثاني $0.3 \div 0.1 = 3\ \text{cm}$، ويُرسمان متتاليين نحو الشرق؛ فطول المحصلة $4 + 3 = 7\ \text{cm}$ (تمثل 0.7 km).', '["هذا مقدار المحصلة بالكيلومتر (0.7 km) كُتب بوحدة cm دون تحويله بالمقياس.","طُرح السهمان ($4\\ \\text{cm} - 3\\ \\text{cm}$) مع أن الإزاحتين في الاتجاه نفسه.","ضُرب في 100 بدل القسمة على 0.1 km لكل cm.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (28%)"}],"at":"2026-11-18T12:34:59.218Z"}'::jsonb),
('mcq', 4, 1, 'نرسم $\boldsymbol{A}$ (5 مربعات شرقًا)، ثم نضع ذيل $\boldsymbol{B}$ عند رأسه ونرسمه 8 مربعات غربًا، ثم نضع ذيل $\boldsymbol{C}$ عند رأس $\boldsymbol{B}$ ونرسمه مربعين شرقًا. ينتهي رأس $\boldsymbol{C}$ على بعد $5 - 8 + 2 = -1$، أي مربع واحد غرب ذيل $\boldsymbol{A}$؛ فالمحصلة $1 \times 20 = 20\ \text{m}$ غربًا.', '["جُمعت الأطوال $5 + 8 + 2 = 15$ مربعًا دون مراعاة أن $\\boldsymbol{B}$ يتجه نحو الغرب.","","المقدار صحيح، لكن رأس المحصلة يقع غرب ذيلها؛ لأن الإزاحة الغربية (8 مربعات) أكبر من مجموع الشرقيتين (7 مربعات).","عُدّ المربع مترًا واحدًا، ولم يُستخدم المقياس (كل مربع 20 m)."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (45%)"}],"at":"2026-11-18T12:34:59.218Z"}'::jsonb),
('mcq', 5, 0, 'طول السهم الثاني = $600 \div 200 = 3\ \text{cm}$، ويُرسم في اتجاه إزاحته (الجنوب)، ويوضع ذيله عند رأس السهم الأول.', '["","في الجمع البياني يبدأ الثاني من رأس الأول لا من ذيله.","الإزاحة الثانية نحو الجنوب، فيجب المحافظة على اتجاهها.","طول السهم الثاني يمثل مقداره هو ($600\\ \\text{m} = 3\\ \\text{cm}$)، لا الفرق بين الإزاحتين."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-11-18T12:34:59.218Z"}'::jsonb),
('mcq', 6, 3, 'طول السهم الثاني يجب أن يكون $20 \div 10 = 2\ \text{cm}$؛ فطول المحصلة $4 + 2 = 6\ \text{cm}$ يمثل 60 m شرقًا. تغيير طول السهم يغيّر المقدار الذي يمثله.', '["وضع الذيل عند الرأس هو الطريقة الصحيحة للجمع؛ فليس هذا موضع الخطأ.","الإزاحة الثانية نحو الشرق، فاتجاه السهم صحيح.","يجب استخدام مقياس واحد لجميع المتجهات في الرسم الواحد.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-11-18T12:34:59.218Z"}'::jsonb),
('mcq', 7, 2, 'طول $\boldsymbol{B}$ على الرسم $150 \div 50 = 3$ مربعات نحو الغرب، ويوضع ذيله عند رأس $\boldsymbol{A}$ (5 مربعات شرق O)؛ فينتهي رأسه عند $5 - 3 = 2$ مربع شرق O، أي فوق النقطة R. والمحصلة من O إلى هذا الرأس.', '["رُسم $\\boldsymbol{B}$ من النقطة O (ذيل $\\boldsymbol{A}$) لا من رأس $\\boldsymbol{A}$.","هذا موضع يبعد مربعين غرب O؛ أي أُخذ مقدار المحصلة الصحيح وجُعل اتجاهها اتجاه $\\boldsymbol{B}$.","","رُسم $\\boldsymbol{B}$ نحو الشرق من رأس $\\boldsymbol{A}$، مع أنه يتجه نحو الغرب."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (28%)"}],"at":"2026-11-18T12:34:59.218Z"}'::jsonb),
('essay', 1, null::int, null, null, '(أ) 1) أرسم من نقطة تمثل البيت سهمًا طوله $300 \div 100 = 3\ \text{cm}$ نحو الشرق. 2) أضع ذيل السهم الثاني عند رأس الأول وأرسمه بطول $500 \div 100 = 5\ \text{cm}$ نحو الغرب. 3) أرسم متجه المحصلة من ذيل السهم الأول إلى رأس السهم الثاني. 4) أقيس طوله وأحوّله بالمقياس. (ب) طول المحصلة 2 cm، ورأسها غرب ذيلها؛ فالمحصلة $2 \times 100 = 200\ \text{m}$ غربًا (أي أن المكتبة تقع 200 m غرب البيت).', '["السهم الأول 3 cm شرقًا","السهم الثاني 5 cm غربًا من رأس الأول","المحصلة من ذيل الأول إلى رأس الثاني","طولها 2 cm","المحصلة 200 m غربًا"]'::jsonb, '["طول السهم الأول = $300\\ \\text{m} \\div 100\\ \\text{m}$ لكل cm = 3 cm شرقًا","طول السهم الثاني = $500\\ \\text{m} \\div 100\\ \\text{m}$ لكل cm = 5 cm غربًا","طول المحصلة المقيس = $5\\ \\text{cm} - 3\\ \\text{cm} = 2\\ \\text{cm}$ نحو الغرب","المحصلة = $2 \\times 100\\ \\text{m} = 200\\ \\text{m}$ غربًا"]'::jsonb, '[{"element":"السهم الأول","marks":1},{"element":"السهم الثاني وموضعه","marks":1},{"element":"رسم المحصلة","marks":1},{"element":"الطول","marks":1},{"element":"المقدار والاتجاه","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"إجابة كاملة صحيحة تشمل جميع العناصر المطلوبة."},{"level":"درجة جزئية","description":"يذكر بعض العناصر صحيحة أو يخطئ في أحدها."},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة."}]'::jsonb, '["رسم السهمين من النقطة نفسها.","الحصول على 800 m بإهمال الاتجاهين.","ذكر الاتجاه شرقًا."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (28%)"}],"at":"2026-11-18T12:34:59.219Z"}'::jsonb),
('essay', 2, null::int, null, null, 'أنقل المتجه B دون تغيير طوله أو اتجاهه بحيث يقع ذيله عند رأس A، ثم أرسم المحصلة من ذيل A إلى رأس B. طول A ثلاثة مربعات، وطول B خمسة مربعات، وكلاهما نحو الشرق؛ فطول المحصلة $3 + 5 = 8$ مربعات = $8 \times 20 = 160\ \text{m}$ شرقًا.', '["نقل B مع الحفاظ على طوله واتجاهه","ذيل B عند رأس A","المحصلة من ذيل A إلى رأس B","المحصلة 160 m شرقًا"]'::jsonb, '["طول المحصلة = $3 + 5 = 8$ مربعات","المحصلة = $8 \\times 20\\ \\text{m} = 160\\ \\text{m}$ شرقًا"]'::jsonb, '[{"element":"النقل الصحيح","marks":1},{"element":"ترتيب الرأس إلى الذيل","marks":1},{"element":"رسم المحصلة","marks":1},{"element":"المقدار والاتجاه","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة تشمل جميع العناصر المطلوبة."},{"level":"درجة جزئية","description":"يذكر بعض العناصر صحيحة أو يخطئ في أحدها."},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة."}]'::jsonb, '["عدّ المربعات دون ضربها في المقياس (8 m).","إهمال ذكر الاتجاه."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (45%)"}],"at":"2026-11-18T12:34:59.219Z"}'::jsonb),
('essay', 3, null::int, null, null, '(أ) عند رسم الأسهم رأسًا لذيل يصعد الرسم 4.0 km شمال نقطة البداية، ثم ينزل 6.0 km فيصل إلى 2.0 km جنوبها، ثم يصعد 1.0 km؛ فيمتد الرسم كله من 4.0 km شمال البداية إلى 2.0 km جنوبها، أي 6.0 km. بالمقياس 1 cm لكل 0.5 km يحتاج الرسم إلى $6.0 \div 0.5 = 12\ \text{cm}$ فلا يتسع، وبالمقياس 1 cm لكل 1 km يحتاج إلى 6.0 cm فيتسع؛ فالمقياس الأنسب 1 cm لكل 1 km. (ب) الأسهم: 4.0 cm شمالًا، و6.0 cm جنوبًا، و1.0 cm شمالًا. (ج) أرسم السهم الأول من نقطة البداية نحو الشمال، ثم أضع ذيل الثاني عند رأس الأول وأرسمه نحو الجنوب، ثم أضع ذيل الثالث عند رأس الثاني وأرسمه نحو الشمال (مع إزاحة الأسهم قليلًا جانبًا لتظهر بوضوح). أرسم المحصلة من ذيل السهم الأول إلى رأس السهم الثالث، فيكون طولها 1.0 cm ويتجه رأسها نحو الجنوب؛ فالمحصلة $1.0 \times 1 = 1.0\ \text{km}$ جنوبًا.', '["تحديد امتداد الرسم 6.0 km (لا مجموع الأطوال)","اختيار المقياس 1 cm لكل 1 km مع التعليل (12 cm لا تتسع، 6.0 cm تتسع)","أطوال الأسهم 4.0 cm و6.0 cm و1.0 cm","رسم الأسهم رأسًا لذيل مع المحافظة على الاتجاهات","المحصلة من ذيل الأول إلى رأس الثالث، طولها 1.0 cm","المحصلة 1.0 km جنوبًا"]'::jsonb, '["امتداد الرسم: من $+4.0\\ \\text{km}$ إلى $4.0 - 6.0 = -2.0\\ \\text{km}$، أي 6.0 km","بالمقياس 1 cm لكل 0.5 km: $6.0 \\div 0.5 = 12\\ \\text{cm} > 10\\ \\text{cm}$؛ وبالمقياس 1 cm لكل 1 km: $6.0\\ \\text{cm} < 10\\ \\text{cm}$","أطوال الأسهم: $4.0\\ \\text{cm}$، $6.0\\ \\text{cm}$، $1.0\\ \\text{cm}$","طول المحصلة المقيس: $4.0 - 6.0 + 1.0 = -1.0\\ \\text{cm}$، أي 1.0 cm نحو الجنوب","المحصلة $= 1.0 \\times 1\\ \\text{km} = 1.0\\ \\text{km}$ جنوبًا"]'::jsonb, '[{"element":"امتداد الرسم","marks":1},{"element":"اختيار المقياس مع التعليل","marks":1},{"element":"أطوال الأسهم","marks":1},{"element":"الرسم رأسًا لذيل","marks":1},{"element":"تعيين المحصلة وطولها","marks":1},{"element":"المقدار والاتجاه","marks":1}]'::jsonb, '[{"level":"6 درجات","description":"إجابة كاملة صحيحة تشمل جميع العناصر المطلوبة."},{"level":"3–5 درجات","description":"خطوات الجمع البياني صحيحة مع خطأ في اختيار المقياس أو في المقدار أو الاتجاه."},{"level":"1–2 درجة","description":"يحسب أطوال الأسهم أو يصف الترتيب رأسًا لذيل فقط."},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة."}]'::jsonb, '["حساب امتداد الرسم من مجموع الأطوال (11 km) واختيار مقياس أصغر من اللازم.","رسم الأسهم الثلاثة من نقطة البداية نفسها.","الحصول على 11 km بإهمال الاتجاهات.","ذكر المحصلة شمالًا لأن إزاحتين من الثلاث نحو الشمال."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-11-18T12:34:59.219Z"}'::jsonb)
