('mcq', 4, 2, 'المحصلة متجه ناتج عن جمع متجهات، فتُوجد للكميات المتجهة مثل الإزاحة والقوة.', '["الزمن كمية قياسية تُجمع حسابيًا، فلا محصلة متجهة له.","المسافة كمية قياسية لا اتجاه لها.","","درجة الحرارة كمية قياسية لا اتجاه لها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-11-18T12:34:59.220Z"}'::jsonb),
('mcq', 5, 0, 'متجه المحصلة يمثل مجموع الإزاحتين، ويتجه من ذيل الأولى إلى رأس الثانية: $0.5 + 0.2 = 0.7\ \text{km}$ شرقًا، وهو بعدك عن نقطة البداية.', '["","المحصلة تمثل مجموع الإزاحتين لا إحداهما.","الإزاحتان في الاتجاه نفسه، فلا يُطرح مقداراهما.","المحصلة تشمل جميع المتجهات المجموعة لا أكبرها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-11-18T12:34:59.220Z"}'::jsonb),
('mcq', 6, 3, 'المحصلة مجموع المتجهين، فتتحدد بمقداري المتجهين واتجاهيهما؛ أما ترتيب رسمهما فلا يغيّرها.', '["متجهان بالمقدارين نفسيهما قد تختلف محصلتهما إذا تغير اتجاه أحدهما.","مقدار كل متجه واتجاه الثاني يؤثران أيضًا في المحصلة.","ترتيب الرسم لا يغيّر المحصلة؛ إذ يصح وصل ذيل الأول برأس الثاني والعكس.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-11-18T12:34:59.220Z"}'::jsonb),
('mcq', 7, 0, 'عند اتحاد الاتجاه يقع رأس الثاني على امتداد الأول، فيساوي طول المحصلة مجموع الطولين؛ وفي غير ذلك يكون أقل.', '["","إذا تعاكس المتجهان كان مقدار المحصلة الفرق بين مقداريهما.","في هذه الحالة تكون المحصلة هي الفرق لا المجموع.","تساوي المقدارين لا يكفي؛ فإن تعاكسا كانت المحصلة صفرًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-11-18T12:34:59.220Z"}'::jsonb),
('essay', 1, null::int, null, null, 'المحصلة متجه ناتج عن جمع متجهين أو أكثر. عند جمع متجهين بيانيًا بوضع رأس الأول عند ذيل الثاني، يبدأ متجه المحصلة من ذيل المتجه الأول، وينتهي عند رأس المتجه الثاني.', '["المحصلة متجه ناتج عن جمع متجهين أو أكثر","يبدأ من ذيل المتجه الأول","ينتهي عند رأس المتجه الثاني"]'::jsonb, '[]'::jsonb, '[{"element":"التعريف","marks":1},{"element":"البداية","marks":1},{"element":"النهاية","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"إجابة كاملة صحيحة تشمل جميع العناصر المطلوبة."},{"level":"درجة جزئية","description":"يذكر بعض العناصر صحيحة أو يخطئ في أحدها."},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة."}]'::jsonb, '["رسم المحصلة من رأس الثاني إلى ذيل الأول.","تعريف المحصلة بأنها المتجه الأكبر."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-11-18T12:34:59.220Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) المحصلة متجه ناتج عن جمع متجهين أو أكثر؛ وهنا تُجمع الإزاحات الثلاث: 3.0 km شرقًا، و1.0 km غربًا، و2.5 km شرقًا. (ب) باعتبار الشرق موجبًا: $3.0 - 1.0 + 2.5 = +4.5\ \text{km}$؛ فالمحصلة 4.5 km شرقًا. يبدأ متجهها من ذيل الإزاحة الأولى (نقطة انطلاق القارب) وينتهي عند رأس الإزاحة الأخيرة (مكان توقفه). (ج) تمثل المحصلة إزاحة القارب الكلية، أي الإزاحة الواحدة التي تنقله من نقطة الانطلاق إلى مكان التوقف مباشرة، وتساوي مجموع إزاحاته الثلاث.', '["تعريف المحصلة: متجه ناتج عن جمع متجهين أو أكثر","المتجهات المجموعة: الإزاحات الثلاث","المحصلة 4.5 km شرقًا","تبدأ من ذيل الإزاحة الأولى وتنتهي عند رأس الأخيرة","تمثل الإزاحة الكلية من نقطة الانطلاق إلى مكان التوقف"]'::jsonb, '["الشرق موجب: $+3.0\\ \\text{km}$، $-1.0\\ \\text{km}$، $+2.5\\ \\text{km}$","المحصلة $= 3.0 - 1.0 + 2.5 = +4.5\\ \\text{km}$، أي 4.5 km شرقًا"]'::jsonb, '[{"element":"التعريف والمتجهات المجموعة","marks":1},{"element":"المقدار والاتجاه","marks":1},{"element":"بداية متجه المحصلة ونهايته","marks":1},{"element":"دلالة المحصلة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة تشمل جميع العناصر المطلوبة."},{"level":"درجة جزئية","description":"يذكر بعض العناصر صحيحة أو يخطئ في أحدها."},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة."}]'::jsonb, '["جمع المقادير 6.5 km دون مراعاة الاتجاه.","رسم المحصلة من رأس الإزاحة الأخيرة إلى ذيل الأولى.","عدّ المحصلة مسافة لا اتجاه لها."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-11-18T12:34:59.220Z"}'::jsonb),
('essay', 3, null::int, null, null, '(أ) أكبر مقدار $4 + 3 = 7\ \text{m}$، عندما يكون المتجهان في الاتجاه نفسه. (ب) أصغر مقدار $4 - 3 = 1\ \text{m}$، عندما يكون المتجهان متعاكسين، وتكون المحصلة في اتجاه المتجه الأكبر (4 m). (ج) المحصلة لا تساوي مجموع المقدارين دائمًا؛ فمقدارها يعتمد على الاتجاهين، ويقع هنا بين 1 m و7 m.', '["أكبر مقدار 7 m عند اتحاد الاتجاه","أصغر مقدار 1 m عند التعاكس","اتجاهها اتجاه المتجه الأكبر","الاستنتاج"]'::jsonb, '["اتحاد الاتجاه: $4\\ \\text{m} + 3\\ \\text{m} = 7\\ \\text{m}$","التعاكس: $4\\ \\text{m} - 3\\ \\text{m} = 1\\ \\text{m}$ في اتجاه المتجه 4 m"]'::jsonb, '[{"element":"أكبر مقدار وشرطه","marks":1},{"element":"أصغر مقدار وشرطه","marks":1},{"element":"اتجاه المحصلة الصغرى","marks":1},{"element":"الاستنتاج","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة تشمل جميع العناصر المطلوبة."},{"level":"درجة جزئية","description":"يذكر بعض العناصر صحيحة أو يخطئ في أحدها."},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة."}]'::jsonb, '["اعتبار أصغر محصلة صفرًا.","جعل اتجاه المحصلة الصغرى في اتجاه المتجه الأصغر."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (6%)"}],"at":"2026-11-18T12:34:59.220Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
