insert into public.questions (objective_id, type, number, stem, stimulus, images, options, thinking_level, question_kind, difficulty, source_ref, status, origin)
select (select id from public.objectives where code = 'P1-C2-L2-O11'), v.type, v.number, v.stem, v.stimulus::jsonb, v.images::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'ما المقصود بالفترة الزمنية؟', null, null, '["الفرق بين زمنين، أي الزمن النهائي مطروحًا منه الزمن الابتدائي","القراءة التي تشير إليها ساعة الإيقاف عند لحظة معيّنة من الحركة","مجموع قراءتي ساعة الإيقاف عند بداية الحركة وعند نهايتها","الزمن الذي تكون عنده قراءة ساعة الإيقاف صفرًا عند بدء التشغيل"]'::jsonb, 'تذكر', 'تذكر تعريف', 'سهل', 'الكتاب ص 36 — الفترة الزمنية والإزاحة'),
('mcq', 2, 'يبيّن الشكل الآتي قراءتي ساعة إيقاف عندما كان عدّاء عند الموقع 1 وعندما وصل إلى الموقع 2. أيّ العلاقات الآتية تعطي الفترة الزمنية التي استغرقها العدّاء للانتقال من الموقع 1 إلى الموقع 2؟', null, '[{"src":"qimg/phys1/c2l2-o11-stopwatches.svg","alt":"محور أفقي للموقع d بالمتر مدرّج من 0 إلى 30 كل 5. نقطة مرقمة 1 عند الموقع 5 m ونقطة مرقمة 2 عند الموقع 25 m. فوق النقطة 1 ساعة إيقاف رقمية تقرأ 2.0 s ومكتوب بجانبها t_i، وفوق النقطة 2 ساعة إيقاف رقمية تقرأ 7.5 s ومكتوب بجانبها t_f."}]'::jsonb, '["$\\Delta t = 7.5\\ \\text{s} + 2.0\\ \\text{s}$","$\\Delta t = 2.0\\ \\text{s} - 7.5\\ \\text{s}$","$\\Delta t = 7.5\\ \\text{s}$","$\\Delta t = 7.5\\ \\text{s} - 2.0\\ \\text{s}$"]'::jsonb, 'فهم', 'تفسير شكل', 'سهل', 'الكتاب ص 36 — الفترة الزمنية والإزاحة'),
('mcq', 3, 'أيّ العلاقات الآتية تعبّر عن الفترة الزمنية؟', null, null, '["$\\Delta t = t_i - t_f$","$\\Delta t = t_f - t_i$","$\\Delta t = t_f + t_i$","$\\Delta t = \\frac{t_f}{t_i}$"]'::jsonb, 'فهم', 'تمييز علاقة', 'متوسط', 'الكتاب ص 36 و53 — معادلة الفترة الزمنية'),
('mcq', 4, 'استعمل طالبان ساعتي إيقاف لقياس زمن حركة العدّاء نفسه بين شجرة وعمود إنارة، لكن كل واحد منهما شغّل ساعته في لحظة مختلفة. قرأت ساعة الطالب الأول 3.0 s عند الشجرة و7.0 s عند العمود، وقرأت ساعة الطالب الثاني 5.0 s عند الشجرة. ما قراءة ساعة الطالب الثاني عند العمود؟', null, null, '["7.0 s","4.0 s","9.0 s","12.0 s"]'::jsonb, 'تطبيق', 'تطبيق مفهوم', 'متوسط', 'الكتاب ص 36 — الفترة الزمنية والإزاحة'),
('mcq', 5, 'بدأ طالب تشغيل ساعة الإيقاف قبل أن يبدأ زميله الجري بقليل. أيّ العبارات الآتية صحيحة بشأن الفترة الزمنية لجري الزميل بين خطَّي البداية والنهاية؟', null, null, '["تساوي فرق قراءتي الساعة عند الخطين، ولا تتأثر بتشغيل الساعة مبكرًا","تساوي قراءة الساعة عند خط النهاية؛ لأنها تمثل الزمن الكلي للجري","لا يمكن تحديدها؛ لأن قراءة الساعة لم تكن صفرًا عند خط البداية","تساوي قراءة الساعة عند خط البداية مضافة إلى قراءتها عند خط النهاية"]'::jsonb, 'تحليل', 'تحليل موقف', 'صعب', 'الكتاب ص 36 — الفترة الزمنية والإزاحة'),
('mcq', 6, 'كيف يمكنك استعمال ساعة حائط لتعيين الفترة الزمنية التي تستغرقها حصة دراسية؟', null, null, '["تسجّل قراءة الساعة عند انتهاء الحصة فقط؛ فهي تمثل مدة الحصة","تجمع قراءة الساعة عند بدء الحصة إلى قراءتها عند انتهائها","تضبط ساعة الحائط على الصفر عند انتهاء الحصة ثم تقرأ ما تشير إليه","تسجّل قراءة الساعة عند بدء الحصة وعند انتهائها، ثم تطرح القراءة الأولى من الثانية"]'::jsonb, 'فهم', 'تطبيق مفهوم', 'متوسط', 'الكتاب ص 54 — تقويم الفصل 2 (إتقان المفاهيم، السؤال 38)'),
('mcq', 7, 'أيّ العبارات الآتية تعبّر عن فترة زمنية، لا عن لحظة زمنية؟', null, null, '["انطلق القطار من المحطة عندما كانت الساعة تشير إلى 9:00","كانت قراءة ساعة الإيقاف 5.0 s عندما وصل العدّاء إلى العمود","استغرق العدّاء 4.0 s ليصل من الشجرة إلى عمود الإنارة","رنّ الجرس معلنًا بدء الحصة الأولى عند الساعة 7:15"]'::jsonb, 'فهم', 'تمييز', 'سهل', 'الكتاب ص 36 — الفترة الزمنية والإزاحة'),
('essay', 1, 'وضّح المقصود بالفترة الزمنية، واكتب رمزها والعلاقة التي تُحسب بها مع بيان دلالة كل رمز، ثم أعطِ مثالًا عدديًّا: عدّاء كانت قراءة ساعة الإيقاف 1.5 s عندما مرّ بشجرة، و6.0 s عندما مرّ بعمود إنارة.', null, null, null, 'فهم', 'شرح مفهوم مع مثال', 'متوسط', 'الكتاب ص 36 — الفترة الزمنية والإزاحة'),
('essay', 2, 'تحرك قطار من محطة عندما كانت ساعة المحطة تشير إلى 10:15، ووصل إلى المحطة التالية عندما كانت ساعتها تشير إلى 10:40. وكانت ساعة أحد الركاب متأخرة 5 دقائق عن ساعتي المحطتين طوال الرحلة.
(أ) ما قراءتا ساعة الراكب عند الانطلاق وعند الوصول؟
(ب) احسب الفترة الزمنية للرحلة باستعمال ساعتي المحطتين، ثم باستعمال ساعة الراكب.
(ج) فسّر لماذا اختلفت القراءات ولم تختلف الفترة الزمنية.', null, null, null, 'تحليل', 'تحليل وتفسير', 'صعب', 'الكتاب ص 54 — تقويم الفصل 2 (إتقان المفاهيم، السؤال 38)'),
('essay', 3, 'وضّح الفرق بين الزمن $t$ والفترة الزمنية $\Delta t$ في وصف الحركة، ثم بيّن لماذا تكون الفترة الزمنية موجبة دائمًا عند حسابها بين بداية حركة ونهايتها.', null, null, null, 'فهم', 'مقارنة وتفسير', 'صعب', 'الكتاب ص 34 و36 — نقطة الأصل والفترة الزمنية')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
