select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 0, 'الفترة الزمنية هي الفرق بين زمنين، ويرمز لها بالرمز $\Delta t$، حيث $\Delta t = t_f - t_i$: الزمن النهائي مطروحًا منه الزمن الابتدائي.', '["","القراءة عند لحظة واحدة تحدد زمنًا (لحظة) لا فترة زمنية؛ فالفترة تحتاج إلى قراءتين يُطرح أولاهما من الأخرى.","الفترة الزمنية فرق بين الزمنين لا مجموعهما؛ والجمع يعطي قيمة لا معنى لها في وصف مدة الحركة.","هذا يصف لحظة بدء العدّ (نقطة الأصل للزمن) وليس الفترة الزمنية بين حدثين."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-18T12:34:59.221Z"}'::jsonb),
('mcq', 2, 3, 'الفترة الزمنية تساوي الزمن النهائي مطروحًا منه الزمن الابتدائي: $\Delta t = t_f - t_i = 7.5\ \text{s} - 2.0\ \text{s} = 5.5\ \text{s}$.', '["جمع القراءتين بدل طرحهما؛ الفترة الزمنية فرق بين زمنين.","عكس ترتيب الطرح فطرح الزمن النهائي من الابتدائي، فيصير الناتج سالبًا؛ والصحيح $t_f - t_i$.","أخذ القراءة النهائية وحدها، وكأن ساعة الإيقاف كانت تقرأ صفرًا عند الموقع 1، مع أنها كانت تقرأ 2.0 s.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-11-18T12:34:59.221Z"}'::jsonb),
('mcq', 3, 1, 'الفترة الزمنية هي الزمن النهائي $t_f$ مطروحًا منه الزمن الابتدائي $t_i$: $\Delta t = t_f - t_i$.', '["ترتيب الطرح معكوس؛ هذه العلاقة تعطي قيمة سالبة للفترة الزمنية.","","الفترة الزمنية فرق بين زمنين لا مجموعهما.","النسبة بين الزمنين عدد بلا وحدة، ولا تمثل مدة الحركة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-11-18T12:34:59.221Z"}'::jsonb),
('mcq', 4, 2, 'الفترة الزمنية بين الحدثين نفسيهما واحدة لا تعتمد على لحظة تشغيل الساعة: $\Delta t = 7.0\ \text{s} - 3.0\ \text{s} = 4.0\ \text{s}$؛ لذا تقرأ ساعة الطالب الثاني عند العمود $5.0\ \text{s} + 4.0\ \text{s} = 9.0\ \text{s}$.', '["افترض أن الساعتين تعطيان القراءة نفسها، مع أن ساعة الطالب الثاني متقدمة 2.0 s في كل لحظة.","هذه هي الفترة الزمنية نفسها لا قراءة الساعة عند العمود؛ يجب إضافتها إلى قراءته عند الشجرة.","","جمع قراءة الطالب الثاني عند الشجرة مع قراءة الطالب الأول عند العمود، وهما قراءتان لساعتين مختلفتين."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-11-18T12:34:59.221Z"}'::jsonb),
('mcq', 5, 0, 'الفترة الزمنية فرق بين زمنين: $\Delta t = t_f - t_i$، فيكفي تسجيل قراءة الساعة عند خط البداية وعند خط النهاية وطرحهما؛ وتشغيل الساعة مبكرًا يزيد القراءتين بالمقدار نفسه فلا يتغير الفرق.', '["","قراءة خط النهاية تتضمن الزمن الذي مضى قبل بدء الجري، فهي أكبر من الفترة الزمنية للجري.","لا يشترط أن تكون القراءة الابتدائية صفرًا؛ فالفترة الزمنية تُحسب من فرق أي قراءتين.","الفترة الزمنية فرق بين القراءتين لا مجموعهما."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-18T12:34:59.221Z"}'::jsonb),
('mcq', 6, 3, 'الفترة الزمنية هي الفرق بين زمنين؛ لذا تُسجّل قراءة ساعة الحائط عند بداية الحصة (الزمن الابتدائي) وعند نهايتها (الزمن النهائي)، ثم تُطرح القراءة الابتدائية من النهائية.', '["قراءة النهاية وحدها تحدد لحظة انتهاء الحصة لا مدتها.","جمع القراءتين لا يعطي مدة الحصة؛ المطلوب الفرق بينهما.","ضبط الساعة على الصفر عند النهاية لا يقيس شيئًا عن الحصة التي انتهت.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-18T12:34:59.221Z"}'::jsonb),
('mcq', 7, 2, 'الفترة الزمنية فرق بين زمنين، أي مدة استغرقها حدث بين لحظتين؛ و«استغرق 4.0 s من الشجرة إلى العمود» مدة بين لحظة وجوده عند الشجرة ولحظة وصوله إلى العمود.', '["هذه قراءة ساعة عند لحظة الانطلاق، أي زمن واحد لا فرق بين زمنين.","هذه قراءة ساعة الإيقاف عند لحظة الوصول، وهي زمن نهائي واحد لا فترة زمنية.","","هذا وقت حدوث حدث واحد (لحظة)، لا مدة بين لحظتين."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-11-18T12:34:59.222Z"}'::jsonb),
('essay', 1, null::int, null, null, 'الفترة الزمنية هي الفرق بين زمنين، ويرمز لها بالرمز $\Delta t$، وتُحسب بالعلاقة $\Delta t = t_f - t_i$؛ حيث $t_f$ الزمن النهائي (قراءة الساعة عند نهاية الحركة المدروسة)، و$t_i$ الزمن الابتدائي (قراءتها عند بدايتها). مثال: $\Delta t = 6.0\ \text{s} - 1.5\ \text{s} = 4.5\ \text{s}$، وهي المدة التي استغرقها العدّاء للانتقال من الشجرة إلى العمود.', '["الفترة الزمنية فرق بين زمنين","الرمز $\\Delta t$","العلاقة $\\Delta t = t_f - t_i$ ودلالة $t_f$ و$t_i$","التطبيق العددي: $\\Delta t = 4.5\\ \\text{s}$"]'::jsonb, '["$t_i = 1.5\\ \\text{s}$، $t_f = 6.0\\ \\text{s}$","$\\Delta t = t_f - t_i = 6.0\\ \\text{s} - 1.5\\ \\text{s}$","$\\Delta t = 4.5\\ \\text{s}$"]'::jsonb, '[{"element":"المفهوم","marks":1},{"element":"الرمز والعلاقة ودلالة الرموز","marks":1},{"element":"التطبيق العددي","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"مفهوم صحيح وعلاقة صحيحة مع دلالة الرموز وناتج التطبيق العددي 4.5 s"},{"level":"2 درجتان","description":"المفهوم والعلاقة صحيحان مع خطأ في التطبيق العددي أو العكس"},{"level":"1 درجة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تعريف الفترة الزمنية بأنها قراءة الساعة عند لحظة","كتابة $t_i - t_f$ فيصير الناتج سالبًا","إغفال وحدة الثانية في الناتج"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-11-18T12:34:59.222Z"}'::jsonb),
('essay', 2, null::int, null, null, 'قراءتا ساعة الراكب 10:10 عند الانطلاق و10:35 عند الوصول. الفترة الزمنية من ساعتي المحطتين: 10:40 − 10:15 = 25 min، ومن ساعة الراكب: 10:35 − 10:10 = 25 min. القراءات تختلف لأن كل ساعة تحدد اللحظة بالنسبة إلى ضبطها الخاص، لكن الفترة الزمنية فرق بين زمنين، وتأخر الساعة بمقدار ثابت ينقص القراءتين بالمقدار نفسه فيلغى عند الطرح.', '["قراءتا الراكب 10:10 و10:35","الفترة 25 min من ساعتي المحطتين","الفترة 25 min من ساعة الراكب","التفسير: التأخر الثابت يُلغى عند الطرح"]'::jsonb, '["ساعتا المحطتين: $\\Delta t = 10{:}40 - 10{:}15 = 25\\ \\text{min}$","ساعة الراكب: 10:10 و10:35، $\\Delta t = 25\\ \\text{min}$","المقارنة: الفترتان متساويتان"]'::jsonb, '[{"element":"قراءتا ساعة الراكب","marks":1},{"element":"حساب الفترة الزمنية بالطريقتين","marks":2},{"element":"التفسير","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"القراءتان صحيحتان والحسابان صحيحان مع تفسير يربط بين الفترة والفرق بين زمنين"},{"level":"2–3 درجات","description":"حسابات صحيحة مع تفسير ناقص، أو تفسير صحيح مع خطأ حسابي"},{"level":"1 درجة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["الاعتقاد أن الساعة المتأخرة تعطي فترة زمنية أقصر","إضافة 5 دقائق إلى قراءات الراكب بدل طرحها","الخلط بين قراءة الساعة (لحظة) والفترة الزمنية"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-11-18T12:34:59.222Z"}'::jsonb),
('essay', 3, null::int, null, null, 'الزمن $t$ قراءة الساعة عند لحظة معيّنة، أي يحدد متى وقع حدث ما، وتتوقف قيمته على اللحظة التي بدأ عندها العدّ (نقطة الأصل للزمن). أما الفترة الزمنية $\Delta t = t_f - t_i$ فهي الفرق بين زمنين، وتعبّر عن المدة التي استغرقها الحدث، ولا تتوقف على لحظة بدء العدّ. وتكون موجبة لأن الزمن النهائي $t_f$ يقع بعد الزمن الابتدائي $t_i$ فقراءته أكبر، فيكون ناتج طرح الأصغر من الأكبر موجبًا.', '["الزمن قراءة عند لحظة","الفترة الزمنية فرق بين زمنين (مدة)","الفترة لا تتوقف على لحظة بدء العدّ","$t_f > t_i$ فتكون $\\Delta t$ موجبة"]'::jsonb, '[]'::jsonb, '[{"element":"معنى الزمن","marks":1},{"element":"معنى الفترة الزمنية","marks":1},{"element":"عدم توقفها على بدء العدّ","marks":1},{"element":"تفسير كونها موجبة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"جميع العناصر صحيحة ومترابطة"},{"level":"2–3 درجات","description":"التمييز صحيح مع نقص في التفسير"},{"level":"1 درجة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["اعتبار الزمن والفترة الزمنية الشيء نفسه","تبرير الإشارة الموجبة بأن الزمن لا يكون سالبًا، مع أن الإشارة ناتجة عن ترتيب اللحظتين"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-11-18T12:34:59.222Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
