select (select id from public.objectives where code = 'P1-C2-L2-O12'), v.type, v.number, v.stem, v.stimulus::jsonb, v.images::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'سجّلت ساعتا إيقاف متماثلتان، شُغّلتا معًا، الزمن الذي مرّ عنده متسابق بخط البداية والزمن الذي وصل عنده إلى خط النهاية، كما في الشكل الآتي. ما الفترة الزمنية لحركة المتسابق بين الخطين؟', null, '[{"src":"qimg/phys1/c2l2-o12-stopwatch.svg","alt":"ساعتا إيقاف رقميتان: اليسرى تقرأ 3.4 s ومكتوب تحتها «عند خط البداية»، واليمنى تقرأ 9.1 s ومكتوب تحتها «عند خط النهاية»، وبينهما سهم يشير من اليسرى إلى اليمنى."}]'::jsonb, '["$12.5\\ \\text{s}$","$-5.7\\ \\text{s}$","$5.7\\ \\text{s}$","$9.1\\ \\text{s}$"]'::jsonb, 'تطبيق', 'حساب', 'سهل', 'الكتاب ص 36 — الفترة الزمنية والإزاحة'),
('mcq', 2, 'يمثّل الشكل الآتي نموذج الجسيم النقطي لحركة جسم، والفترة الزمنية بين كل نقطتين متتاليتين 0.5 s. ما الفترة الزمنية التي استغرقها الجسم للانتقال من النقطة A إلى النقطة B؟', null, '[{"src":"qimg/phys1/c2l2-o12-dots.svg","alt":"ثماني نقاط على خط أفقي تتزايد المسافات بينها من اليسار إلى اليمين. النقطة الثانية من اليسار مكتوب فوقها A، والنقطة السابعة من اليسار مكتوب فوقها B. وفي الأسفل سهم نحو اليمين مكتوب بجانبه «اتجاه الحركة»."}]'::jsonb, '["2.5 s","3.0 s","2.0 s","5.0 s"]'::jsonb, 'تطبيق', 'حساب من شكل', 'متوسط', 'الكتاب ص 36 والتقويم ص 55 (السؤال 50) — الفترة الزمنية في نموذج الجسيم النقطي'),
('mcq', 3, 'يمثّل المنحنى الآتي (الموقع – الزمن) لحركة قرص هوكي على الجليد. ما الفترة الزمنية التي استغرقها القرص للانتقال من الموقع 60 m إلى الموقع 120 m؟', null, '[{"src":"qimg/phys1/c2l2-o12-graph.svg","alt":"منحنى (الموقع – الزمن): المحور الأفقي الزمن (s) من 0 إلى 7 بخطوة 1، والمحور الرأسي الموقع (m) من 0 إلى 140 بخطوة 20، مع شبكة. خط مستقيم أخضر يبدأ من النقطة (0، 0) ويمر بالنقاط (1، 20) و(2، 40) و(3، 60) و(4، 80) و(5، 100) و(6، 120) وينتهي عند (7، 140)."}]'::jsonb, '["6.0 s","60 s","9.0 s","3.0 s"]'::jsonb, 'تطبيق', 'قراءة منحنى', 'متوسط', 'الكتاب ص 42 — مراجعة 2-3 (السؤال 23 الفترة الزمنية)'),
('mcq', 4, 'بدأ سباق عندما كانت ساعة الملعب تشير إلى 10:12:20، وانتهى عندما أشارت إلى 10:15:50 (الساعة:الدقيقة:الثانية). ما الفترة الزمنية للسباق بالثواني؟', null, null, '["330 s","210 s","180 s","30 s"]'::jsonb, 'تطبيق', 'حساب مع تحويل وحدات', 'سهل', 'الكتاب ص 54 — تقويم الفصل 2 (إتقان المفاهيم، السؤال 38)'),
('mcq', 5, 'شُغّلت ساعة إيقاف قبل انطلاق عدّاء بـ 2.0 s. وعندما مرّ العدّاء بعلامة 10 m كانت قراءتها 4.5 s، وعندما مرّ بعلامة 40 m كانت قراءتها 9.5 s. ما الفترة الزمنية التي استغرقها العدّاء للانتقال من العلامة الأولى إلى الثانية؟', null, null, '["7.5 s","5.0 s","14.0 s","3.0 s"]'::jsonb, 'تطبيق', 'حساب مع معطيات زائدة', 'صعب', 'الكتاب ص 36 — الفترة الزمنية والإزاحة'),
('mcq', 6, 'بدأت تجربة عندما كانت قراءة ساعة الإيقاف 1.25 min، وانتهت عندما كانت قراءتها 3.50 min. ما الفترة الزمنية للتجربة بالثواني؟', null, null, '["135 s","2.25 s","225 s","285 s"]'::jsonb, 'تطبيق', 'حساب مع تحويل وحدات', 'متوسط', 'الكتاب ص 36 — الفترة الزمنية والإزاحة'),
('mcq', 7, 'كانت قراءة ساعة الإيقاف 12.6 s عندما بدأت سيارة لعبة حركتها، واستغرقت الحركة فترة زمنية مقدارها 4.8 s. ما قراءة الساعة عند نهاية الحركة؟', null, null, '["7.8 s","4.8 s","12.6 s","17.4 s"]'::jsonb, 'تطبيق', 'حساب عكسي', 'سهل', 'الكتاب ص 36 — الفترة الزمنية والإزاحة'),
('essay', 1, 'سُجّلت قراءات ساعة إيقاف عندما مرّ عدّاء بعلامات على مضمار مستقيم كما في الجدول. احسب الفترة الزمنية لكل مرحلة من المراحل الثلاث، والفترة الزمنية الكلية من العلامة 0 m إلى العلامة 30 m، وحدّد المرحلة التي استغرقت أقصر فترة زمنية.', '{"headers":["العلامة (m)","قراءة الساعة (s)"],"rows":[["0","0.8"],["10","2.6"],["20","4.2"],["30","5.9"]]}'::jsonb, null, null, 'تطبيق', 'حساب من جدول', 'متوسط', 'الكتاب ص 36 — الفترة الزمنية والإزاحة'),
('essay', 2, 'غادرت حافلة محطة عندما كانت ساعة الحائط تشير إلى 7:48:30، ووصلت إلى المحطة التالية عندما كانت تشير إلى 8:06:15 (الساعة:الدقيقة:الثانية). احسب الفترة الزمنية للرحلة بالدقائق والثواني، ثم بالثواني فقط، موضحًا خطوات الحل.', null, null, null, 'تطبيق', 'حساب متعدد الخطوات', 'صعب', 'الكتاب ص 54 — تقويم الفصل 2 (إتقان المفاهيم، السؤال 38)'),
('essay', 3, 'أراد طالبان قياس الفترة الزمنية لجري زميلهما بين خطَّي البداية والنهاية. شغّل الطالب الأول ساعته لحظة انطلاق الزميل وأوقفها عند خط النهاية فقرأت 6.4 s. أما الطالب الثاني فقد شغّل ساعته متأخرًا 1.5 s بعد الانطلاق، وأوقفها عند خط النهاية، ثم كتب أن الفترة الزمنية تساوي قراءة ساعته.
(أ) ما قراءة ساعة الطالب الثاني عند خط النهاية؟
(ب) أيّ الطالبين حصل على الفترة الزمنية الصحيحة؟ ولماذا؟
(ج) اقترح طريقة يحصل بها أيّ شخص على الفترة الزمنية الصحيحة حتى لو لم يشغّل ساعته لحظة الانطلاق.', null, null, null, 'تحليل', 'تحليل وتقويم', 'صعب', 'الكتاب ص 36 — الفترة الزمنية والإزاحة')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
