from (values
('mcq', 1, 2, '$\Delta t = t_f - t_i = 9.1\ \text{s} - 3.4\ \text{s} = 5.7\ \text{s}$.', '["جمع القراءتين بدل طرحهما.","طرح الزمن النهائي من الابتدائي ($t_i - t_f$) فظهرت إشارة سالبة.","","أخذ قراءة خط النهاية وحدها وأهمل أن الساعة كانت تقرأ 3.4 s عند خط البداية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-11-18T12:34:59.223Z"}'::jsonb),
('mcq', 2, 0, 'بين A وB خمس فترات زمنية متتالية (A هي النقطة الثانية وB هي السابعة)، فتكون $\Delta t = 5 \times 0.5\ \text{s} = 2.5\ \text{s}$؛ وتباعد النقاط لا يؤثر لأن الفترات الزمنية بينها متساوية.', '["","عدّ النقاط من A إلى B (ست نقاط) بدل عدّ الفترات بينها (خمس فترات).","عدّ النقاط الواقعة بين A وB فقط (أربع نقاط) فأسقط فترة.","عدّ الفترات الخمس صحيحًا لكنه عدّ كل فترة ثانية واحدة بدل 0.5 s."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (28%)"}],"at":"2026-11-18T12:34:59.223Z"}'::jsonb),
('mcq', 3, 3, 'من المنحنى: يكون القرص عند 60 m عند الزمن 3.0 s، وعند 120 m عند الزمن 6.0 s، فتكون $\Delta t = 6.0\ \text{s} - 3.0\ \text{s} = 3.0\ \text{s}$.', '["هذا زمن وصول القرص إلى 120 m مقيسًا من الصفر، وليس الفترة بين الموقعين.","هذه الإزاحة 60 m بين الموقعين، فخلط بين محور الموقع ومحور الزمن.","جمع الزمنين 3.0 s و6.0 s بدل طرحهما.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (28%)"}],"at":"2026-11-18T12:34:59.223Z"}'::jsonb),
('mcq', 4, 1, 'الفرق بين القراءتين 3 min و30 s، و$\Delta t = 3 \times 60\ \text{s} + 30\ \text{s} = 210\ \text{s}$.', '["كتب «3 دقائق و30 ثانية» على صورة العدد 330 كأنها ثوانٍ، ونسي أن الدقيقة 60 s.","","طرح الدقائق فقط (15 − 12 = 3 min) وأهمل فرق الثواني.","طرح الثواني فقط (50 − 20) وأهمل فرق الدقائق."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (28%)"}],"at":"2026-11-18T12:34:59.224Z"}'::jsonb),
('mcq', 5, 1, 'الفترة الزمنية بين المرورين هي فرق قراءتي الساعة عندهما: $\Delta t = 9.5\ \text{s} - 4.5\ \text{s} = 5.0\ \text{s}$؛ وتشغيل الساعة مبكرًا لا يؤثر في الفرق.', '["طرح 2.0 s من القراءة النهائية، مع أن المطلوب الفترة بين العلامتين لا بين الانطلاق والعلامة الثانية.","","جمع القراءتين بدل طرحهما.","طرح 2.0 s من الفرق الصحيح ظنًّا أن التشغيل المبكر يؤثر في الفترة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-11-18T12:34:59.224Z"}'::jsonb),
('mcq', 6, 0, '$\Delta t = 3.50\ \text{min} - 1.25\ \text{min} = 2.25\ \text{min}$، وبالتحويل: $2.25 \times 60\ \text{s} = 135\ \text{s}$.', '["","حسب الفرق صحيحًا بالدقائق لكنه لم يحوّله إلى ثوانٍ.","ضرب في 100 بدل 60 عند التحويل من الدقائق إلى الثواني.","جمع القراءتين (4.75 min) ثم حوّل الناتج، والمطلوب الفرق."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-11-18T12:34:59.224Z"}'::jsonb),
('mcq', 7, 3, 'من العلاقة $\Delta t = t_f - t_i$ نجد $t_f = t_i + \Delta t = 12.6\ \text{s} + 4.8\ \text{s} = 17.4\ \text{s}$.', '["طرح الفترة من القراءة الابتدائية، مع أن القراءة النهائية تقع بعد الابتدائية فتكون أكبر.","خلط بين الفترة الزمنية وقراءة الساعة النهائية.","هذه القراءة الابتدائية نفسها، والساعة استمرت في العدّ خلال الحركة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-11-18T12:34:59.224Z"}'::jsonb),
('essay', 1, null::int, null, null, 'المرحلة الأولى (0 m إلى 10 m): $\Delta t = 2.6\ \text{s} - 0.8\ \text{s} = 1.8\ \text{s}$. المرحلة الثانية (10 m إلى 20 m): $\Delta t = 4.2\ \text{s} - 2.6\ \text{s} = 1.6\ \text{s}$. المرحلة الثالثة (20 m إلى 30 m): $\Delta t = 5.9\ \text{s} - 4.2\ \text{s} = 1.7\ \text{s}$. الفترة الكلية: $\Delta t = 5.9\ \text{s} - 0.8\ \text{s} = 5.1\ \text{s}$ (وتساوي مجموع الفترات الثلاث). أقصر فترة للمرحلة الثانية.', '["1.8 s للمرحلة الأولى","1.6 s للمرحلة الثانية","1.7 s للمرحلة الثالثة","الفترة الكلية 5.1 s","أقصرها المرحلة الثانية"]'::jsonb, '["$\\Delta t_1 = 2.6 - 0.8 = 1.8\\ \\text{s}$","$\\Delta t_2 = 4.2 - 2.6 = 1.6\\ \\text{s}$","$\\Delta t_3 = 5.9 - 4.2 = 1.7\\ \\text{s}$","$\\Delta t = 5.9 - 0.8 = 5.1\\ \\text{s}$","المقارنة: 1.6 s هي الأصغر"]'::jsonb, '[{"element":"فترات المراحل الثلاث","marks":3},{"element":"الفترة الكلية","marks":1},{"element":"تحديد المرحلة الأقصر","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"جميع الحسابات صحيحة مع تحديد المرحلة الأقصر"},{"level":"3–4 درجات","description":"خطأ حسابي واحد أو إغفال المقارنة"},{"level":"1–2 درجة","description":"حساب فترة أو فترتين صحيحًا فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["حساب الفترة الكلية من 0 s بدل 0.8 s فيكون الناتج 5.9 s","جمع القراءات بدل طرحها","اعتبار قراءة كل علامة فترة زمنية للمرحلة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-11-18T12:34:59.224Z"}'::jsonb),
('essay', 2, null::int, null, null, 'نحوّل القراءتين إلى ثوانٍ بدءًا من الساعة 7:00: القراءة الأولى $48 \times 60 + 30 = 2910\ \text{s}$، والثانية $66 \times 60 + 15 = 3975\ \text{s}$ (لأن 8:06:15 تعني 66 min و15 s بعد 7:00). $\Delta t = 3975\ \text{s} - 2910\ \text{s} = 1065\ \text{s}$، أي 17 min و45 s.', '["تحويل القراءتين إلى وحدة واحدة","$\\Delta t = t_f - t_i$","1065 s","17 min و45 s"]'::jsonb, '["$t_i = 48 \\times 60 + 30 = 2910\\ \\text{s}$ بعد 7:00","$t_f = 66 \\times 60 + 15 = 3975\\ \\text{s}$ بعد 7:00","$\\Delta t = 3975 - 2910 = 1065\\ \\text{s}$","1065 s = 17 min + 45 s"]'::jsonb, '[{"element":"التحويل الصحيح للقراءتين","marks":1},{"element":"تطبيق علاقة الفترة الزمنية","marks":1},{"element":"الناتج بالثواني","marks":1},{"element":"الناتج بالدقائق والثواني","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"خطوات وناتجان صحيحان"},{"level":"2–3 درجات","description":"طريقة صحيحة مع خطأ في الاستلاف أو التحويل"},{"level":"1 درجة","description":"كتابة العلاقة فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["طرح 48 من 06 مباشرة دون مراعاة تغيّر الساعة","اعتبار الدقيقة 100 s","إهمال فرق الثواني"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (28%)"}],"at":"2026-11-18T12:34:59.224Z"}'::jsonb),
('essay', 3, null::int, null, null, '(أ) قراءته $6.4\ \text{s} - 1.5\ \text{s} = 4.9\ \text{s}$. (ب) الطالب الأول؛ لأن ساعته كانت تقرأ صفرًا لحظة الانطلاق، فقراءتها النهائية تساوي $\Delta t = t_f - t_i = 6.4\ \text{s} - 0 = 6.4\ \text{s}$. أما الثاني فساعته لم تكن تعمل لحظة الانطلاق، فلم يسجّل الزمن الابتدائي، وقراءته 4.9 s أقل من الفترة الحقيقية. (ج) تُشغَّل الساعة في أي وقت قبل الانطلاق، وتُسجّل قراءتها لحظة الانطلاق $t_i$ ولحظة الوصول $t_f$، ثم تُحسب $\Delta t = t_f - t_i$.', '["قراءة الطالب الثاني 4.9 s","الطالب الأول هو الصحيح (6.4 s)","التعليل: الثاني لم يسجّل الزمن الابتدائي","الطريقة: تسجيل $t_i$ و$t_f$ على ساعة تعمل وطرحهما"]'::jsonb, '["$4.9 = 6.4 - 1.5$","$\\Delta t = 6.4 - 0 = 6.4\\ \\text{s}$"]'::jsonb, '[{"element":"حساب قراءة الطالب الثاني","marks":1},{"element":"تحديد الصحيح مع التعليل","marks":2},{"element":"الطريقة المقترحة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"جميع العناصر صحيحة مع تعليل واضح"},{"level":"2–3 درجات","description":"التحديد صحيح مع نقص في التعليل أو الطريقة"},{"level":"1 درجة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["الاعتقاد أن قراءة الساعة النهائية هي الفترة الزمنية دائمًا","إضافة 1.5 s بدل طرحها في (أ)","اشتراط أن تبدأ الساعة من الصفر لقياس أي فترة زمنية"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-11-18T12:34:59.225Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
