insert into public.questions (objective_id, type, number, stem, stimulus, images, options, thinking_level, question_kind, difficulty, source_ref, status, origin)
select (select id from public.objectives where code = 'P1-C2-L2-O13'), v.type, v.number, v.stem, v.stimulus::jsonb, v.images::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'أيّ العبارات الآتية تبيّن الفرق بين الإزاحة والمسافة بصورة صحيحة؟', null, null, '["الإزاحة كمية قياسية تعبّر عن طول المسار كله، والمسافة كمية متجهة تعبّر عن التغير في الموقع","الإزاحة كمية متجهة تعبّر عن المقدار والاتجاه، والمسافة كمية قياسية لا اتجاه لها","الإزاحة والمسافة كميتان متجهتان، لكن الإزاحة تقاس بالمتر والمسافة بالكيلومتر","الإزاحة والمسافة كميتان قياسيتان، والفرق بينهما في طريقة القياس فقط"]'::jsonb, 'فهم', 'مقارنة', 'سهل', 'الكتاب ص 36 — الإزاحة والمسافة'),
('mcq', 2, 'يبيّن الشكل الآتي مسار جسم تحرك على خط مستقيم من موقع البداية إلى الموقع 9 m، ثم عاد إلى موقع النهاية. أيّ العبارات الآتية تصف العلاقة بين المسافة التي قطعها ومقدار إزاحته؟', null, '[{"src":"qimg/phys1/c2l2-o13-backforth.svg","alt":"محور أفقي للموقع d بالمتر مدرّج من 0 إلى 10 كل 1 m. نقطة مكتوب فوقها «البداية» عند 2 m، ونقطة مكتوب فوقها «النهاية» عند 5 m، ونقطة عند 9 m. فوق المحور سهم أسود من 2 m إلى 9 m، وفوقه سهم أسود ثانٍ من 9 m يعود إلى 5 m، يمثلان مسار الجسم."}]'::jsonb, '["مقدار الإزاحة أكبر من المسافة؛ لأن الإزاحة تحسب الذهاب والعودة معًا","المسافة تساوي مقدار الإزاحة؛ لأن الحركة كلها كانت على خط مستقيم واحد","المسافة ومقدار الإزاحة كلاهما صفر؛ لأن الجسم عاد في عكس اتجاه حركته","المسافة أكبر من مقدار الإزاحة؛ لأن الجسم عاد جزءًا من طريقه"]'::jsonb, 'تحليل', 'تحليل شكل', 'متوسط', 'الكتاب ص 36 — الإزاحة والمسافة'),
('mcq', 3, 'يبيّن الشكل الآتي مضمارًا محيطه 400 m، ركض عليه عدّاء دورة كاملة واحدة، فبدأ وانتهى عند النقطة نفسها. أيّ مما يأتي يصف المسافة التي قطعها العدّاء وإزاحته؟', null, '[{"src":"qimg/phys1/c2l2-o13-track.svg","alt":"مضمار جري بيضاوي الشكل، عليه نقطة حمراء في أسفله مكتوب تحتها «البداية والنهاية»، وسهم على الجزء الأيمن العلوي من المضمار يبيّن اتجاه الجري حول المضمار."}]'::jsonb, '["المسافة 400 m، والإزاحة صفر","المسافة صفر، والإزاحة 400 m","المسافة والإزاحة كلتاهما 400 m","المسافة والإزاحة كلتاهما صفر"]'::jsonb, 'تحليل', 'تحليل شكل', 'صعب', 'الكتاب ص 36 — الإزاحة والمسافة'),
('mcq', 4, 'متى يتساوى مقدار إزاحة جسم متحرك مع المسافة التي قطعها؟', null, null, '["عندما يتحرك ذهابًا وإيابًا على خط مستقيم واحد","عندما يعود في نهاية حركته إلى موقع البداية","عندما يتحرك في خط مستقيم باتجاه واحد","عندما يتحرك على مسار دائري بسرعة ثابتة"]'::jsonb, 'فهم', 'شرط', 'سهل', 'الكتاب ص 36 — الإزاحة والمسافة'),
('mcq', 5, 'أيّ العبارات الآتية تصف إزاحة، لا مسافة؟', null, null, '["قطع العدّاء 100 m خلال تدريبه الصباحي","عدّاد السيارة يبيّن أنها قطعت 35 km في الرحلة","طول المسار الذي سلكه المتسابق في المتاهة 2.5 m","تحرك العدّاء 100 m في اتجاه الشرق من خط البداية"]'::jsonb, 'فهم', 'تصنيف', 'سهل', 'الكتاب ص 36 — الإزاحة والمسافة'),
('mcq', 6, 'هل يمكن أن يكون مقدار إزاحة جسم أكبر من المسافة التي قطعها في الحركة نفسها؟', null, null, '["نعم؛ إذا تحرك الجسم في خط مستقيم في اتجاه واحد","لا؛ فهو أصغر من المسافة أو يساويها دائمًا","نعم؛ إذا عاد الجسم في نهاية حركته إلى موقع البداية","لا؛ فمقدار الإزاحة يساوي المسافة دائمًا في أي حركة"]'::jsonb, 'تحليل', 'استدلال', 'صعب', 'الكتاب ص 36 — الإزاحة والمسافة'),
('mcq', 7, 'قاد سائق سيارته من مرآب منزله 30 km إلى مدينة مجاورة، ثم عاد بالطريق نفسه إلى المرآب. قال أحد الطلاب: «إزاحة السيارة 60 km». ما تقويمك لهذه العبارة؟', null, null, '["غير صحيحة؛ فهذه هي المسافة، أما الإزاحة فصفر","صحيحة؛ لأن الإزاحة تساوي مجموع ما قطعته السيارة ذهابًا وإيابًا","غير صحيحة؛ فالإزاحة 30 km لأنها تُحسب للذهاب فقط","صحيحة؛ لأن المسافة والإزاحة متساويتان في أي رحلة بالسيارة"]'::jsonb, 'تقويم', 'تقويم عبارة', 'متوسط', 'الكتاب ص 36 — الإزاحة والمسافة'),
('essay', 1, 'وضّح الفرق بين كلٍّ من: الموقع، والمسافة، والإزاحة، مستعينًا بمثال عدّاء انطلق من الموقع 5.0 m على محور الموقع، وركض إلى الموقع 25.0 m، ثم عاد إلى الموقع 15.0 m.', null, null, null, 'تحليل', 'مقارنة مع مثال', 'متوسط', 'الكتاب ص 54 — تقويم الفصل 2 (السؤال 37)'),
('essay', 2, 'تحركت حافلة على طريق مستقيم من محطة 5.0 km شرقًا، ثم عادت 2.0 km غربًا لتقف عند موقف آخر.
(أ) ما المسافة التي قطعتها الحافلة؟ وما إزاحتها؟
(ب) يحسب عدّاد الحافلة أجرة الوقود بناءً على ما قطعته، بينما يرسم المخطط على الخريطة سهمًا من المحطة إلى الموقف. أيّ الكميتين يعتمد عليها كلٌّ منهما؟ فسّر.', null, null, null, 'تحليل', 'تطبيق وتفسير', 'متوسط', 'الكتاب ص 36 — الإزاحة والمسافة'),
('essay', 3, 'خرج صديقان من باب المدرسة إلى باب المكتبة المقابلة لها. سار الأول في ممر مستقيم طوله 300 m، وسار الثاني في شوارع متعرجة طولها 450 m. قارن بين المسافة التي قطعها كلٌّ منهما وإزاحته، وقوّم قول أحدهما: «إزاحتي أكبر لأنني مشيت أكثر».', null, null, null, 'تقويم', 'مقارنة وتقويم', 'صعب', 'الكتاب ص 36 — الإزاحة والمسافة')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
