select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 1, 'الإزاحة كمية متجهة تمثل التغير في موقع الجسم في اتجاه معيّن، فتعبّر عن المقدار والاتجاه؛ أما المسافة فكمية قياسية تعبّر عن كل ما يقطعه الجسم دون تحديد الاتجاه.', '["عكس صفتي الكميتين: المسافة هي القياسية والإزاحة هي المتجهة.","","المسافة كمية قياسية، وكلتاهما تقاس بوحدة الطول نفسها في النظام الدولي (m).","الإزاحة كمية متجهة لها اتجاه، والفرق بينهما في نوع الكمية لا في طريقة القياس."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-11-18T12:34:59.225Z"}'::jsonb),
('mcq', 2, 3, 'المسافة تشمل كل ما قطعه الجسم: 7 m ذهابًا و4 m عودة، أي 11 m؛ أما الإزاحة فتعتمد على موقعي البداية والنهاية فقط: من 2 m إلى 5 m، أي 3 m. فالمسافة أكبر لأن الجسم عاد جزءًا من طريقه.', '["الإزاحة لا تجمع أجزاء المسار؛ بل تعتمد على موقعي البداية والنهاية فقط، لذا لا تزيد على المسافة.","الحركة على خط مستقيم لا تكفي للتساوي؛ يلزم أن تكون في اتجاه واحد دون عودة.","الجسم لم يعد إلى موقع البداية، فإزاحته ليست صفرًا، والمسافة لا تكون صفرًا لجسم تحرك.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-18T12:34:59.225Z"}'::jsonb),
('mcq', 3, 0, 'المسافة كل ما قطعه العدّاء على المسار، وهي محيط المضمار 400 m؛ أما الإزاحة فهي التغير في الموقع من البداية إلى النهاية، وبما أنهما النقطة نفسها فالإزاحة صفر.', '["","عكس الكميتين: المسافة لا تكون صفرًا لجسم تحرك، والإزاحة هي التي تنعدم عند العودة إلى نقطة البداية.","الإزاحة لا تساوي طول المسار هنا؛ لأن موقعي البداية والنهاية متطابقان.","العدّاء قطع مسارًا طوله 400 m، فالمسافة ليست صفرًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-18T12:34:59.225Z"}'::jsonb),
('mcq', 4, 2, 'تتساوى المسافة مع مقدار الإزاحة إذا كان كل ما قطعه الجسم في الاتجاه نفسه من موقع البداية إلى موقع النهاية، أي في خط مستقيم دون تغيير اتجاه.', '["في الذهاب والإياب تُحسب العودة ضمن المسافة لكنها تُنقص الإزاحة، فتكون المسافة أكبر.","عند العودة إلى البداية تكون الإزاحة صفرًا بينما المسافة لا تساوي صفرًا.","","على المسار الدائري يكون طول المسار أكبر من الخط الواصل بين البداية والنهاية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (38%)"}],"at":"2026-11-18T12:34:59.226Z"}'::jsonb),
('mcq', 5, 3, 'الإزاحة كمية متجهة تتطلب المقدار والاتجاه بالنسبة إلى نقطة إسناد؛ و«100 m في اتجاه الشرق من خط البداية» تحدد المقدار والاتجاه معًا.', '["ذُكر المقدار فقط دون اتجاه، فهذه مسافة.","العدّاد يقيس كل ما قطعته السيارة دون اتجاه، فهذه مسافة.","طول المسار كله دون اتجاه هو مسافة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-11-18T12:34:59.226Z"}'::jsonb),
('mcq', 6, 1, 'الإزاحة تمثل التغير في الموقع بين البداية والنهاية، وهو أقصر طريق بينهما، أما المسافة فتشمل كل ما قطعه الجسم؛ لذا يساوي مقدار الإزاحة المسافة في حالة الحركة في خط مستقيم باتجاه واحد، ويكون أصغر منها في أي حالة أخرى، ولا يكون أكبر منها.', '["في هذه الحالة يتساوى المقداران، ولا يزيد مقدار الإزاحة على المسافة.","","عند العودة إلى البداية تكون الإزاحة صفرًا، أي أصغر ما يمكن.","يتساويان فقط في الحركة في خط مستقيم باتجاه واحد، وتكون المسافة أكبر في الحركات الأخرى."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (38%)"}],"at":"2026-11-18T12:34:59.226Z"}'::jsonb),
('mcq', 7, 0, 'الإزاحة التغير في الموقع، وموقعا البداية والنهاية هما المرآب نفسه، فالإزاحة صفر؛ والرقم 60 km هو المسافة التي قطعتها السيارة دون تحديد اتجاه.', '["","هذا وصف المسافة لا الإزاحة؛ فالإزاحة لا تجمع أجزاء المسار.","الإزاحة تُحسب بين موقع البداية وموقع النهاية للحركة كلها، لا لجزء منها.","المسافة والإزاحة لا تتساويان إلا في الحركة في خط مستقيم باتجاه واحد."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (5%)"}],"at":"2026-11-18T12:34:59.226Z"}'::jsonb),
('essay', 1, null::int, null, null, 'الموقع متجه ذيله عند نقطة الأصل ورأسه عند مكان الجسم، ويحدد بُعد الجسم واتجاهه عن نقطة الأصل في لحظة معيّنة؛ فموقع العدّاء الابتدائي $\boldsymbol{d}_i = 5.0\ \text{m}$ والنهائي $\boldsymbol{d}_f = 15.0\ \text{m}$. المسافة كمية قياسية تمثل كل ما قطعه الجسم دون اتجاه: $20.0\ \text{m} + 10.0\ \text{m} = 30.0\ \text{m}$. الإزاحة كمية متجهة تمثل التغير في الموقع: $\Delta\boldsymbol{d} = \boldsymbol{d}_f - \boldsymbol{d}_i = 15.0\ \text{m} - 5.0\ \text{m} = +10.0\ \text{m}$، أي 10.0 m في الاتجاه الموجب. فالموقع يصف مكانًا في لحظة، والمسافة تصف طول المسار، والإزاحة تصف التغير بين موقعين بالمقدار والاتجاه.', '["الموقع: متجه من نقطة الأصل إلى الجسم في لحظة","المسافة: كمية قياسية لكل ما قُطع (30.0 m)","الإزاحة: كمية متجهة للتغير في الموقع (+10.0 m)","المقارنة بين الثلاثة"]'::jsonb, '["المسافة $= (25.0 - 5.0) + (25.0 - 15.0) = 30.0\\ \\text{m}$","$\\Delta\\boldsymbol{d} = 15.0\\ \\text{m} - 5.0\\ \\text{m} = +10.0\\ \\text{m}$"]'::jsonb, '[{"element":"معنى الموقع","marks":1},{"element":"معنى المسافة وقيمتها في التطبيق العددي","marks":1},{"element":"معنى الإزاحة وقيمتها في التطبيق العددي","marks":1},{"element":"المقارنة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"المفاهيم الثلاثة واضحة ومطبّقة على التطبيق العددي تطبيقًا صحيحًا"},{"level":"2–3 درجات","description":"تمييز صحيح مع خطأ في أحد الحسابين"},{"level":"1 درجة","description":"مفهوم واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["اعتبار الموقع النهائي 15.0 m هو الإزاحة","حساب المسافة 10.0 m بإهمال الذهاب والعودة","وصف الإزاحة بأنها كمية قياسية"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-18T12:34:59.226Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) المسافة $5.0\ \text{km} + 2.0\ \text{km} = 7.0\ \text{km}$، والإزاحة 3.0 km شرقًا (من المحطة إلى الموقف). (ب) العدّاد يعتمد على المسافة؛ لأن الوقود يُستهلك في كل ما تقطعه الحافلة ذهابًا وعودة دون اعتبار للاتجاه. والسهم على الخريطة يمثل الإزاحة؛ لأنه يبدأ من موقع البداية وينتهي عند موقع النهاية، فيحدد المقدار والاتجاه فقط.', '["المسافة 7.0 km","الإزاحة 3.0 km شرقًا","العدّاد يعتمد على المسافة مع التعليل","السهم يمثل الإزاحة مع التعليل"]'::jsonb, '["المسافة $= 5.0 + 2.0 = 7.0\\ \\text{km}$","الإزاحة: 5.0 km شرقًا − 2.0 km = 3.0 km شرقًا"]'::jsonb, '[{"element":"المسافة","marks":1},{"element":"الإزاحة بالمقدار والاتجاه","marks":1},{"element":"ربط العدّاد بالمسافة","marks":1},{"element":"ربط السهم بالإزاحة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"الحسابان صحيحان والربط معلل"},{"level":"2–3 درجات","description":"الحسابان صحيحان مع نقص في التعليل"},{"level":"1 درجة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["كتابة الإزاحة 3.0 km دون اتجاه","جمع 5.0 و2.0 للإزاحة","ربط العدّاد بالإزاحة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (7%)"}],"at":"2026-11-18T12:34:59.226Z"}'::jsonb),
('essay', 3, null::int, null, null, 'المسافة التي قطعها الأول 300 m، والثاني 450 m؛ فمسافة الثاني أكبر. أما الإزاحة فتعتمد على موقعي البداية والنهاية فقط، وهما واحد للصديقين (باب المدرسة وباب المكتبة)، فلهما الإزاحة نفسها: 300 m في اتجاه المكتبة (طول الممر المستقيم). لذا قول الثاني غير صحيح؛ فطول المسار يزيد المسافة ولا يغيّر الإزاحة.', '["المسافتان 300 m و450 m","الإزاحتان متساويتان مقدارًا واتجاهًا","مقدار الإزاحة 300 m نحو المكتبة","القول غير صحيح مع التعليل"]'::jsonb, '[]'::jsonb, '[{"element":"مقارنة المسافتين","marks":1},{"element":"مقارنة الإزاحتين مع التعليل","marks":2},{"element":"تقويم القول","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"مقارنة صحيحة للكميتين مع تقويم معلّل"},{"level":"2–3 درجات","description":"مقارنة صحيحة مع تقويم ناقص"},{"level":"1 درجة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["اعتبار إزاحة الثاني 450 m","إغفال اتجاه الإزاحة","قبول القول لأن المسافة أكبر"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-11-18T12:34:59.227Z"}'::jsonb)
