insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 3, '$\Delta\boldsymbol{d} = \boldsymbol{d}_f - \boldsymbol{d}_i = 26.5\ \text{m} - 8.0\ \text{m} = +18.5\ \text{m}$، أي 18.5 m في الاتجاه الموجب.', '["جمع الموقعين بدل طرحهما.","طرح الموقع النهائي من الابتدائي ($\\boldsymbol{d}_i - \\boldsymbol{d}_f$) فعكس إشارة الإزاحة.","اعتبر الموقع النهائي هو الإزاحة، وأهمل أن العدّاء لم يبدأ من نقطة الأصل.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-11-18T12:34:59.227Z"}'::jsonb),
('mcq', 2, 1, 'المسافة كل ما قطعته السيارة: من A (30 m) إلى B (40 m) قطعت 10 m، ومن B إلى C ($-20\ \text{m}$) قطعت 60 m، فالمسافة $10 + 60 = 70\ \text{m}$.', '["هذا مقدار الإزاحة من A إلى C ($|-20 - 30| = 50\\ \\text{m}$) لا المسافة.","","أخذ المرحلة الثانية فقط وأهمل المرحلة الأولى من A إلى B.","أخذ المرحلة الأولى فقط من A إلى B."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-11-18T12:34:59.227Z"}'::jsonb),
('mcq', 3, 2, 'الإزاحة تعتمد على موقعي البداية والنهاية فقط: $\Delta\boldsymbol{d} = \boldsymbol{d}_f - \boldsymbol{d}_i = 1.0\ \text{m} - 3.0\ \text{m} = -2.0\ \text{m}$، أي 2.0 m غربًا.', '["هذه المسافة (6.0 m + 8.0 m) لا الإزاحة، والمسافة كمية قياسية لا إشارة لها.","عكس ترتيب الطرح ($\\boldsymbol{d}_i - \\boldsymbol{d}_f$) فظهرت إشارة موجبة.","","حسب إزاحة مرحلة الارتداد وحدها (من 9.0 m إلى 1.0 m) لا الحركة كلها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-11-18T12:34:59.227Z"}'::jsonb),
('mcq', 4, 0, 'الإزاحتان في الاتجاه نفسه، فتُجمعان: $120\ \text{m} + 45\ \text{m} = 165\ \text{m}$ شرقًا؛ وفي هذه الحالة تساوي الإزاحة المسافة مقدارًا.', '["","طرح الإزاحتين كأنهما في اتجاهين متعاكسين.","طرح الإزاحتين وعكس الاتجاه، والحركة كلها نحو الشرق.","المقدار صحيح لكن الاتجاه خطأ؛ فالدراجة تحركت شرقًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-18T12:34:59.227Z"}'::jsonb),
('mcq', 5, 2, 'المسافة $= (30 - 12) + (30 - 6) = 18 + 24 = 42\ \text{m}$، والإزاحة $\Delta\boldsymbol{d} = 6\ \text{m} - 12\ \text{m} = -6\ \text{m}$، أي 6 m إلى أسفل.', '["بدّل بين الكميتين: 6 m مقدار الإزاحة و42 m المسافة.","المسافة صحيحة لكنه عكس إشارة الإزاحة ($\\boldsymbol{d}_i - \\boldsymbol{d}_f$)، والمصعد انتهى أسفل موقع بدايته.","","جمع الموقعين 30 m و6 m بدل جمع ما قطعه في كل مرحلة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-11-18T12:34:59.228Z"}'::jsonb),
('mcq', 6, 3, '$\Delta\boldsymbol{d} = \boldsymbol{d}_f - \boldsymbol{d}_i = 3.0\ \text{cm} - 12.5\ \text{cm} = -9.5\ \text{cm}$؛ والإشارة السالبة تعني أن النملة تحركت عكس اتجاه تزايد التدريج.', '["المقدار صحيح لكنه أهمل الإشارة؛ فالنملة تحركت نحو التدريج الأصغر.","جمع القراءتين بدل طرحهما.","اعتبر الموقع النهائي هو الإزاحة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-11-18T12:34:59.228Z"}'::jsonb),
('mcq', 7, 1, 'الإزاحة من موقع البداية إلى موقع النهاية، والسبّاح انتهى عند الطرف المقابل، فمقدار إزاحته طول الحوض 50 m؛ أما المسافة فهي 150 m.', '["هذه المسافة (3 × 50 m) لا مقدار الإزاحة.","","الإزاحة صفر فقط لو عاد إلى طرف البداية، وهو انتهى عند الطرف الآخر.","حسب طولين فقط، كأن الطول الثاني لا يُلغي جزءًا من الأول."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-11-18T12:34:59.228Z"}'::jsonb),
('essay', 1, null::int, null, null, '(أ) المسافة $= 1.0 + 0.3 + 0.8 + 0.4 = 2.5\ \text{m}$. (ب) نحو الشمال: $1.0\ \text{m} - 0.8\ \text{m} = 0.2\ \text{m}$ شمالًا، ونحو الشرق: $0.3\ \text{m} + 0.4\ \text{m} = 0.7\ \text{m}$ شرقًا. (ج) مقدار الإزاحة $= \sqrt{(0.2)^2 + (0.7)^2} = \sqrt{0.53} \approx 0.73\ \text{m}$ من البداية نحو الشمال الشرقي (أقرب إلى الشرق).', '["المسافة 2.5 m","الإزاحة 0.2 m شمالًا","الإزاحة 0.7 m شرقًا","المقدار 0.73 m تقريبًا"]'::jsonb, '["المسافة $= 1.0 + 0.3 + 0.8 + 0.4 = 2.5\\ \\text{m}$","شمالًا: $1.0 - 0.8 = 0.2\\ \\text{m}$","شرقًا: $0.3 + 0.4 = 0.7\\ \\text{m}$","$\\sqrt{0.2^2 + 0.7^2} = \\sqrt{0.53} \\approx 0.73\\ \\text{m}$"]'::jsonb, '[{"element":"المسافة","marks":1},{"element":"الإزاحة شمالًا","marks":1},{"element":"الإزاحة شرقًا","marks":1},{"element":"المقدار","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"جميع الحسابات صحيحة"},{"level":"2–3 درجات","description":"المسافة والمركبتان صحيحة مع خطأ في المقدار"},{"level":"1 درجة","description":"المسافة فقط صحيحة"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["جمع 1.0 و0.8 في اتجاه الشمال بدل طرحهما","اعتبار المسافة 2.5 m هي الإزاحة","جمع المركبتين 0.2 + 0.7 = 0.9 m مقدارًا للإزاحة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-11-18T12:34:59.228Z"}'::jsonb),
('essay', 2, null::int, null, null, 'المسافة: من 0 m إلى $+350\ \text{m}$ قطع 350 m، ومن $+350$ إلى $+120\ \text{m}$ قطع 230 m، ومن $+120$ إلى $+500\ \text{m}$ قطع 380 m؛ فالمسافة 960 m. الإزاحة $\Delta\boldsymbol{d} = 500\ \text{m} - 0 = +500\ \text{m}$، أي 500 m شرقًا. اختلفتا لأن العامل غيّر اتجاه حركته في المرحلة الثانية فعاد غربًا، فدخلت العودة في المسافة ولم تظهر في الإزاحة التي تعتمد على موقعي البداية والنهاية فقط.', '["المسافة 960 m","الإزاحة $+500\\ \\text{m}$ (شرقًا)","التفسير: تغيّر الاتجاه"]'::jsonb, '["350 m + 230 m + 380 m = 960 m","$\\Delta\\boldsymbol{d} = 500 - 0 = +500\\ \\text{m}$"]'::jsonb, '[{"element":"المسافة","marks":2},{"element":"الإزاحة","marks":1},{"element":"التفسير","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"حسابان صحيحان وتفسير صحيح"},{"level":"2–3 درجات","description":"أحد الحسابين خطأ أو التفسير ناقص"},{"level":"1 درجة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["حساب المسافة 500 m","جمع المواقع 350 + 120 + 500","إغفال الإشارة أو الاتجاه في الإزاحة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-11-18T12:34:59.229Z"}'::jsonb),
('essay', 3, null::int, null, null, '$\Delta\boldsymbol{d} = \boldsymbol{d}_f - \boldsymbol{d}_i = 25.0\ \text{m} - 5.0\ \text{m} = +20.0\ \text{m}$، والمسافة 20.0 m. تساوتا مقدارًا لأن العدّاء تحرك في خط مستقيم في اتجاه واحد دون عودة، فكل ما قطعه كان في اتجاه الإزاحة.', '["الإزاحة $+20.0\\ \\text{m}$","المسافة 20.0 m","التعليل: خط مستقيم باتجاه واحد"]'::jsonb, '["$\\Delta\\boldsymbol{d} = 25.0 - 5.0 = +20.0\\ \\text{m}$","المسافة = 20.0 m"]'::jsonb, '[{"element":"الإزاحة","marks":1},{"element":"المسافة","marks":1},{"element":"التعليل","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"الحسابان والتعليل صحيحة"},{"level":"2 درجتان","description":"الحسابان صحيحان دون تعليل"},{"level":"1 درجة","description":"حساب واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["اعتبار الإزاحة 25.0 m","جمع الموقعين (30.0 m)"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-11-18T12:34:59.229Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
