select (select id from public.objectives where code = 'P1-C2-L2-O15'), v.type, v.number, v.stem, v.stimulus::jsonb, v.images::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'يمثّل الشكل الآتي نموذج الجسيم النقطي لحركة سيارة، بفترات زمنية متساوية بين النقاط، وتحته أربعة أسهم مرقمة. أيّ الأسهم يمثّل إزاحة السيارة من نقطة البداية حتى نهاية الفترة الزمنية الثالثة؟', null, '[{"src":"qimg/phys1/c2l2-o15-car.svg","alt":"ست نقاط سوداء على خط أفقي تتزايد المسافات بينها من اليسار إلى اليمين، والنقطة اليسرى مكتوب فوقها «البداية»، وتنزل من كل نقطة خطوط إرشادية رأسية متقطعة. تحت النقاط أربعة أسهم خضراء أفقية: السهم (1) من النقطة الأولى إلى النقطة الرابعة يشير يمينًا، والسهم (2) بين النقطتين نفسيهما لكنه يشير يسارًا من الرابعة إلى الأولى، والسهم (3) من النقطة الأولى إلى النقطة الثالثة يشير يمينًا، والسهم (4) من النقطة الأولى إلى النقطة السادسة يشير يمينًا."}]'::jsonb, '["السهم (1)","السهم (2)","السهم (3)","السهم (4)"]'::jsonb, 'تطبيق', 'اختيار رسم', 'متوسط', 'الكتاب ص 36–37 — متجه الإزاحة على المخطط التوضيحي (الشكل 2-9) ومراجعة 2-2 (السؤالان 5 و6)'),
('mcq', 2, 'رسم طالب متجهات الإزاحة بين كل نقطتين متتاليتين على نموذج الجسيم النقطي لحركته من البيت إلى المدرسة على طريق مستقيم دون أن يعود، كما في الشكل الآتي. أيّ المتجهات رُسم بطريقة خطأ؟', null, '[{"src":"qimg/phys1/c2l2-o15-student.svg","alt":"خمس نقاط متساوية التباعد على خط أفقي، تحت النقطة اليسرى كلمة «البيت» وتحت النقطة اليمنى كلمة «المدرسة». فوق كل فترة بين نقطتين متتاليتين سهم أخضر مرقّم: (1) و(2) و(4) تشير نحو اليمين، أما (3) الواقع بين النقطة الثالثة والرابعة فيشير نحو اليسار."}]'::jsonb, '["المتجه (1)","المتجه (2)","المتجه (3)","المتجه (4)"]'::jsonb, 'تحليل', 'اكتشاف خطأ', 'متوسط', 'الكتاب ص 36–37 — متجه الإزاحة على المخطط التوضيحي (الشكل 2-9) ومراجعة 2-2 (السؤالان 5 و6)'),
('mcq', 3, 'عند رسم متجه الإزاحة على نموذج الجسيم النقطي بين موقعين، أين يوضع ذيل المتجه ورأسه؟', null, null, '["ذيله عند موقع نهاية الحركة، ورأسه عند موقع بدايتها","ذيله عند موقع بداية الحركة، ورأسه عند موقع نهايتها","ذيله عند نقطة الأصل، ورأسه عند موقع نهاية الحركة","ذيله عند نقطة الأصل، ورأسه عند موقع بداية الحركة"]'::jsonb, 'فهم', 'قاعدة رسم', 'سهل', 'الكتاب ص 36–37 — متجه الإزاحة على المخطط التوضيحي (الشكل 2-9) ومراجعة 2-2 (السؤالان 5 و6)'),
('mcq', 4, 'بدأت كرة حركتها من الموقع 2 m، فتدحرجت إلى الموقع 8 m، ثم ارتدت وتوقفت عند الموقع 5 m. أيّ مما يأتي يصف متجه الإزاحة الذي يُرسم على نموذج الجسيم النقطي للحركة كلها؟', null, null, '["سهم ذيله عند الموقع 2 m ورأسه عند الموقع 8 m","سهم ذيله عند الموقع 5 m ورأسه عند الموقع 2 m","سهم ذيله عند الموقع 0 m ورأسه عند الموقع 5 m","سهم ذيله عند الموقع 2 m ورأسه عند الموقع 5 m"]'::jsonb, 'تطبيق', 'وصف رسم', 'متوسط', 'الكتاب ص 36–37 — متجه الإزاحة على المخطط التوضيحي (الشكل 2-9) ومراجعة 2-2 (السؤالان 5 و6)'),
('mcq', 5, 'يريد طالب رسم متجه إزاحة مقداره 35 m باستعمال مقياس رسم 1 cm لكل 10 m. ما طول السهم الذي يرسمه على الورقة؟', null, null, '["35 cm","3.5 cm","0.35 cm","0.29 cm"]'::jsonb, 'تطبيق', 'مقياس رسم', 'صعب', 'الكتاب ص 35 — تمثيل المتجه بمقياس رسم مناسب'),
('mcq', 6, 'يبيّن الشكل الآتي نموذج الجسيم النقطي لحركة جسم فوق محور الموقع، وقد رُسم عليه متجه إزاحة أخضر. ما الإزاحة التي يمثلها هذا المتجه؟', null, '[{"src":"qimg/phys1/c2l2-o15-scale.svg","alt":"محور أفقي للموقع d بالمتر مدرّج من 0 إلى 60، الأرقام كل 10 m وعلامات صغيرة كل 5 m. أربع نقاط مرقمة فوق المحور: النقطة 1 عند 5 m، والنقطة 2 عند 15 m، والنقطة 3 عند 30 m، والنقطة 4 عند 50 m. فوق النقاط سهم أخضر أفقي يبدأ فوق النقطة 1 وينتهي رأسه فوق النقطة 4 مشيرًا إلى اليمين."}]'::jsonb, '["$+45\\ \\text{m}$","$+50\\ \\text{m}$","$-45\\ \\text{m}$","$+55\\ \\text{m}$"]'::jsonb, 'تطبيق', 'قراءة رسم', 'متوسط', 'الكتاب ص 36–37 — متجه الإزاحة على المخطط التوضيحي (الشكل 2-9) ومراجعة 2-2 (السؤالان 5 و6)'),
('mcq', 7, 'على ماذا يدل طول متجه الإزاحة المرسوم على نموذج الجسيم النقطي؟', null, null, '["الفترة الزمنية التي استغرقها الجسم بين الموقعين","بُعد الجسم عن نقطة الأصل عند نهاية الحركة","المسافة التي قطعها الجسم في اتجاه معيّن بين الموقعين","عدد النقاط الواقعة بين ذيل المتجه ورأسه"]'::jsonb, 'فهم', 'دلالة رسم', 'سهل', 'الكتاب ص 36 — تمثيل الإزاحة بسهم'),
('essay', 1, 'يمثّل الشكل الآتي نموذج الجسيم النقطي لحركة سيارة على طريق مستقيم (النقاط مرقمة من 1 إلى 5). إذا أردت رسم متجهات الإزاحة بمقياس رسم 1 cm لكل 10 m:
(أ) صِف كل متجه إزاحة بين نقطتين متتاليتين: موقع ذيله وموقع رأسه، وطوله على الورقة، واتجاهه.
(ب) صِف متجه الإزاحة من النقطة 1 إلى النقطة 5 وطوله على الورقة، وبيّن علاقته بالمتجهات الأربعة.', null, '[{"src":"qimg/phys1/c2l2-o15-essay.svg","alt":"محور أفقي للموقع d بالمتر مدرّج من 0 إلى 100 كل 10 m. فوقه خمس نقاط مرقمة: النقطة 1 عند 0 m، والنقطة 2 عند 10 m، والنقطة 3 عند 30 m، والنقطة 4 عند 60 m، والنقطة 5 عند 100 m."}]'::jsonb, null, 'تطبيق', 'وصف رسم', 'صعب', 'الكتاب ص 36–37 — متجه الإزاحة على المخطط التوضيحي (الشكل 2-9) ومراجعة 2-2 (السؤالان 5 و6)'),
('essay', 2, 'دُفعت عربة صغيرة إلى أعلى مستوى مائل فصعدت ثم عادت، وسُجّلت مواقعها على المستوى في فترات زمنية متساوية: 0.0 m، 0.8 m، 1.2 m، 0.8 m، 0.0 m (الاتجاه الموجب إلى أعلى المستوى).
(أ) صِف متجهات الإزاحة الأربعة بين كل نقطتين متتاليتين (المقدار والاتجاه).
(ب) ماذا تتوقع عند محاولة رسم متجه الإزاحة من النقطة الأولى إلى النقطة الأخيرة؟ فسّر.
(ج) ما المسافة التي قطعتها العربة؟', null, null, null, 'تحليل', 'تحليل حركة', 'صعب', 'الكتاب ص 36–37 — متجه الإزاحة على المخطط التوضيحي (الشكل 2-9) ومراجعة 2-2 (السؤالان 5 و6)'),
('essay', 3, 'اكتب خطوات رسم متجه إزاحة بين موقعين على نموذج الجسيم النقطي لحركة جسم، مع ذكر اللون المستعمل لمتجهات الإزاحة في المخططات.', null, null, null, 'فهم', 'إجراء', 'سهل', 'الكتاب ص 36–37 — متجه الإزاحة على المخطط التوضيحي (الشكل 2-9) ومراجعة 2-2 (السؤالان 5 و6)')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
