select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 0, 'نهاية الفترة الزمنية الثالثة هي النقطة الرابعة؛ ومتجه الإزاحة ذيله عند موقع البداية (النقطة الأولى) ورأسه عند موقع النهاية (النقطة الرابعة)، وهذا هو السهم (1).', '["","يصل بين النقطتين الصحيحتين لكن اتجاهه معكوس؛ رأسه عند البداية وذيله عند النقطة الرابعة.","ينتهي عند النقطة الثالثة، أي نهاية الفترة الثانية؛ فقد عدّ النقاط بدل الفترات.","يمثّل إزاحة السيارة للحركة كلها حتى النقطة السادسة، لا حتى نهاية الفترة الثالثة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-11-18T12:34:59.229Z"}'::jsonb),
('mcq', 2, 2, 'الطالب يتحرك دائمًا نحو المدرسة، فكل متجه إزاحة يجب أن يكون ذيله عند النقطة الأسبق ورأسه عند النقطة التالية، أي يشير نحو المدرسة؛ والمتجه (3) يشير نحو البيت.', '["ذيله عند النقطة الأولى ورأسه عند الثانية، فهو مرسوم بطريقة صحيحة.","يشير من النقطة الثانية إلى الثالثة نحو المدرسة، فهو صحيح.","","يشير من النقطة الرابعة إلى الخامسة نحو المدرسة، فهو صحيح."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (28%)"}],"at":"2026-11-18T12:34:59.229Z"}'::jsonb),
('mcq', 3, 1, 'متجه الإزاحة يُمثَّل بسهم يشير ذيله إلى موقع بداية الحركة، ويشير رأسه إلى موقع نهايتها.', '["هذا معكوس؛ المتجه الناتج يمثل إزاحة في الاتجاه المعاكس للحركة.","","هذا متجه الموقع النهائي لا متجه الإزاحة؛ فالإزاحة لا تبدأ من نقطة الأصل إلا إذا بدأت الحركة منها.","هذا متجه الموقع الابتدائي، ولا يعبّر عن التغير في الموقع."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (32%)"}],"at":"2026-11-18T12:34:59.230Z"}'::jsonb),
('mcq', 4, 3, 'متجه الإزاحة للحركة كلها يبدأ من موقع البداية (2 m) وينتهي عند موقع النهاية (5 m)، بغض النظر عن وصول الكرة إلى 8 m في أثناء حركتها؛ فطوله 3 m ويشير في الاتجاه الموجب.', '["هذا متجه إزاحة المرحلة الأولى فقط حتى نقطة الارتداد.","النقطتان صحيحتان لكن الاتجاه معكوس؛ فالذيل يكون عند البداية.","هذا متجه الموقع النهائي المرسوم من نقطة الأصل، لا متجه الإزاحة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-11-18T12:34:59.230Z"}'::jsonb),
('mcq', 5, 1, 'كل 1 cm يمثل 10 m، فطول السهم $= \frac{35\ \text{m}}{10\ \text{m/cm}} = 3.5\ \text{cm}$؛ لأن طول المتجه يتناسب مع مقدار الكمية التي يمثلها.', '["أهمل مقياس الرسم فرسم كل متر سنتيمترًا واحدًا.","","قسم على 100 بدل 10 كأن كل 1 cm يمثل 100 m.","قلب النسبة فقسم 10 على 35."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-18T12:34:59.230Z"}'::jsonb),
('mcq', 6, 0, 'ذيل المتجه عند النقطة 1 (الموقع 5 m) ورأسه عند النقطة 4 (الموقع 50 m)، فالإزاحة $\Delta\boldsymbol{d} = 50\ \text{m} - 5\ \text{m} = +45\ \text{m}$ في الاتجاه الموجب.', '["","هذا موقع رأس المتجه، وأهمل أن الذيل ليس عند نقطة الأصل.","المقدار صحيح لكن المتجه يشير في الاتجاه الموجب (نحو تزايد الموقع).","جمع موقعي الذيل والرأس بدل طرحهما."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (28%)"}],"at":"2026-11-18T12:34:59.230Z"}'::jsonb),
('mcq', 7, 2, 'طول سهم الإزاحة يمثل المسافة التي قطعها الجسم في اتجاه معيّن، وهو الاتجاه الذي يشير إليه السهم.', '["الزمن لا يُمثَّل بطول متجه الإزاحة، بل يُحسب من عدد الفترات بين النقاط.","هذا ما يدل عليه طول متجه الموقع النهائي لا متجه الإزاحة.","","عدد النقاط يدل على عدد الفترات الزمنية، لا على طول الإزاحة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (28%)"}],"at":"2026-11-18T12:34:59.230Z"}'::jsonb),
('essay', 1, null::int, null, null, '(أ) من 1 إلى 2: ذيله عند 0 m ورأسه عند 10 m، إزاحته 10 m فطوله 1 cm. من 2 إلى 3: ذيله عند 10 m ورأسه عند 30 m، طوله 2 cm. من 3 إلى 4: ذيله عند 30 m ورأسه عند 60 m، طوله 3 cm. من 4 إلى 5: ذيله عند 60 m ورأسه عند 100 m، طوله 4 cm. وجميعها تشير في الاتجاه الموجب (اتجاه الحركة)، وتتزايد أطوالها لأن السيارة تقطع مسافات متزايدة. (ب) ذيله عند 0 m ورأسه عند 100 m، إزاحته $+100\ \text{m}$ فطوله 10 cm في الاتجاه الموجب، ويساوي مجموع المتجهات الأربعة الموضوعة رأسًا لذيل: $1 + 2 + 3 + 4 = 10\ \text{cm}$.', '["أطوال المتجهات 1 و2 و3 و4 cm","الذيل عند النقطة الأسبق والرأس عند التالية","جميعها في الاتجاه الموجب","المتجه الكلي 10 cm (100 m)","المتجه الكلي محصلة المتجهات الأربعة"]'::jsonb, '["الإزاحات: 10 m، 20 m، 30 m، 40 m","الأطوال بالقسمة على 10 m/cm: 1، 2، 3، 4 cm","الكلي: $100 - 0 = 100\\ \\text{m}$ أي 10 cm"]'::jsonb, '[{"element":"المتجهات الأربعة بالذيل والرأس والطول","marks":2},{"element":"الاتجاه","marks":1},{"element":"المتجه الكلي وطوله","marks":1},{"element":"العلاقة بالمتجهات الأربعة","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"وصف كامل وصحيح لجميع المتجهات والمتجه الكلي وعلاقته بها"},{"level":"3–4 درجات","description":"المتجهات صحيحة مع خطأ في مقياس الرسم أو إغفال العلاقة"},{"level":"1–2 درجة","description":"وصف قاعدة الذيل والرأس دون أطوال صحيحة"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["رسم المتجهات من نقطة الأصل بدل النقطة الأسبق","استعمال المواقع أطوالًا للمتجهات (1، 3، 6، 10 cm)","رسم المتجهات بأطوال متساوية"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (28%)"}],"at":"2026-11-18T12:34:59.230Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) الأول $+0.8\ \text{m}$ (إلى أعلى المستوى)، والثاني $+0.4\ \text{m}$ (إلى أعلى)، والثالث $-0.4\ \text{m}$ (إلى أسفل)، والرابع $-0.8\ \text{m}$ (إلى أسفل)؛ ويُرسم كل منها ذيله عند النقطة الأسبق ورأسه عند التالية، فالمتجهان الأخيران يشيران إلى أسفل المستوى. (ب) لا يمكن رسم سهم؛ لأن موقع البداية وموقع النهاية متطابقان (0.0 m)، فالإزاحة الكلية صفر، ومجموع المتجهات الأربعة صفر. (ج) المسافة $0.8 + 0.4 + 0.4 + 0.8 = 2.4\ \text{m}$.', '["$+0.8$ و$+0.4$ و$-0.4$ و$-0.8\\ \\text{m}$","اتجاه المتجهين الأخيرين إلى أسفل","الإزاحة الكلية صفر فلا يُرسم سهم","المسافة 2.4 m"]'::jsonb, '["$0.8 - 0.0 = +0.8$، $1.2 - 0.8 = +0.4$، $0.8 - 1.2 = -0.4$، $0.0 - 0.8 = -0.8$","$\\Delta\\boldsymbol{d} = 0.0 - 0.0 = 0$","2.4 m = 0.8 + 0.4 + 0.4 + 0.8"]'::jsonb, '[{"element":"المتجهات الأربعة","marks":2},{"element":"الإزاحة الكلية مع التفسير","marks":1},{"element":"المسافة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"جميع العناصر صحيحة"},{"level":"2–3 درجات","description":"المتجهات صحيحة مع خطأ في الإزاحة الكلية أو المسافة"},{"level":"1 درجة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["رسم جميع المتجهات إلى أعلى المستوى","اعتبار الإزاحة الكلية 2.4 m","رسم سهم الإزاحة الكلية من النقطة الأولى إلى أعلى نقطة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-11-18T12:34:59.231Z"}'::jsonb),
('essay', 3, null::int, null, null, 'نحدد النقطة التي تمثل موقع بداية الحركة المدروسة والنقطة التي تمثل موقع نهايتها؛ ثم نرسم سهمًا يبدأ ذيله عند نقطة البداية وينتهي رأسه عند نقطة النهاية؛ ويكون طول السهم متناسبًا مع مقدار الإزاحة وفق مقياس الرسم إن وُجد، واتجاهه هو اتجاه التغير في الموقع؛ ثم نكتب الرمز $\Delta\boldsymbol{d}$ بجانبه. وتظهر متجهات الإزاحة باللون الأخضر.', '["تحديد نقطتي البداية والنهاية","الذيل عند البداية والرأس عند النهاية","الطول متناسب مع المقدار والاتجاه نحو موقع النهاية","اللون الأخضر"]'::jsonb, '[]'::jsonb, '[{"element":"تحديد النقطتين","marks":1},{"element":"موضع الذيل والرأس","marks":1},{"element":"الطول والاتجاه","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"خطوات صحيحة ومرتبة"},{"level":"2 درجتان","description":"خطوتان صحيحتان"},{"level":"1 درجة","description":"خطوة واحدة صحيحة"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["رسم السهم من نقطة الأصل","عكس الذيل والرأس"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (32%)"}],"at":"2026-11-18T12:34:59.231Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
