('mcq', 2, 'في الشكل الآتي، ما المتجه $\boldsymbol{A} - \boldsymbol{B}$؟', null, '[{"src":"qimg/phys1/c2l2-o16-AB.svg","alt":"شبكة مربعات، وتحتها «ضلع المربع يمثل 1 m» وسهم مكتوب بجانبه «شرق» يشير إلى اليمين. متجه أخضر A أفقي نحو اليمين طوله 5 مربعات، وتحته متجه أخضر B أفقي نحو اليمين طوله مربعان، يبدأ المتجهان من الموضع الأفقي نفسه."}]'::jsonb, '["7 m شرقًا","3 m غربًا","7 m غربًا","3 m شرقًا"]'::jsonb, 'فهم', 'قراءة رسم', 'سهل', 'الكتاب ص 37 — طرح المتجهات (الشكلان 2-10 و2-11)'),
('mcq', 3, 'يبيّن الشكل الآتي المتجهين $\boldsymbol{A}$ و$\boldsymbol{B}$، وأربعة رسوم مرقمة رُسم في كلٍّ منها متجه محصلة بخط متقطع. أيّ الرسوم يمثّل إيجاد $\boldsymbol{A} - \boldsymbol{B}$ بطريقة صحيحة؟', null, '[{"src":"qimg/phys1/c2l2-o16-panels.svg","alt":"في الأعلى «المتجهان الأصليان»: متجه أخضر A أفقي نحو اليمين طوله 4 وحدات، ومتجه أخضر B رأسي إلى أعلى طوله وحدتان. وتحتهما أربعة رسوم: (1) A نحو اليمين ثم من رأسه متجه −B إلى أسفل، وخط متقطع من ذيل A إلى رأس −B. (2) A نحو اليمين ثم من رأسه B إلى أعلى، وخط متقطع من ذيل A إلى رأس B. (3) −A نحو اليسار ثم من رأسه B إلى أعلى، وخط متقطع من ذيل −A إلى رأس B. (4) A نحو اليمين و−B إلى أسفل يبدآن من النقطة نفسها، وخط متقطع من رأس A إلى رأس −B."}]'::jsonb, '["الرسم (1)","الرسم (2)","الرسم (3)","الرسم (4)"]'::jsonb, 'فهم', 'اختيار رسم', 'متوسط', 'الكتاب ص 37 — طرح المتجهات (الشكلان 2-10 و2-11)'),
('mcq', 4, 'ما المتجه $-\boldsymbol{B}$؟', null, null, '["متجه اتجاهه اتجاه $\\boldsymbol{B}$ نفسه، ومقداره سالب","متجه له مقدار $\\boldsymbol{B}$ نفسه، واتجاهه عكس اتجاه $\\boldsymbol{B}$","متجه مقداره صفر؛ لأنه يُلغي المتجه $\\boldsymbol{B}$","متجه اتجاهه عمودي على $\\boldsymbol{B}$، وله المقدار نفسه"]'::jsonb, 'فهم', 'مفهوم', 'سهل', 'الكتاب ص 37 — طرح المتجهات (الشكلان 2-10 و2-11)'),
('mcq', 5, 'رُسم متجها إزاحة $\boldsymbol{A}$ و$\boldsymbol{B}$ بمقياس رسم على الشبكة الآتية. إذا طُرح $\boldsymbol{B}$ من $\boldsymbol{A}$، فما مقدار الناتج واتجاهه بالمتر؟', null, '[{"src":"qimg/phys1/c2l2-o16-west.svg","alt":"شبكة مربعات، وتحتها «ضلع المربع يمثل 10 m» وسهم مكتوب بجانبه «شرق» يشير إلى اليمين. متجه أخضر A أفقي نحو اليمين طوله 3 مربعات، وتحته متجه أخضر B أفقي نحو اليسار طوله مربعان."}]'::jsonb, '["50 m شرقًا","10 m شرقًا","50 m غربًا","10 m غربًا"]'::jsonb, 'تطبيق', 'قراءة رسم', 'صعب', 'الكتاب ص 37 — طرح المتجهات (الشكلان 2-10 و2-11)'),
('mcq', 6, 'يبيّن الشكل الآتي متجهَي الموقع الابتدائي $\boldsymbol{d}_i$ والنهائي $\boldsymbol{d}_f$ لجسم. كيف يُرسم متجه الإزاحة $\Delta\boldsymbol{d} = \boldsymbol{d}_f - \boldsymbol{d}_i$ بيانيًّا؟', null, '[{"src":"qimg/phys1/c2l2-o16-dfdi.svg","alt":"محور أفقي للموقع d بالمتر مدرّج من 0 إلى 12 كل 1 m، ومكتوب عند الصفر «نقطة الأصل»، ونقطتان على المحور عند 4 m و10 m. فوق المحور متجه أخضر d_i يبدأ من الصفر وينتهي عند 4 m، وفوقه متجه أخضر d_f يبدأ من الصفر وينتهي عند 10 m، وكلاهما يشير إلى اليمين."}]'::jsonb, '["يوضع ذيل $\\boldsymbol{d}_i$ عند رأس $\\boldsymbol{d}_f$ دون عكسه، ثم يُرسم المتجه من ذيل $\\boldsymbol{d}_f$ إلى رأس $\\boldsymbol{d}_i$","يُعكس $\\boldsymbol{d}_f$، ويوضع ذيل $-\\boldsymbol{d}_f$ عند رأس $\\boldsymbol{d}_i$، ثم يُرسم المتجه من ذيل $\\boldsymbol{d}_i$ إلى رأس $-\\boldsymbol{d}_f$","يُعكس $\\boldsymbol{d}_i$، ويوضع ذيل $-\\boldsymbol{d}_i$ عند رأس $\\boldsymbol{d}_f$، ثم يُرسم المتجه من ذيل $\\boldsymbol{d}_f$ إلى رأس $-\\boldsymbol{d}_i$","يُرسم المتجه من نقطة الأصل إلى رأس $\\boldsymbol{d}_f$ مباشرة؛ لأنه يمثل الإزاحة"]'::jsonb, 'فهم', 'إجراء', 'متوسط', 'الكتاب ص 37 — طرح المتجهات (الشكلان 2-10 و2-11)'),
('mcq', 7, 'ما العلاقة بين المتجهين $\boldsymbol{A} - \boldsymbol{B}$ و$\boldsymbol{B} - \boldsymbol{A}$ لأي متجهين $\boldsymbol{A}$ و$\boldsymbol{B}$؟', null, null, '["متساويان في المقدار والاتجاه؛ لأن ترتيب الطرح لا يؤثر","مقدار الأول أكبر دائمًا، ولهما الاتجاه نفسه","متعامدان، ولهما المقدار نفسه","لهما المقدار نفسه، واتجاهاهما متعاكسان"]'::jsonb, 'تحليل', 'استنتاج', 'متوسط', 'الكتاب ص 37 — طرح المتجهات (الشكلان 2-10 و2-11)'),
('essay', 1, 'المتجه $\boldsymbol{A}$ طوله 6 cm ويتجه شرقًا، والمتجه $\boldsymbol{B}$ طوله 2 cm ويتجه شرقًا أيضًا. وضّح بالخطوات كيف تجد $\boldsymbol{A} - \boldsymbol{B}$ بيانيًّا، وحدّد مقدار الناتج واتجاهه.', null, null, null, 'فهم', 'شرح إجراء', 'متوسط', 'الكتاب ص 37 — طرح المتجهات (الشكلان 2-10 و2-11)'),
('essay', 2, 'نقطة الأصل لمحور موقع أفقي في منتصف ممر، والاتجاه الموجب نحو اليمين. تحرك جسم من الموقع $\boldsymbol{d}_i = +3\ \text{m}$ إلى الموقع $\boldsymbol{d}_f = -5\ \text{m}$.
(أ) صِف متجهي الموقع $\boldsymbol{d}_i$ و$\boldsymbol{d}_f$.
(ب) وضّح كيف تجد $\Delta\boldsymbol{d} = \boldsymbol{d}_f - \boldsymbol{d}_i$ بالرسم.
(ج) احسب $\Delta\boldsymbol{d}$ وتحقق من أن الناتج يتفق مع الرسم.', null, null, null, 'تطبيق', 'رسم وحساب', 'صعب', 'الكتاب ص 37 — طرح المتجهات (الشكلان 2-10 و2-11)'),
('essay', 3, 'قال طالب: «$\boldsymbol{A} - \boldsymbol{B}$ هو نفسه $\boldsymbol{B} - \boldsymbol{A}$؛ لأننا في الحالتين نطرح الطول الأصغر من الأكبر». قوّم قوله باستعمال مثال: $\boldsymbol{A}$ = 5 m شرقًا، و$\boldsymbol{B}$ = 3 m شرقًا.', null, null, null, 'تقويم', 'تقويم عبارة', 'صعب', 'الكتاب ص 37 — طرح المتجهات (الشكلان 2-10 و2-11)')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
