from (values
('mcq', 1, 2, 'لطرح متجه من آخر نعكس اتجاه المتجه المراد طرحه ثم نجمعهما: $\boldsymbol{A} - \boldsymbol{B} = \boldsymbol{A} + (-\boldsymbol{B})$.', '["هذا يصلح فقط عندما يكون المتجهان في الاتجاه نفسه، ولا يمثل الطريقة العامة للطرح.","هذا يعطي $\\boldsymbol{B} - \\boldsymbol{A}$ لا $\\boldsymbol{A} - \\boldsymbol{B}$.","","هذه طريقة جمع $\\boldsymbol{A} + \\boldsymbol{B}$، دون عكس اتجاه $\\boldsymbol{B}$."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (40%)"}],"at":"2026-11-18T12:34:59.231Z"}'::jsonb),
('mcq', 2, 3, '$\boldsymbol{A}$ = 5 مربعات شرقًا = 5 m شرقًا، و$\boldsymbol{B}$ = 2 m شرقًا، فيكون $-\boldsymbol{B}$ = 2 m غربًا، و$\boldsymbol{A} + (-\boldsymbol{B})$ = 3 m شرقًا.', '["جمع المتجهين ($\\boldsymbol{A} + \\boldsymbol{B}$) دون عكس اتجاه $\\boldsymbol{B}$.","هذا $\\boldsymbol{B} - \\boldsymbol{A}$؛ المقدار صحيح والاتجاه معكوس.","جمع المقدارين وعكس الاتجاه معًا.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (50%)"}],"at":"2026-11-18T12:34:59.231Z"}'::jsonb),
('mcq', 3, 0, 'في الرسم (1) عُكس اتجاه $\boldsymbol{B}$ فصار $-\boldsymbol{B}$ (إلى أسفل)، ووُضع ذيله عند رأس $\boldsymbol{A}$، ورُسمت المحصلة من ذيل $\boldsymbol{A}$ إلى رأس $-\boldsymbol{B}$، أي $\boldsymbol{A} + (-\boldsymbol{B})$.', '["","لم يُعكس اتجاه $\\boldsymbol{B}$، فالمحصلة المرسومة تمثل $\\boldsymbol{A} + \\boldsymbol{B}$.","عُكس اتجاه $\\boldsymbol{A}$ بدل $\\boldsymbol{B}$، فالمحصلة تمثل $\\boldsymbol{B} - \\boldsymbol{A}$.","وُضع $-\\boldsymbol{B}$ وذيله عند ذيل $\\boldsymbol{A}$ لا عند رأسه، ورُسم المتقطع بين الرأسين، فلا يمثل $\\boldsymbol{A} + (-\\boldsymbol{B})$ بطريقة الرأس للذيل."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-11-18T12:34:59.232Z"}'::jsonb),
('mcq', 4, 1, '$-\boldsymbol{B}$ متجه يساوي $\boldsymbol{B}$ في المقدار ويعاكسه في الاتجاه، ويُستعمل لتحويل الطرح إلى جمع.', '["مقدار المتجه (طوله) لا يكون سالبًا؛ الإشارة السالبة تعني عكس الاتجاه.","","$-\\boldsymbol{B}$ له مقدار $\\boldsymbol{B}$ نفسه؛ ومجموعه مع $\\boldsymbol{B}$ هو الذي يساوي صفرًا.","عكس الاتجاه يعني دورانه نصف دورة لا ربع دورة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (50%)"}],"at":"2026-11-18T12:34:59.232Z"}'::jsonb),
('mcq', 5, 0, '$\boldsymbol{A}$ = 3 مربعات شرقًا = 30 m شرقًا، و$\boldsymbol{B}$ = 20 m غربًا، فيكون $-\boldsymbol{B}$ = 20 m شرقًا، و$\boldsymbol{A} + (-\boldsymbol{B})$ = 50 m شرقًا.', '["","جمع $\\boldsymbol{A} + \\boldsymbol{B}$ (30 m شرقًا مع 20 m غربًا) دون عكس اتجاه $\\boldsymbol{B}$.","هذا $\\boldsymbol{B} - \\boldsymbol{A}$؛ المقدار صحيح والاتجاه معكوس.","طرح المقدارين وعكس الاتجاه، دون اتباع قاعدة عكس المتجه المطروح."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-11-18T12:34:59.232Z"}'::jsonb),
('mcq', 6, 2, 'الإزاحة $\boldsymbol{d}_f - \boldsymbol{d}_i = \boldsymbol{d}_f + (-\boldsymbol{d}_i)$؛ فنعكس $\boldsymbol{d}_i$ وننقله بحيث يكون ذيله عند رأس $\boldsymbol{d}_f$ ثم نجمعهما، فينتج متجه طوله 6 m في الاتجاه الموجب.', '["هذا جمع $\\boldsymbol{d}_f + \\boldsymbol{d}_i$ لا طرحهما.","هذا يعطي $\\boldsymbol{d}_i - \\boldsymbol{d}_f$، أي الإزاحة معكوسة الاتجاه.","","هذا متجه الموقع النهائي $\\boldsymbol{d}_f$ نفسه، ويهمل أن الجسم لم يبدأ من نقطة الأصل."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-11-18T12:34:59.232Z"}'::jsonb),
('mcq', 7, 3, '$\boldsymbol{B} - \boldsymbol{A} = -(\boldsymbol{A} - \boldsymbol{B})$؛ فعكس ترتيب الطرح يعكس اتجاه الناتج ويبقي مقداره كما هو، أي أن لهما المقدار نفسه واتجاهاهما متعاكسان.', '["ترتيب الطرح يؤثر؛ فعكسه يعكس اتجاه الناتج، بخلاف الجمع.","المقداران متساويان، والاتجاهان متعاكسان لا متماثلان.","الناتجان على خط واحد بعكس الاتجاه، لا متعامدان.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-18T12:34:59.232Z"}'::jsonb),
('essay', 1, null::int, null, null, 'نكتب الطرح على صورة جمع: $\boldsymbol{A} - \boldsymbol{B} = \boldsymbol{A} + (-\boldsymbol{B})$. نرسم $\boldsymbol{A}$ بطول 6 cm نحو الشرق، ثم نرسم $-\boldsymbol{B}$ بطول 2 cm نحو الغرب (عكس اتجاه $\boldsymbol{B}$) بحيث يكون ذيله عند رأس $\boldsymbol{A}$، ثم نرسم المحصلة من ذيل $\boldsymbol{A}$ إلى رأس $-\boldsymbol{B}$، فيكون طولها 4 cm نحو الشرق.', '["$\\boldsymbol{A} - \\boldsymbol{B} = \\boldsymbol{A} + (-\\boldsymbol{B})$","$-\\boldsymbol{B}$: 2 cm غربًا","ذيل $-\\boldsymbol{B}$ عند رأس $\\boldsymbol{A}$","المحصلة 4 cm شرقًا"]'::jsonb, '[]'::jsonb, '[{"element":"تحويل الطرح إلى جمع","marks":1},{"element":"عكس $\\boldsymbol{B}$ ووضعه رأسًا لذيل","marks":1},{"element":"الناتج مقدارًا واتجاهًا","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"خطوات صحيحة وناتج صحيح"},{"level":"2 درجتان","description":"خطوات صحيحة مع خطأ في الاتجاه أو المقدار"},{"level":"1 درجة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["جمع $\\boldsymbol{A}$ و$\\boldsymbol{B}$ فيكون الناتج 8 cm","كتابة الناتج 4 cm دون اتجاه","عكس اتجاه $\\boldsymbol{A}$ بدل $\\boldsymbol{B}$"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-11-18T12:34:59.232Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) $\boldsymbol{d}_i$ سهم ذيله عند نقطة الأصل ورأسه عند 3 m إلى اليمين، و$\boldsymbol{d}_f$ سهم ذيله عند نقطة الأصل ورأسه عند 5 m إلى اليسار. (ب) نعكس $\boldsymbol{d}_i$ فنحصل على $-\boldsymbol{d}_i$ (3 m نحو اليسار)، وننقله بحيث يكون ذيله عند رأس $\boldsymbol{d}_f$، ثم نرسم المحصلة من ذيل $\boldsymbol{d}_f$ (نقطة الأصل) إلى رأس $-\boldsymbol{d}_i$، فتنتهي عند $-8\ \text{m}$. (ج) $\Delta\boldsymbol{d} = -5\ \text{m} - (+3\ \text{m}) = -8\ \text{m}$، أي 8 m نحو اليسار، وهو طول المحصلة واتجاهها في الرسم، ويطابق انتقال الجسم من 3 m يمين الأصل إلى 5 m يساره.', '["وصف متجهي الموقع","عكس $\\boldsymbol{d}_i$ ووضعه رأسًا لذيل مع $\\boldsymbol{d}_f$","$\\Delta\\boldsymbol{d} = -8\\ \\text{m}$","اتفاق الحساب مع الرسم"]'::jsonb, '["$-\\boldsymbol{d}_i = -3\\ \\text{m}$","$\\Delta\\boldsymbol{d} = \\boldsymbol{d}_f + (-\\boldsymbol{d}_i) = -5 + (-3) = -8\\ \\text{m}$"]'::jsonb, '[{"element":"متجها الموقع","marks":1},{"element":"خطوات الرسم","marks":1},{"element":"الحساب","marks":1},{"element":"التحقق","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"جميع العناصر صحيحة"},{"level":"2–3 درجات","description":"حساب صحيح مع نقص في وصف الرسم أو العكس"},{"level":"1 درجة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["حساب $-5 - 3$ على أنه $-2$","نسيان عكس اتجاه $\\boldsymbol{d}_i$","كتابة الإزاحة $+8\\ \\text{m}$"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-18T12:34:59.233Z"}'::jsonb),
('essay', 3, null::int, null, null, 'القول غير صحيح. $\boldsymbol{A} - \boldsymbol{B} = \boldsymbol{A} + (-\boldsymbol{B})$ = 5 m شرقًا + 3 m غربًا = 2 m شرقًا. أما $\boldsymbol{B} - \boldsymbol{A} = \boldsymbol{B} + (-\boldsymbol{A})$ = 3 m شرقًا + 5 m غربًا = 2 m غربًا. الناتجان متساويان في المقدار ومتعاكسان في الاتجاه؛ لأن طرح المتجهات يعتمد على عكس اتجاه المتجه المطروح، والمتجه لا يُحدَّد بمقداره فقط بل بمقداره واتجاهه معًا.', '["$\\boldsymbol{A} - \\boldsymbol{B}$ = 2 m شرقًا","$\\boldsymbol{B} - \\boldsymbol{A}$ = 2 m غربًا","الناتجان متعاكسان فالقول خطأ","التعليل: المتجه مقدار واتجاه"]'::jsonb, '["$\\boldsymbol{A} + (-\\boldsymbol{B})$: 5 m شرقًا + 3 m غربًا = 2 m شرقًا","$\\boldsymbol{B} + (-\\boldsymbol{A})$: 3 m شرقًا + 5 m غربًا = 2 m غربًا"]'::jsonb, '[{"element":"حساب $\\boldsymbol{A} - \\boldsymbol{B}$","marks":1},{"element":"حساب $\\boldsymbol{B} - \\boldsymbol{A}$","marks":1},{"element":"الحكم مع التعليل","marks":2}]'::jsonb, '[{"level":"4 درجات","description":"حسابان صحيحان وحكم معلل"},{"level":"2–3 درجات","description":"حسابان صحيحان مع تعليل ناقص"},{"level":"1 درجة","description":"حكم صحيح دون أدلة"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["الاكتفاء بالمقدار 2 m في الحالتين","قبول قول الطالب"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (7%)"}],"at":"2026-11-18T12:34:59.233Z"}'::jsonb)
