('mcq', 4, 'لماذا يجوز نقل متجه من موضع إلى آخر على الورقة عند جمع المتجهات بيانيًّا؟', null, null, '["لأن موضع المتجه على الورقة يحدد مقداره، فيجب تحريكه إلى المكان الصحيح","لأن نقل المتجه يغيّر اتجاهه بما يناسب المتجه الآخر","لأن المتجه يتحدد بمقداره واتجاهه، فإذا بقيا ثابتين بقي المتجه نفسه","لأن المحصلة لا تعتمد على اتجاهات المتجهات المجموعة"]'::jsonb, 'فهم', 'تعليل', 'سهل', 'الكتاب ص 35 و37 — نقل المتجه عند الجمع والطرح (الشكلان 2-8 و2-11)'),
('mcq', 5, 'عند حساب الإزاحة بيانيًّا من العلاقة $\Delta\boldsymbol{d} = \boldsymbol{d}_f + (-\boldsymbol{d}_i)$، يُنقل المتجه $-\boldsymbol{d}_i$ بحيث يكون ذيله عند رأس $\boldsymbol{d}_f$. ما الذي يبقى ثابتًا للمتجه $-\boldsymbol{d}_i$ في أثناء نقله؟', null, null, '["طوله، واتجاهه المعاكس لاتجاه $\\boldsymbol{d}_i$","موضع ذيله عند نقطة الأصل","اتجاهه فقط، أما طوله فيصبح مساويًا لطول $\\boldsymbol{d}_f$","طوله فقط، أما اتجاهه فيصبح اتجاه $\\boldsymbol{d}_f$"]'::jsonb, 'فهم', 'تطبيق مبدأ', 'متوسط', 'الكتاب ص 35 و37 — نقل المتجه عند الجمع والطرح (الشكلان 2-8 و2-11)'),
('mcq', 6, 'رُسم متجه طوله 4.0 cm في اتجاه الشمال الشرقي على ورقة، ثم نُقل إلى مكان آخر على الورقة نفسها لاستعماله في جمع بياني. أيّ وصف للمتجه بعد نقله صحيح؟', null, null, '["طوله 4.0 cm واتجاهه يتحدد حسب المكان الجديد","طوله 4.0 cm واتجاهه الشمال الشرقي","طوله يتغير حسب بُعد المكان الجديد عن مكانه الأول","طوله 4.0 cm واتجاهه الجنوب الغربي"]'::jsonb, 'تطبيق', 'تطبيق مبدأ', 'متوسط', 'الكتاب ص 35 و37 — نقل المتجه عند الجمع والطرح (الشكلان 2-8 و2-11)'),
('mcq', 7, 'عند نقل متجه موازيًا لنفسه إلى موضع جديد على الورقة، أيّ خصائصه تتغير؟', null, null, '["طوله فقط، ويبقى اتجاهه كما هو","اتجاهه فقط، ويبقى طوله كما هو","موضع ذيله ورأسه على الورقة فقط","طوله واتجاهه معًا"]'::jsonb, 'فهم', 'مفهوم', 'سهل', 'الكتاب ص 35 و37 — نقل المتجه عند الجمع والطرح (الشكلان 2-8 و2-11)'),
('essay', 1, 'عند جمع متجهين بيانيًّا نضع ذيل المتجه الثاني عند رأس المتجه الأول. وضّح لماذا يُسمح بنقل المتجه الثاني من مكانه، وما الشرطان اللذان يجب تحقيقهما عند نقله، وماذا يحدث لو لم يتحققا.', null, null, null, 'فهم', 'شرح مبدأ', 'متوسط', 'الكتاب ص 35 و37 — نقل المتجه عند الجمع والطرح (الشكلان 2-8 و2-11)'),
('essay', 2, 'أراد طالب إيجاد $\boldsymbol{A} - \boldsymbol{B}$ حيث $\boldsymbol{A}$ = 6 cm شرقًا و$\boldsymbol{B}$ = 4 cm شرقًا. فرسم $\boldsymbol{A}$، ثم رسم $-\boldsymbol{B}$ نحو الغرب، لكنه عندما نقله ليضع ذيله عند رأس $\boldsymbol{A}$ قصّره إلى 2 cm ليتسع في الورقة، فحصل على محصلة 4 cm شرقًا.
(أ) حدّد الخطأ في عمله.
(ب) ما الناتج الصحيح؟
(ج) اقترح طريقة يحل بها مشكلة ضيق الورقة دون الوقوع في هذا الخطأ.', null, null, null, 'تحليل', 'اكتشاف خطأ وتصحيحه', 'صعب', 'الكتاب ص 35 و37 — نقل المتجه عند الجمع والطرح (الشكلان 2-8 و2-11)'),
('essay', 3, 'رسم طالب متجهًا في أعلى الورقة، ثم رسم متجهًا آخر في أسفلها له الطول نفسه والاتجاه نفسه. هل يمثل المتجهان الكمية المتجهة نفسها؟ فسّر، ثم صِف متجهًا ثالثًا مرسومًا في وسط الورقة لا يمثل الكمية نفسها رغم أن طوله يساوي طولهما.', null, null, null, 'فهم', 'تفسير', 'صعب', 'الكتاب ص 35 و37 — نقل المتجه عند الجمع والطرح (الشكلان 2-8 و2-11)')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
where not exists (select 1 from public.questions x where x.objective_id = (select id from public.objectives where code = 'P1-C2-L2-O17') and x.type = v.type and x.number = v.number);
insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 1, 'المتجه يتحدد بمقداره واتجاهه؛ لذا عند نقله يجب أن يبقى طوله واتجاهه كما هما، ويتغير موضعه على الورقة فقط.', '["تغيير الاتجاه ينتج متجهًا آخر، فتكون المحصلة خطأ.","","تغيير الطول يغيّر مقدار الكمية التي يمثلها المتجه.","النقل يعني تغيير موضع الذيل، بشرط بقاء الطول والاتجاه."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-11-18T12:34:59.234Z"}'::jsonb),
('mcq', 2, 0, 'المتجه (1) يتحرك 3 مربعات أفقيًّا ومربعين رأسيًّا مثل $\boldsymbol{A}$ تمامًا، فله الطول والاتجاه نفسهما، وتغيّر موضعه فقط.', '["","له الاتجاه نفسه لكنه أطول (4.5 مربعات أفقيًّا و3 رأسيًّا)، فمقداره تغيّر.","طوله يساوي طول $\\boldsymbol{A}$ لكن اتجاهه مختلف (مربعان أفقيًّا و3 رأسيًّا بدل 3 أفقيًّا ومربعين رأسيًّا).","له الطول نفسه لكن اتجاهه معكوس، فهو يمثل $-\\boldsymbol{A}$."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-11-18T12:34:59.234Z"}'::jsonb),
('mcq', 3, 3, 'المتجه $\boldsymbol{B}$ الأصلي يشير إلى أعلى (الشمال)، لكن الطالب رسمه بعد النقل يشير إلى اليمين (الشرق)؛ والنقل يجب أن يحافظ على المقدار والاتجاه، لذا فالمحصلة المرسومة خطأ.', '["وضع ذيل الثاني عند رأس الأول هو الطريقة الصحيحة للجمع، وليس خطأً.","المحصلة تُرسم من ذيل المتجه الأول إلى رأس الثاني، وهذا ما فعله الطالب.","طول $\\boldsymbol{A}$ في رسم الطالب 4 مربعات كالأصل، فلم يتغير.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-11-18T12:34:59.234Z"}'::jsonb),
('mcq', 4, 2, 'ما يحدد المتجه مقداره واتجاهه، لا مكانه على الورقة؛ لذا يمكن نقله لوضع ذيله عند رأس متجه آخر دون أن يتغير، بشرط المحافظة على طوله واتجاهه.', '["مقدار المتجه يحدده طوله لا موضعه على الورقة.","النقل الصحيح لا يغيّر الاتجاه؛ تغيير الاتجاه ينتج متجهًا آخر.","","المحصلة تعتمد على اتجاهات المتجهات، ولهذا يجب المحافظة عليها عند النقل."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-11-18T12:34:59.234Z"}'::jsonb),
('mcq', 5, 0, 'المتجه $-\boldsymbol{d}_i$ له مقدار $\boldsymbol{d}_i$ واتجاه معاكس له، ويُنقل دون تغيير طوله أو اتجاهه؛ والذي يتغير هو موضع ذيله فقط، ليصبح عند رأس $\boldsymbol{d}_f$.', '["","موضع الذيل هو الشيء الوحيد الذي يتغير عند النقل؛ إذ ينتقل من نقطة الأصل إلى رأس $\\boldsymbol{d}_f$.","لا يتغير طول المتجه المنقول؛ تغييره يجعل الإزاحة المحسوبة خطأ.","لا يتغير اتجاه المتجه المنقول؛ فلو صار في اتجاه $\\boldsymbol{d}_f$ لأصبح الناتج جمعًا لا طرحًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-18T12:34:59.234Z"}'::jsonb),
('mcq', 6, 1, 'النقل يحافظ على المقدار والاتجاه، فيبقى المتجه 4.0 cm نحو الشمال الشرقي، ويتغير موضعه فقط.', '["الاتجاه لا يتغير بتغير المكان؛ فتغييره يُنتج متجهًا آخر.","","طول المتجه يمثل مقدار الكمية ولا علاقة له بمكانه على الورقة.","هذا الاتجاه المعاكس، أي المتجه السالب لا المتجه نفسه."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-11-18T12:34:59.235Z"}'::jsonb),
('mcq', 7, 2, 'نقل المتجه موازيًا لنفسه يغيّر موضعه (مكان الذيل والرأس) فقط، ويبقى طوله واتجاهه دون تغيير، فيظل يمثل الكمية نفسها.', '["النقل الموازي لا يغيّر الطول.","النقل الموازي يعني بقاء الاتجاه كما هو.","","لو تغيّر الطول والاتجاه لأصبح متجهًا مختلفًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (31%)"}],"at":"2026-11-18T12:34:59.235Z"}'::jsonb),
('essay', 1, null::int, null, null, 'يُسمح بنقل المتجه لأنه يتحدد بمقداره واتجاهه لا بموضعه على الورقة؛ فإذا بقي طوله واتجاهه كما هما بقي المتجه نفسه. والشرطان: المحافظة على طوله (مقداره) والمحافظة على اتجاهه. فإذا تغيّر أحدهما صار المتجه المنقول متجهًا آخر، فتكون المحصلة المرسومة من ذيل الأول إلى رأس الثاني خطأ.', '["المتجه يتحدد بالمقدار والاتجاه لا بالموضع","الشرط الأول: ثبات الطول","الشرط الثاني: ثبات الاتجاه","مخالفة الشرطين تجعل المحصلة خطأ"]'::jsonb, '[]'::jsonb, '[{"element":"سبب جواز النقل","marks":1},{"element":"الشرطان","marks":2},{"element":"أثر مخالفتهما","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"جميع العناصر صحيحة ومعللة"},{"level":"2–3 درجات","description":"الشرطان صحيحان مع نقص في التعليل"},{"level":"1 درجة","description":"شرط واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["ذكر ثبات الطول فقط","الاعتقاد أن موضع المتجه جزء من تعريفه"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-18T12:34:59.235Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) غيّر مقدار $-\boldsymbol{B}$ عند نقله (من 4 cm إلى 2 cm)، والنقل يجب أن يحافظ على المقدار والاتجاه، فأصبح يطرح متجهًا آخر. (ب) $\boldsymbol{A} + (-\boldsymbol{B})$ = 6 cm شرقًا + 4 cm غربًا = 2 cm شرقًا. (ج) يختار مقياس رسم أصغر يطبّقه على جميع المتجهات بالنسبة نفسها، أو ينقل المتجه إلى موضع آخر من الورقة مع الحفاظ على طوله واتجاهه.', '["الخطأ: تغيير طول المتجه المنقول","الناتج الصحيح 2 cm شرقًا","الحل: تصغير مقياس الرسم لكل المتجهات أو نقل صحيح"]'::jsonb, '["$\\boldsymbol{A} + (-\\boldsymbol{B})$: 6 cm شرقًا + 4 cm غربًا = 2 cm شرقًا"]'::jsonb, '[{"element":"تحديد الخطأ","marks":1},{"element":"الناتج الصحيح","marks":1},{"element":"الطريقة المقترحة","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"جميع العناصر صحيحة"},{"level":"2 درجتان","description":"عنصران صحيحان"},{"level":"1 درجة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["اعتبار الخطأ في عكس اتجاه $\\boldsymbol{B}$","اقتراح تصغير متجه واحد فقط"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-11-18T12:34:59.235Z"}'::jsonb),
('essay', 3, null::int, null, null, 'نعم، يمثلان الكمية المتجهة نفسها؛ لأن المتجه يتحدد بمقداره واتجاهه، وكلاهما متساويان، والاختلاف في الموضع فقط، أي أن أحدهما نسخة منقولة من الآخر. أما المتجه الثالث الذي له الطول نفسه لكن اتجاهه مختلف (مثلًا يعاكس اتجاههما أو يميل عنه) فلا يمثل الكمية نفسها؛ لأن الاتجاه جزء من تعريف الكمية المتجهة.', '["نعم يمثلان الكمية نفسها","التعليل: تساوي المقدار والاتجاه والموضع لا يؤثر","مثال متجه بالطول نفسه واتجاه مختلف","التعليل: الاتجاه جزء من تعريف المتجه"]'::jsonb, '[]'::jsonb, '[{"element":"الحكم والتعليل للمتجهين","marks":2},{"element":"المتجه الثالث وتعليله","marks":2}]'::jsonb, '[{"level":"4 درجات","description":"حكم صحيح ومثال صحيح مع التعليل"},{"level":"2–3 درجات","description":"حكم صحيح مع مثال غير معلل"},{"level":"1 درجة","description":"حكم صحيح دون تعليل"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن اختلاف الموضع يجعلهما متجهين مختلفين","اعتبار تساوي الطول كافيًا لتساوي المتجهين"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-18T12:34:59.235Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
join public.questions x on x.objective_id = (select id from public.objectives where code = 'P1-C2-L2-O17') and x.type = v.type and x.number = v.number
