select (select id from public.objectives where code = 'P1-C2-L2-O18'), v.type, v.number, v.stem, v.stimulus::jsonb, v.images::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'في كلٍّ من الرسوم الأربعة الآتية متجها إزاحة $\boldsymbol{A}$ و$\boldsymbol{B}$ ومتجه متقطع. في أيّ رسم يمثل المتجه المتقطع محصلة $\boldsymbol{A} + \boldsymbol{B}$ بطريقة صحيحة؟', null, '[{"src":"qimg/phys1/c2l2-o18-panels.svg","alt":"أربعة رسوم مرقمة. في الرسوم (1) و(2) و(3): متجه أخضر A أفقي نحو اليمين طوله 4 وحدات، ومن رأسه متجه أخضر B رأسي إلى أعلى طوله 3 وحدات. في (1) سهم متقطع من ذيل A إلى رأس B. في (2) سهم متقطع من رأس B إلى ذيل A. في (3) سهم متقطع أفقي تحت A يبدأ من تحت ذيل A نحو اليمين بطول 7 وحدات. في (4) A أفقي نحو اليمين وB رأسي إلى أعلى يبدآن من النقطة نفسها، وسهم متقطع من رأس A إلى رأس B."}]'::jsonb, '["الرسم (2)","الرسم (3)","الرسم (4)","الرسم (1)"]'::jsonb, 'تطبيق', 'اختيار رسم', 'متوسط', 'الكتاب ص 35 و37 — المحصلة على الرسم (الشكلان 2-8 و2-10)'),
('mcq', 2, 'مشى طالب من بيته شرقًا، ومُثّلت حركته بمتجهي الإزاحة في الشكل الآتي. ما محصلة إزاحته كما تُقرأ من الرسم؟', null, '[{"src":"qimg/phys1/c2l2-o18-scale1d.svg","alt":"شبكة مربعات، وتحتها «ضلع المربع يمثل 0.1 km» وسهم مكتوب بجانبه «شرق» يشير إلى اليمين. متجه أخضر A أفقي نحو اليمين طوله 6 مربعات، ومن رأسه مباشرة متجه أخضر B أفقي نحو اليمين طوله 3 مربعات."}]'::jsonb, '["0.3 km شرقًا","0.6 km شرقًا","0.9 km شرقًا","9 km شرقًا"]'::jsonb, 'تطبيق', 'قراءة رسم', 'سهل', 'الكتاب ص 35 — المحصلة (الشكل 2-8)'),
('mcq', 3, 'يبيّن الشكل الآتي إزاحتين متتاليتين: $\boldsymbol{A}$ ثم $\boldsymbol{B}$، حيث يبدأ $\boldsymbol{B}$ من رأس $\boldsymbol{A}$ (رُسم تحته قليلًا للوضوح). ما المحصلة؟', null, '[{"src":"qimg/phys1/c2l2-o18-opposite.svg","alt":"شبكة مربعات، وتحتها «ضلع المربع يمثل 5 m» وسهم مكتوب بجانبه «شرق» يشير إلى اليمين. متجه أخضر A أفقي نحو اليمين طوله 6 مربعات، وتحت رأسه بمربع واحد يبدأ متجه أخضر B أفقي نحو اليسار طوله مربعان، وخط رأسي متقطع قصير يصل رأس A ببداية B."}]'::jsonb, '["20 m شرقًا","40 m شرقًا","20 m غربًا","30 m شرقًا"]'::jsonb, 'تطبيق', 'قراءة رسم', 'متوسط', 'الكتاب ص 35 و37 — المحصلة على الرسم (الشكلان 2-8 و2-10)'),
('mcq', 4, 'يبيّن الشكل الآتي إزاحتين متتاليتين $\boldsymbol{A}$ ثم $\boldsymbol{B}$ مرسومتين بمقياس رسم 1 cm لكل 10 m (ضلع المربع 1 cm). إذا قيس بالمسطرة البعد بين النقطتين O وQ فكان 5.0 cm، فأيّ مما يأتي يحدد المحصلة؟', null, '[{"src":"qimg/phys1/c2l2-o18-2d.svg","alt":"شبكة مربعات وسهم إلى أعلى مكتوب عنده «شمال» وسهم إلى اليمين مكتوب عنده «شرق». النقطة O في أسفل اليسار، ومنها متجه أخضر A أفقي نحو اليمين طوله 3 مربعات ينتهي عند النقطة P، ومن P متجه أخضر B رأسي إلى أعلى طوله 4 مربعات ينتهي عند النقطة Q."}]'::jsonb, '["تمتد من Q إلى O، ومقدارها 50 m","تمتد من O إلى Q، ومقدارها 50 m","تمتد من O إلى Q، ومقدارها 70 m","تمتد من P إلى Q، ومقدارها 40 m"]'::jsonb, 'تطبيق', 'تعيين المحصلة', 'صعب', 'الكتاب ص 35 و37 — المحصلة على الرسم (الشكلان 2-8 و2-10)'),
('mcq', 5, 'في الجمع البياني لمتجهين بوضع رأس الأول ملامسًا لذيل الثاني، من أين يبدأ متجه المحصلة وأين ينتهي؟', null, null, '["يبدأ من رأس المتجه الأول، وينتهي عند ذيل المتجه الثاني","يبدأ من رأس المتجه الثاني، وينتهي عند ذيل المتجه الأول","يبدأ من ذيل المتجه الثاني، وينتهي عند رأس المتجه الثاني","يبدأ من ذيل المتجه الأول، وينتهي عند رأس المتجه الثاني"]'::jsonb, 'تذكر', 'قاعدة', 'سهل', 'الكتاب ص 35 — المحصلة (الشكل 2-8)'),
('mcq', 6, 'رُسمت إزاحتان متتاليتان على ورقة بمقياس رسم 1 cm لكل 20 m: الأولى سهم طوله 4.5 cm نحو الشمال، والثانية سهم طوله 1.5 cm نحو الجنوب يبدأ من رأس الأولى. ما المحصلة؟', null, null, '["120 m شمالًا","60 m جنوبًا","60 m شمالًا","3.0 m شمالًا"]'::jsonb, 'تطبيق', 'تعيين المحصلة', 'متوسط', 'الكتاب ص 35 و37 — المحصلة على الرسم (الشكلان 2-8 و2-10)'),
('mcq', 7, 'رسم طالب محصلة إزاحتين بوضع $\boldsymbol{B}$ بعد $\boldsymbol{A}$، ثم أعاد الرسم بوضع $\boldsymbol{A}$ بعد $\boldsymbol{B}$. كيف تكون المحصلة في الرسم الثاني مقارنة بالأول؟', null, null, '["لها المقدار نفسه والاتجاه نفسه","لها المقدار نفسه واتجاهها معاكس","مقدارها أكبر واتجاهها نفسه","مقدارها أصغر واتجاهها مختلف"]'::jsonb, 'تحليل', 'استنتاج', 'صعب', 'الكتاب ص 35 و37 — المحصلة على الرسم (الشكلان 2-8 و2-10)'),
('essay', 1, 'يبيّن الشكل الآتي ثلاث إزاحات متتالية $\boldsymbol{A}$ ثم $\boldsymbol{B}$ ثم $\boldsymbol{C}$ مرسومة بمقياس رسم: ضلع المربع 1 cm ويمثل 0.1 km.
(أ) صِف كيف تحدد متجه المحصلة على الرسم (من أين يبدأ وأين ينتهي).
(ب) كم مربعًا تتحرك المحصلة نحو الشرق ونحو الشمال؟
(ج) إذا قيس طول المحصلة بالمسطرة فكان 3.6 cm، فما مقدارها بالكيلومتر؟ وما اتجاهها التقريبي؟', null, '[{"src":"qimg/phys1/c2l2-o18-essay.svg","alt":"شبكة مربعات وسهم إلى أعلى مكتوب عنده «شمال» وسهم إلى اليمين مكتوب عنده «شرق». متجه أخضر A أفقي نحو اليمين طوله 4 مربعات، ومن رأسه متجه أخضر B رأسي إلى أعلى طوله 3 مربعات، ومن رأس B متجه أخضر C أفقي نحو اليسار طوله مربعان."}]'::jsonb, null, 'تطبيق', 'تعيين المحصلة وقراءتها', 'صعب', 'الكتاب ص 35 و37 — المحصلة على الرسم (الشكلان 2-8 و2-10)'),
('essay', 2, 'مشى طالب من بيته 0.6 km شرقًا، ثم عاد 0.2 km غربًا على الطريق نفسه. باستعمال مقياس رسم 1 cm لكل 0.1 km:
(أ) ما طول كل متجه على الرسم؟ وكيف يوضعان؟
(ب) حدّد المحصلة على الرسم، واحسب مقدارها واتجاهها.', null, null, null, 'تطبيق', 'رسم وحساب', 'متوسط', 'الكتاب ص 35 — المحصلة (الشكل 2-8)'),
('essay', 3, 'اكتب خطوات تحديد محصلة متجهين على الرسم وقراءة مقدارها واتجاهها، عندما يكون المتجهان مرسومين بمقياس رسم معلوم.', null, null, null, 'فهم', 'إجراء', 'سهل', 'الكتاب ص 35 — المحصلة (الشكل 2-8)')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
where not exists (select 1 from public.questions x where x.objective_id = (select id from public.objectives where code = 'P1-C2-L2-O18') and x.type = v.type and x.number = v.number);
insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 3, 'في الرسم (1) وُضع ذيل $\boldsymbol{B}$ عند رأس $\boldsymbol{A}$، والمتجه المتقطع يبدأ من ذيل $\boldsymbol{A}$ (المتجه الأول) وينتهي عند رأس $\boldsymbol{B}$ (المتجه الثاني)، وهذا تعريف المحصلة.', '["المتقطع يصل النقطتين الصحيحتين لكن اتجاهه معكوس؛ يبدأ من رأس $\\boldsymbol{B}$ وينتهي عند ذيل $\\boldsymbol{A}$.","المتقطع أفقي طوله مجموع الطولين (7 وحدات)، كأن المتجهين جُمعا جمعًا عدديًّا دون مراعاة اتجاهيهما.","المتجهان مرسومان من ذيل مشترك، والمتقطع يصل بين رأسيهما، فلا يمثل المحصلة بطريقة الرأس للذيل.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-11-18T12:34:59.236Z"}'::jsonb),
('mcq', 2, 2, 'المحصلة من ذيل $\boldsymbol{A}$ إلى رأس $\boldsymbol{B}$ طولها $6 + 3 = 9$ مربعات، وكل مربع يمثل 0.1 km، فهي $9 \times 0.1 = 0.9\ \text{km}$ شرقًا.', '["طرح طولي المتجهين بدل جمعهما مع أنهما في الاتجاه نفسه.","قرأ طول $\\boldsymbol{A}$ وحده، ولم يمد المحصلة إلى رأس $\\boldsymbol{B}$.","","عدّ المربعات صحيحًا لكنه أهمل مقياس الرسم (كل مربع 0.1 km لا 1 km)."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-18T12:34:59.236Z"}'::jsonb),
('mcq', 3, 0, 'المحصلة من ذيل $\boldsymbol{A}$ إلى رأس $\boldsymbol{B}$: 6 مربعات شرقًا ثم مربعان غربًا، فتنتهي على بُعد 4 مربعات شرق البداية، أي $4 \times 5 = 20\ \text{m}$ شرقًا.', '["","جمع الطولين (8 مربعات) متجاهلًا أن $\\boldsymbol{B}$ يتجه غربًا.","المقدار صحيح لكن المحصلة تتجه من ذيل $\\boldsymbol{A}$ إلى رأس $\\boldsymbol{B}$، أي نحو الشرق.","قرأ طول $\\boldsymbol{A}$ وحده (6 مربعات)."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (26%)"}],"at":"2026-11-18T12:34:59.236Z"}'::jsonb),
('mcq', 4, 1, 'المحصلة تبدأ من ذيل المتجه الأول $\boldsymbol{A}$ (النقطة O) وتنتهي عند رأس المتجه الثاني $\boldsymbol{B}$ (النقطة Q)، وطولها 5.0 cm يمثل $5.0 \times 10 = 50\ \text{m}$.', '["اتجاهها معكوس؛ المحصلة تتجه من ذيل الأول إلى رأس الثاني.","","جمع طولي المتجهين (3 + 4 = 7 cm) جمعًا عدديًّا مع أنهما متعامدان.","هذا المتجه $\\boldsymbol{B}$ نفسه لا المحصلة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (26%)"}],"at":"2026-11-18T12:34:59.236Z"}'::jsonb),
('mcq', 5, 3, 'متجه المحصلة يتجه دائمًا من ذيل المتجه الأول إلى رأس المتجه الثاني.', '["رأس الأول وذيل الثاني نقطة واحدة في هذه الطريقة، فلا يمكن أن يكون بينهما متجه.","هذا المتجه له طول المحصلة لكن اتجاهه معكوس.","هذا المتجه الثاني نفسه لا المحصلة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-11-18T12:34:59.236Z"}'::jsonb),
('mcq', 6, 2, 'المحصلة من ذيل الأولى إلى رأس الثانية طولها $4.5 - 1.5 = 3.0\ \text{cm}$ نحو الشمال، وتمثل $3.0 \times 20 = 60\ \text{m}$ شمالًا.', '["جمع الطولين (6.0 cm) متجاهلًا أن الإزاحة الثانية نحو الجنوب.","المقدار صحيح لكن رأس المحصلة يقع شمال ذيلها لأن الإزاحة الأولى أطول.","","قرأ طول المحصلة على الورقة بالسنتيمتر وكتبه بالمتر دون تطبيق مقياس الرسم."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-18T12:34:59.237Z"}'::jsonb),
('mcq', 7, 0, 'المحصلة تمثل مجموع الإزاحتين، وتغيير ترتيب الرسم ينقل كل متجه مع الحفاظ على مقداره واتجاهه، فتبدأ المحصلة من نقطة البداية نفسها وتنتهي عند النقطة نفسها: $\boldsymbol{A} + \boldsymbol{B} = \boldsymbol{B} + \boldsymbol{A}$.', '["","ترتيب الجمع لا يعكس الاتجاه؛ عكس الاتجاه يحدث عند تبديل ترتيب الطرح.","المتجهان لم يتغيرا في الطول أو الاتجاه، فلا يتغير مجموعهما.","المتجهان لم يتغيرا، فلا يتغير مقدار المحصلة ولا اتجاهها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-11-18T12:34:59.237Z"}'::jsonb),
('essay', 1, null::int, null, null, '(أ) تبدأ المحصلة من ذيل المتجه الأول $\boldsymbol{A}$ (نقطة البداية) وتنتهي عند رأس المتجه الأخير $\boldsymbol{C}$. (ب) نحو الشرق: $4 - 2 = 2$ مربعين، ونحو الشمال: 3 مربعات. (ج) $3.6 \times 0.1 = 0.36\ \text{km}$، واتجاهها بين الشمال والشرق (شمال شرق، أقرب إلى الشمال).', '["البداية ذيل $\\boldsymbol{A}$ والنهاية رأس $\\boldsymbol{C}$","مربعان شرقًا و3 مربعات شمالًا","المقدار 0.36 km","الاتجاه شمال شرق"]'::jsonb, '["شرقًا: $4 - 2 = 2$ مربعين","شمالًا: 3 مربعات","$3.6\\ \\text{cm} \\times 0.1\\ \\text{km/cm} = 0.36\\ \\text{km}$"]'::jsonb, '[{"element":"تعيين بداية المحصلة ونهايتها","marks":1},{"element":"حركة المحصلة شرقًا وشمالًا","marks":1},{"element":"المقدار","marks":1},{"element":"الاتجاه","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"جميع العناصر صحيحة"},{"level":"2–3 درجات","description":"التعيين صحيح مع خطأ في المقدار أو الاتجاه"},{"level":"1 درجة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["رسم المحصلة من ذيل $\\boldsymbol{A}$ إلى رأس $\\boldsymbol{B}$ فقط","جمع الأطوال 4 + 3 + 2 = 9 cm","إهمال مقياس الرسم"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (26%)"}],"at":"2026-11-18T12:34:59.237Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) المتجه الأول 6 cm نحو الشرق، والثاني 2 cm نحو الغرب، ويوضع ذيل الثاني عند رأس الأول. (ب) المحصلة تُرسم من ذيل المتجه الأول (البيت) إلى رأس الثاني، وطولها $6 - 2 = 4\ \text{cm}$ نحو الشرق، أي $4 \times 0.1 = 0.4\ \text{km}$ شرقًا.', '["طولا المتجهين 6 cm و2 cm","ذيل الثاني عند رأس الأول","المحصلة من ذيل الأول إلى رأس الثاني","0.4 km شرقًا"]'::jsonb, '["$0.6 / 0.1 = 6\\ \\text{cm}$، $0.2 / 0.1 = 2\\ \\text{cm}$","طول المحصلة $6 - 2 = 4\\ \\text{cm}$","$4 \\times 0.1 = 0.4\\ \\text{km}$ شرقًا"]'::jsonb, '[{"element":"أطوال المتجهين ووضعهما","marks":1},{"element":"تعيين المحصلة","marks":1},{"element":"المقدار والاتجاه","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"جميع العناصر صحيحة"},{"level":"2 درجتان","description":"عنصران صحيحان"},{"level":"1 درجة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["جمع الطولين 8 cm","كتابة المحصلة 4 cm دون تحويلها إلى km","إغفال الاتجاه"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-11-18T12:34:59.237Z"}'::jsonb),
('essay', 3, null::int, null, null, 'نرسم المتجه الأول بطوله واتجاهه وفق مقياس الرسم؛ ثم ننقل المتجه الثاني مع المحافظة على طوله واتجاهه بحيث يكون ذيله عند رأس الأول؛ ثم نرسم المحصلة من ذيل المتجه الأول إلى رأس المتجه الثاني؛ ثم نقيس طولها بالمسطرة ونضربه في مقياس الرسم لنحصل على مقدارها، ونصف اتجاهها بالاتجاه الذي يشير إليه رأسها.', '["وضع الثاني رأسًا لذيل","المحصلة من ذيل الأول إلى رأس الثاني","قياس الطول وضربه في المقياس","تحديد الاتجاه"]'::jsonb, '[]'::jsonb, '[{"element":"ترتيب المتجهين","marks":1},{"element":"رسم المحصلة","marks":1},{"element":"المقدار والاتجاه","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"خطوات كاملة ومرتبة"},{"level":"2 درجتان","description":"خطوتان صحيحتان"},{"level":"1 درجة","description":"خطوة واحدة"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["رسم المحصلة من رأس الثاني إلى ذيل الأول","نسيان مقياس الرسم"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-11-18T12:34:59.237Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
