select (select id from public.objectives where code = 'P1-C2-L2-O19'), v.type, v.number, v.stem, v.stimulus::jsonb, v.images::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'يبيّن الشكل الآتي الموقعين 1 و2 لعدّاء في نظامين إحداثيين مختلفين (a) و(b)، والاتجاه الموجب نحو اليمين في النظامين. ما موقعا العدّاء 1 و2 في النظام (b)؟', null, '[{"src":"qimg/phys1/c2l2-o19-two.svg","alt":"محوران أفقيان للموقع d بالمتر. المحور (a) في الأعلى مدرّج من 0 إلى 30 كل 5 m، ومكتوب تحت الصفر «نقطة الأصل». المحور (b) في الأسفل مدرّج من −30 إلى 0 كل 5 m، والصفر عند الطرف الأيمن. فوق كل محور نقطتان: النقطة 1 فوق التدريج 5 في (a) وفوق التدريج −25 في (b)، والنقطة 2 فوق التدريج 25 في (a) وفوق التدريج −5 في (b)."}]'::jsonb, '["$-25\\ \\text{m}$ و$-5\\ \\text{m}$","$+5\\ \\text{m}$ و$+25\\ \\text{m}$","$+25\\ \\text{m}$ و$+5\\ \\text{m}$","$-5\\ \\text{m}$ و$-25\\ \\text{m}$"]'::jsonb, 'فهم', 'قراءة رسم', 'متوسط', 'الكتاب ص 34–35 و37 — أثر اختيار النظام الإحداثي (الشكلان 2-7 و2-11، السؤالان 7 و8)'),
('mcq', 2, 'ركض عدّاء من شجرة إلى عمود إنارة يبعد عنها 20 m نحو اليمين. اختار طالب نقطة الأصل عند الشجرة، واختار آخر نقطة الأصل على بعد 5 m يسار الشجرة، والاتجاه الموجب نحو اليمين لكليهما. ما إزاحة العدّاء في كل نظام؟', null, null, '["$+20\\ \\text{m}$ في الأول و$+25\\ \\text{m}$ في الثاني","$+20\\ \\text{m}$ في النظامين","$+20\\ \\text{m}$ في الأول و$+15\\ \\text{m}$ في الثاني","صفر في الأول و$+5\\ \\text{m}$ في الثاني"]'::jsonb, 'فهم', 'مقارنة', 'سهل', 'الكتاب ص 34–35 و37 — أثر اختيار النظام الإحداثي (الشكلان 2-7 و2-11، السؤالان 7 و8)'),
('mcq', 3, 'إذا غيّرت موضع نقطة الأصل لمحور الموقع مع إبقاء الاتجاه الموجب كما هو، فأيّ مما يأتي يتغير عند وصف حركة جسم بين موقعين؟', null, null, '["مقدار إزاحة الجسم","اتجاه إزاحة الجسم","الفترة الزمنية للحركة","قيم مواقع الجسم وإشاراتها"]'::jsonb, 'فهم', 'مبدأ', 'سهل', 'الكتاب ص 34–35 و37 — أثر اختيار النظام الإحداثي (الشكلان 2-7 و2-11، السؤالان 7 و8)'),
('mcq', 4, 'تحرك جسم من النقطة A إلى النقطة B على محور الموقع في الشكل الآتي. إذا نُقلت نقطة الأصل إلى النقطة A مع بقاء الاتجاه الموجب نحو اليمين، فما موقعا A وB الجديدان؟', null, '[{"src":"qimg/phys1/c2l2-o19-mid.svg","alt":"محور أفقي للموقع d بالمتر مدرّج من −10 إلى 10 كل 2 m، ونقطة الأصل 0 في منتصفه. فوق المحور نقطة A عند −6 m ونقطة B عند 4 m."}]'::jsonb, '["A عند $-6\\ \\text{m}$، وB عند $+4\\ \\text{m}$","A عند 0 m، وB عند $+4\\ \\text{m}$","A عند 0 m، وB عند $+10\\ \\text{m}$","A عند 0 m، وB عند $-10\\ \\text{m}$"]'::jsonb, 'تطبيق', 'تطبيق مبدأ', 'متوسط', 'الكتاب ص 34–35 و37 — أثر اختيار النظام الإحداثي (الشكلان 2-7 و2-11، السؤالان 7 و8)'),
('mcq', 5, 'قارن طالبان متجهي الموقع اللذين رسماهما لتحديد موقع جسم متحرك في اللحظة نفسها، فوجدا أنهما لا يشيران إلى الاتجاه نفسه. ما التفسير الصحيح؟', null, null, '["أخطأ أحدهما؛ فمتجه الموقع للجسم في لحظة معيّنة واحد في أي نظام","اختار كل منهما نقطة أصل مختلفة، والجسم يقع بين النقطتين","رسم أحدهما متجه الموقع ورسم الآخر متجه الإزاحة","اختار كل منهما فترة زمنية مختلفة لقياس الموقع"]'::jsonb, 'تحليل', 'تفسير', 'صعب', 'الكتاب ص 37 — مراجعة 2-2 (السؤال 7)'),
('mcq', 6, 'اختيرت نقطة الأصل على بعد 4 m يسار شجرة، والاتجاه الموجب نحو اليمين. ما موقع جسم يقع على بعد 9 m يسار الشجرة؟', null, null, '["$+5\\ \\text{m}$","$-9\\ \\text{m}$","$-13\\ \\text{m}$","$-5\\ \\text{m}$"]'::jsonb, 'تطبيق', 'حساب موقع', 'سهل', 'الكتاب ص 35 — الموقع السالب (الشكل 2-7)'),
('mcq', 7, 'تتحرك سيارة في خط مستقيم من البقالة إلى مكتب البريد. اخترت نظامًا إحداثيًّا نقطة أصله البقالة، واختار زميلك نظامًا نقطة أصله مكتب البريد، والاتجاه الموجب لكليكما هو اتجاه حركة السيارة. فيمَ تتفقان؟', null, null, '["في الإزاحة والمسافة والفترة الزمنية، وتختلفان في المواقع","في المواقع والإزاحة، وتختلفان في المسافة","في جميع الكميات بما فيها المواقع","في المواقع فقط، وتختلفان في الإزاحة والمسافة"]'::jsonb, 'تحليل', 'مقارنة', 'صعب', 'الكتاب ص 37 — مراجعة 2-2 (السؤال 8)'),
('essay', 1, 'ركض عدّاء من الموقع 1 إلى الموقع 2. في النظام الإحداثي (a) نقطة الأصل على اليسار، فكان الموقعان $+5\ \text{m}$ و$+25\ \text{m}$. وفي النظام (b) نقطة الأصل عند الطرف الأيمن والاتجاه الموجب نحو اليمين أيضًا، فكان الموقعان $-25\ \text{m}$ و$-5\ \text{m}$.
(أ) احسب الإزاحة في كل نظام.
(ب) ماذا تستنتج عن أثر اختيار النظام الإحداثي في المواقع وفي متجه الإزاحة؟', null, null, null, 'فهم', 'حساب واستنتاج', 'متوسط', 'الكتاب ص 34–35 و37 — أثر اختيار النظام الإحداثي (الشكلان 2-7 و2-11، السؤالان 7 و8)'),
('essay', 2, 'تتحرك سيارة في خط مستقيم من البقالة إلى مكتب البريد الذي يبعد 400 m شرقها في 50 s. اخترتَ نظامًا إحداثيًّا نقطة أصله البقالة والاتجاه الموجب نحو الشرق، واختار زميلك نظامًا نقطة أصله مكتب البريد والاتجاه الموجب نحو الغرب (عكس حركة السيارة).
(أ) اكتب موقعي البداية والنهاية للسيارة في كل نظام.
(ب) احسب الإزاحة في كل نظام، وفسّر اختلاف إشارتها مع أنها تمثل السهم نفسه.
(ج) هل تتفقان على المسافة والفترة الزمنية؟ وضّح.', null, null, null, 'تحليل', 'مقارنة وتفسير', 'صعب', 'الكتاب ص 37 — مراجعة 2-2 (السؤال 8)'),
('essay', 3, 'قارن طالبان متجهي الموقع اللذين رسماهما على المخطط التوضيحي للحركة لتحديد موقع جسم في اللحظة نفسها، فوجدا أنهما يشيران إلى اتجاهين متعاكسين. فسّر ذلك، ثم بيّن هل سيختلف متجه الإزاحة الذي يرسمه كلٌّ منهما للجسم بين لحظتين.', null, null, null, 'فهم', 'تفسير', 'متوسط', 'الكتاب ص 37 — مراجعة 2-2 (السؤال 7)')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
