('mcq', 1, 0, 'نقطة الأصل في النظام (b) عند الطرف الأيمن، فالموقعان يقعان يسارها في الاتجاه السالب: الموقع 1 عند $-25\ \text{m}$ والموقع 2 عند $-5\ \text{m}$.', '["","هذان موقعاهما في النظام (a) الذي نقطة أصله على اليسار.","أهمل الإشارة السالبة مع أن الموقعين يقعان يسار نقطة الأصل.","بدّل بين الموقعين؛ الموقع 1 هو الأبعد عن نقطة الأصل في النظام (b)."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-11-18T12:34:59.238Z"}'::jsonb),
('mcq', 2, 1, 'نظام الطالب الذي اختار الشجرة: $\Delta\boldsymbol{d} = 20\ \text{m} - 0 = +20\ \text{m}$. نظام زميله: الموقعان 5 m و25 m، فتكون $\Delta\boldsymbol{d} = 25\ \text{m} - 5\ \text{m} = +20\ \text{m}$. فالإزاحة واحدة في النظامين؛ لأن تغيير نقطة الأصل غيّر المواقع ولم يغيّر الإزاحة.', '["أخذ الموقع النهائي في النظام الثاني على أنه الإزاحة.","","طرح 5 m من الإزاحة بدل طرح الموقع الابتدائي من النهائي.","خلط بين الموقع الابتدائي في كل نظام والإزاحة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (32%)"}],"at":"2026-11-18T12:34:59.238Z"}'::jsonb),
('mcq', 3, 3, 'الموقع يُقاس من نقطة الأصل، فتتغير قيمه وقد تتغير إشاراته عند تغيير نقطة الأصل؛ أما متجه الإزاحة فلا يتغير مقداره ولا اتجاهه، والفترة الزمنية لا تتأثر.', '["الإزاحة فرق بين موقعين، وتغيير نقطة الأصل يزيد الموقعين أو ينقصهما بالمقدار نفسه، فلا يتغير مقدارها.","اتجاه الإزاحة من موقع البداية إلى موقع النهاية، ولا يتأثر بمكان نقطة الأصل.","الفترة الزمنية فرق بين قراءتي ساعة، ولا علاقة لها بنقطة أصل محور الموقع.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-11-18T12:34:59.238Z"}'::jsonb),
('mcq', 4, 2, 'B تبعد عن A مسافة 10 m نحو اليمين، فعندما تصبح A نقطة الأصل يكون موقعها 0 m وموقع B $+10\ \text{m}$؛ والإزاحة $+10\ \text{m}$ في النظامين.', '["هذان الموقعان في النظام القديم قبل نقل نقطة الأصل.","غيّر موقع A فقط، وأبقى موقع B كما كان في النظام القديم.","","عكس إشارة موقع B، مع أن B تقع يمين A في الاتجاه الموجب."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-11-18T12:34:59.238Z"}'::jsonb),
('mcq', 5, 1, 'متجه الموقع ذيله عند نقطة الأصل ورأسه عند الجسم؛ فإذا اختار كل طالب نقطة أصل في جهة مختلفة من الجسم أشار المتجهان إلى اتجاهين مختلفين، مع أن الجسم في المكان نفسه.', '["متجه الموقع يعتمد على نقطة الأصل المختارة، فقد يختلف بين نظامين دون خطأ.","","كلاهما رسم متجه موقع في لحظة واحدة؛ والإزاحة تحتاج إلى موقعين.","المقارنة في اللحظة نفسها، فلا دخل للفترة الزمنية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (36%)"}],"at":"2026-11-18T12:34:59.239Z"}'::jsonb),
('mcq', 6, 3, 'الجسم يبعد $9 - 4 = 5\ \text{m}$ يسار نقطة الأصل، أي في الاتجاه السالب، فموقعه $-5\ \text{m}$.', '["المقدار صحيح لكن الجسم يقع يسار نقطة الأصل، فموقعه سالب.","قاس الموقع من الشجرة لا من نقطة الأصل.","جمع البعدين بدل طرحهما، وكأن نقطة الأصل يمين الشجرة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (32%)"}],"at":"2026-11-18T12:34:59.239Z"}'::jsonb),
('mcq', 7, 0, 'تغيير نقطة الأصل يغيّر قيم المواقع (في نظامك موجبة، وفي نظام زميلك سالبة تنتهي عند الصفر)، لكنه لا يغيّر الإزاحة مقدارًا واتجاهًا، ولا المسافة، ولا الفترة الزمنية.', '["","المواقع تختلف لاختلاف نقطة الأصل، والمسافة لا تتأثر بها.","المواقع تُقاس من نقطة الأصل، فتختلف قيمها في النظامين.","المواقع هي التي تختلف، والإزاحة والمسافة متفق عليهما."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (36%)"}],"at":"2026-11-18T12:34:59.239Z"}'::jsonb),
('essay', 1, null::int, null, null, '(أ) في (a): $\Delta\boldsymbol{d} = 25 - 5 = +20\ \text{m}$. في (b): $\Delta\boldsymbol{d} = -5 - (-25) = +20\ \text{m}$. (ب) اختيار النظام الإحداثي يغيّر قيم المواقع وإشاراتها (موجبة في (a) وسالبة في (b))، لكنه لا يغيّر مقدار متجه الإزاحة ولا اتجاهه؛ فالإزاحة 20 m نحو اليمين في الحالتين.', '["$+20\\ \\text{m}$ في (a)","$+20\\ \\text{m}$ في (b)","المواقع وإشاراتها تتغير","الإزاحة لا تتغير مقدارًا واتجاهًا"]'::jsonb, '["(a): $25 - 5 = +20\\ \\text{m}$","(b): $-5 - (-25) = -5 + 25 = +20\\ \\text{m}$"]'::jsonb, '[{"element":"حساب الإزاحتين","marks":2},{"element":"الاستنتاج عن المواقع","marks":1},{"element":"الاستنتاج عن الإزاحة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"حسابان صحيحان واستنتاج كامل"},{"level":"2–3 درجات","description":"خطأ في إشارة أحد الحسابين أو استنتاج ناقص"},{"level":"1 درجة","description":"حساب واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["حساب $-5 - (-25) = -30$","الاستنتاج أن الإزاحة سالبة في (b) لأن المواقع سالبة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-11-18T12:34:59.240Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) في نظامك: البداية 0 m والنهاية $+400\ \text{m}$. في نظام زميلك: البداية $+400\ \text{m}$ (البقالة تقع غرب مكتب البريد، أي في اتجاهه الموجب) والنهاية 0 m. (ب) في نظامك $\Delta\boldsymbol{d} = 400 - 0 = +400\ \text{m}$، وفي نظام زميلك $\Delta\boldsymbol{d} = 0 - 400 = -400\ \text{m}$. الإشارتان مختلفتان لأن الإشارة تدل على الاتجاه بالنسبة إلى الاتجاه الموجب المختار، أما متجه الإزاحة نفسه فواحد: 400 m نحو الشرق في الحالتين. (ج) نعم؛ المسافة 400 m والفترة الزمنية 50 s في النظامين، لأنهما كميتان قياسيتان لا تعتمدان على نقطة الأصل ولا على الاتجاه الموجب.', '["المواقع في النظامين","$+400\\ \\text{m}$ و$-400\\ \\text{m}$","متجه الإزاحة واحد: 400 m شرقًا","الاتفاق على المسافة 400 m والفترة 50 s"]'::jsonb, '["نظامك: $\\Delta\\boldsymbol{d} = 400 - 0 = +400\\ \\text{m}$","نظام زميلك: $\\Delta\\boldsymbol{d} = 0 - 400 = -400\\ \\text{m}$"]'::jsonb, '[{"element":"المواقع","marks":1},{"element":"الإزاحتان والتفسير","marks":2},{"element":"المسافة والفترة الزمنية","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"جميع العناصر صحيحة مع تفسير الإشارة"},{"level":"2–3 درجات","description":"حسابات صحيحة دون تفسير كافٍ للإشارة"},{"level":"1 درجة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["اعتبار موقع البقالة في نظام الزميل سالبًا","القول إن الإزاحة تغيّرت فعلًا لأن إشارتها تغيّرت","القول إن المسافة تختلف بين النظامين"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (36%)"}],"at":"2026-11-18T12:34:59.240Z"}'::jsonb),
('essay', 3, null::int, null, null, 'متجه الموقع ذيله عند نقطة الأصل ورأسه عند الجسم؛ فإذا اختار أحدهما نقطة الأصل يسار الجسم والآخر يمينه، أشار متجه الأول نحو اليمين ومتجه الثاني نحو اليسار، مع أن الجسم في المكان نفسه. أما متجه الإزاحة فلن يختلف؛ لأنه يُرسم من موقع البداية إلى موقع النهاية للجسم، وهما مكانان محددان لا يعتمدان على نقطة الأصل، فيكون له المقدار نفسه والاتجاه نفسه لدى الطالبين.', '["متجه الموقع يبدأ من نقطة الأصل","اختلاف نقطتي الأصل على جانبي الجسم يعكس الاتجاه","متجه الإزاحة لا يختلف","التعليل: يعتمد على موقعي البداية والنهاية فقط"]'::jsonb, '[]'::jsonb, '[{"element":"تفسير اختلاف متجهي الموقع","marks":2},{"element":"حكم الإزاحة مع التعليل","marks":2}]'::jsonb, '[{"level":"4 درجات","description":"تفسير صحيح وحكم معلل"},{"level":"2–3 درجات","description":"تفسير صحيح مع حكم غير معلل"},{"level":"1 درجة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن أحد الطالبين أخطأ","القول إن الإزاحة تختلف أيضًا لاختلاف المواقع"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (36%)"}],"at":"2026-11-18T12:34:59.240Z"}'::jsonb)
